// Each place's story and sustainability line in Indonesian, by place id.
// Translations of the records' own English text, made on 2026-10-05 under
// the same rules as story-ko.js (nothing added, every hedge kept, `of` is
// a hash of the English each was made from). Loaded only when the
// interface is in this language.
export const STORIES = {
  "balwoo": {"of": "2f1984dd", "story": "Balwoo Gongyang menyajikan masakan kuil Buddha Korea di lantai lima Templestay Information Center di Ujeongguk-ro, Jongno. Masakan kuil tidak menggunakan daging maupun ikan, dan menunya bertumpu pada hidangan set bertahap serta cita rasa fermentasi.", "esg": "Menggunakan fermentasi tradisional tanpa bahan tambahan buatan"},
  "sanchon": {"of": "d034be6c", "story": "Sanchon menyajikan masakan kuil Korea di sebuah hanok di Insadong-gil: hidangan set kuil yang terdiri dari sekitar dua puluh bagian — di antaranya bubur, sayuran gunung berbumbu, panekuk, nasi, dan rebusan — tanpa daging maupun ikan.", "esg": "Bahan dari sumber lokal yang dipetik langsung dari pegunungan Gangwon-do"},
  "osegyehyang": {"of": "a390e292", "story": "Osegyehyang memasak hidangan Korea-Tionghoa — jajangmyeon, jjamppong, hidangan asam manis — dalam versi vegan sepenuhnya yang dibuat dengan daging kedelai, di sebuah gang dekat Insadong. DiningCode mencantumkannya sebagai restoran vegan.", "esg": "Versi 100% nabati dari hidangan klasik Korea-Tionghoa yang akrab di lidah"},
  "plant-cafe": {"of": "b100057f", "story": "Plant Cafe & Kitchen adalah restoran vegan sekaligus kafe roti di Bogwang-ro, Itaewon; situsnya sendiri menyebutnya 100% vegan. Menunya mencakup bowl lentil dan bowl tempe serta burger hingga kue dari toko rotinya sendiri.", "esg": "Toko roti vegan milik sendiri yang memangkas rantai pasok susu dan telur"},
  "monks-butcher": {"of": "7ab2b513", "story": "Monk's Butcher menyebut dirinya restoran vegan kasual sekaligus bar anggur, di lantai tiga dan empat sebuah gedung di Itaewon-ro. Hidangan yang tercantum antara lain gangjeong (gorengan berbalut saus) 'ayam' tahu jeruk, pasta lemon hitam, dan bruschetta jamur bourguignon. DiningCode hanya mencantumkan hidangan vegan pada menunya.", "esg": "Protein nabati kelas atas yang menggantikan hidangan andalan toko daging"},
  "camouflage": {"of": "1c585de1", "story": "Camouflage menyajikan hidangan Amerika-Tionghoa yang dibuat tanpa produk hewani — bowl remah tahu, chow mein, nasi goreng — di lantai dua sebuah gedung dekat Itaewon-ro.", "esg": "Saus dan tekstur yang berani, yang membuat makan nabati terasa mudah"},
  "eid": {"of": "b03bc9c1", "story": "EID terletak di samping Masjid Pusat Seoul. Kantor pariwisata Seoul pernah menggambarkannya sebagai satu-satunya restoran Korea yang disertifikasi oleh Korea Muslim Federation, meskipun daftar sertifikat KMF sendiri untuk 2023–2026 tidak memuat entri untuknya. Tempat ini menyajikan masakan rumahan Korea seperti bibimbap dan bulgogi sapi.", "esg": "Dapur yang dikelola keluarga, menyajikan masakan rumahan Korea yang inklusif di dekat Masjid Pusat"},
  "kampungku": {"of": "264c5499", "story": "Kampungku — yang dalam bahasa Melayu berarti \"kampung saya\" — memadukan nasi lemak dan nasi goreng buatan seorang koki Malaysia dengan hidangan Korea berbahan halal seperti budae jjigae, beberapa langkah dari jalan-jalan belanja Myeongdong. Ruang salat di lantai tiga, yang dicatat secara terpisah oleh para pengunjung, menjadikannya tempat singgah yang ditunjukkan beberapa panduan makanan halal kepada wisatawan Muslim. Dapurnya menyebut dirinya ramah halal; tidak ada sertifikat yang kami lihat untuk menyebutnya lebih dari itu.", "esg": "Dapur seorang koki Muslim yang menjembatani meja makan Malaysia dan Korea, dengan ruang salat di tempat"},
  "nono-shop": {"of": "8dbaf056", "story": "Nono Shop & Cafe pindah dari Itaewon ke sebuah lokasi di samping Stasiun Hoehyeon pada pertengahan 2026, salah satu dari beberapa usaha kecil yang meninggalkan Itaewon ketika harga sewa naik. Dikelola oleh Julian — yang dikenal dari televisi Korea — tempat ini masih berupa kafe yang semua minuman dan hidangan penutup di menunya vegan, dipadukan dengan toko ritel nol sampah bagi orang yang sedang membangun kebiasaan berbelanja tanpa kemasan sekali pakai.", "esg": "Semua item menu vegan; ritel nol sampah berdampingan dengan kafe"},
  "ggot-epida": {"of": "0b1cd6bd", "story": "Kkotbap Epida Bukchon adalah restoran Korea di Bukchon dengan hidangan vegan pada menu campuran. Tempat ini juga menyajikan daging, termasuk babi, jadi tanyakan hidangan mana yang vegan.", "esg": "Inisiatif nol sampah yang berfokus pada pemanfaatan setiap bagian sayuran organik"},
  "maji": {"of": "b2a8acbb", "story": "Maji menyajikan menu Korea yang sepenuhnya nabati di Seochon, dekat Jahamun-ro. Belum ditemukan informasi halal apa pun tentang tempat ini, jadi menu nabati tidak boleh dibaca sebagai halal.", "esg": "Inklusivitas nabati dengan kecap asin fermentasi alami yang diperam lebih dari 3 tahun"},
  "iryonghal": {"of": "d1262d8a", "story": "Iryonghal Yangsik adalah kafe brunch yang mengutamakan sayuran di Guwol-dong, Incheon, yang oleh Blue Ribbon Survey dicantumkan sebagai 채식 위주 (terutama vegetarian). Ratatouille-nya adalah hidangan yang dilaporkan pengunjung sebagai vegan sepenuhnya; menu selebihnya mencakup ikan dan produk susu.", "esg": "Menu yang mengedepankan sayuran, dibangun dari hasil bumi lokal yang dimasak perlahan"},
  "rim": {"of": "e3875683", "story": "Rim dibuka pada 2019 di Gaehang-ro, Dongincheon, dengan nama 더 비기닝 (The Beginning), pindah ke Cheongna pada 2023, dan selama bertahun-tahun menjadi dapur vegan yang tercantum di Blue Ribbon, tempat tidak ada satu pun isi piring yang berasal dari hewan dan sausnya dibuat sendiri. Pada Juni 2026 tempat ini direnovasi menjadi prasmanan brunch dengan menu yang berganti setiap minggu. Hidangan nabati masih menjadi intinya, tetapi prasmanan itu tidak lagi khusus vegan: semur ayam bisa saja berada di meja saji yang sama dengan salad tahu. Hal ini patut Anda ketahui sebelum datang, apa pun pola makan Anda.", "esg": "Pada intinya dapur nabati, kini disajikan sebagai prasmanan yang berganti setiap minggu"},
  "meat-morning": {"of": "6a2a10d2", "story": "Namanya memainkan sebuah ironi yang ternyata hanya separuh benar: Meat Morning memanggang kue kering vegan dan menyiapkan mangkuk yoghurt Yunani yang membangun reputasinya di kalangan pelanggan tetap yang peduli kesehatan, tetapi etalasenya juga memuat cheesecake berbahan susu di samping keduanya. Vegan dan bukan vegan, berdampingan — patut Anda ketahui sebelum memesan hanya berdasarkan lencananya.", "esg": "Kue panggang yang mengedepankan vegan, sadar gula, dibuat dalam jumlah kecil setiap hari"},
  "arabesque": {"of": "22d6c59c", "story": "Arabesque dibuka pada 2003 dengan nama Sahara Ten, dan berganti nama menjadi Arabesque pada Agustus 2007 — menurut catatan Korea Tourism Organization sendiri tentang tempat ini. Dapurnya dipimpin koki India, pemiliknya orang Yordania, dan masakannya membentang dari kari India hingga kebab Turki, dihangatkan tandoor dan ramah halal, bukan bersertifikat resmi. Tempat ini telah menarik komunitas internasional Incheon — pedagang Timur Tengah, mahasiswa Asia Tenggara, dan warga setempat yang penasaran — selama lebih dari dua dasawarsa dengan satu nama atau nama lainnya.", "esg": "Lebih dari dua dasawarsa masakan India dan Turki yang ramah halal di satu dapur di Incheon"},
  "bombay-brau": {"of": "5adcf844", "story": "Bombay Brau adalah bagian dari jaringan restoran India dengan cabang dari Songdo hingga Busan, yang bertumpu pada masakan oven tandoori dan kari. Dapurnya tidak vegan, tetapi staf akan menunjukkan hidangan mana yang vegan. Status halal cabang ini tidak diketahui: satu-satunya pencantuman halal yang ditemukan berasal dari 2021 atau menggambarkan cabang lain, jadi tanyakan sebelum memesan.", "esg": "Meja makan yang ramah Muslim dan mengakomodasi vegetarian — tidak bersertifikat, tetapi sungguh menyambut"},
  "gonghwachun": {"of": "7ee18ecb", "story": "Jajangmyeon lahir di jalan ini: Gonghwachun yang asli dibuka di sini pada 1905 dan menyajikan jajangmyeon selama tiga generasi sebelum tutup pada 1983. Bangunannya masih berdiri sekitar 150 meter dari sini sebagai Museum Jajangmyeon, sebuah situs warisan nasional terdaftar, dan lahannya ditandai di peta sebagai Gonghwachun-teo — lokasi Gonghwachun. Restoran yang kini berdagang dengan nama itu adalah usaha terpisah yang mendaftarkan merek dagangnya pada 2002 dan dibuka pada 2004; keluarga pendiri mempersoalkan klaimnya sebagai yang asli. Datanglah untuk minya, lalu berjalanlah ke museum untuk sejarahnya.", "esg": "Menyajikan hidangan yang membesarkan jalan ini, di samping museum yang menjaga sejarahnya"},
  "yangwon": {"of": "386a3dc3", "story": "Yangwon adalah restoran barbeku bergaya Korea-Tionghoa yang berfokus pada daging domba di kawasan Cheongna, Incheon, yang menyajikan 양꼬치 (sate domba) dan 양갈비 (iga domba), dengan pilihan makan sepuasnya. Situs pariwisata Incheon sendiri dan pencantuman restoran ini di direktori sama-sama menggambarkan daging domba impornya sebagai bersertifikat halal, meskipun keduanya tidak menyebut lembaga yang mensertifikasi, dan tidak ada sumber yang membahas apakah dapurnya sendiri — permukaan persiapan, penyajian alkohol — memenuhi ketentuan halal di luar dagingnya.", "esg": "Klaim halal tentang asal dagingnya, bukan (belum) tentang dapurnya — patut ditanyakan langsung di tempat."},
  "manokamana-songdo": {"of": "7c20e4e3", "story": "Manokamana Songdo — \"Manokamana\" adalah kata bahasa Nepal untuk \"harapan\" — menyajikan ayam tandoori, butter chicken, dan naan di seberang Songdo Central Park, disiapkan oleh koki India dan Nepal dengan pengalaman lebih dari satu dasawarsa. Situs pariwisata kota Incheon menyebut namanya dalam sebuah ulasan tentang pilihan tempat makan halal dan ramah Muslim di kota itu, dan catatan seorang pengunjung menggambarkan papan tanda sertifikasi di pintu masuk — meskipun tidak ada sumber yang menjelaskan lembaga mana yang menerbitkannya atau tingkat sertifikasi apa yang dimilikinya.", "esg": "Disebut namanya dalam panduan tempat makan halal milik kota sendiri, meskipun sertifikasi di baliknya tidak dijelaskan di sumber mana pun."},
  "earthborn-vegan": {"of": "c8cfbc5a", "story": "Earthborn Vegan Bakery (지구본) adalah kafe roti vegan di BT Center, Songdo, yang membuat pound cake, madeleine, scone, dan brownies tahu dengan tepung gandum utuh dan tahu sebagai pengganti telur, produk susu, atau tepung rafinasi. Situs pariwisata Incheon menggambarkan produknya sebagai \"100% nabati\", dan pendirinya mengatakan kepada pers bahwa ia ingin membuat kue panggang yang \"bisa dimakan siapa saja tanpa khawatir\" — bagian dari kegiatan toko ini mendukung kampanye wadah guna ulang dan menyumbangkan sebagian hasil penjualannya kepada anak-anak dengan alergi makanan.", "esg": "Ikut serta dalam kampanye wadah guna ulang (용기내) di Korea dan menyumbangkan sebagian hasil penjualan kepada anak-anak dengan alergi makanan."},
  "legume": {"of": "fc1488f9", "story": "Koki Sung Si-woo membangun Légume dari kegemaran masa kecilnya pada sayuran, dan mengubahnya menjadi menu cicip yang tercantum di Michelin tanpa produk hewani sama sekali. Terselip di Sinsa Square di Gangnam-daero, restoran ini memperlakukan tradisi vegetarian Korea sebagai titik tolak santapan mewah, dengan menu bertahap yang berganti mengikuti musim.", "esg": "Dapur menu cicip yang dibangun tanpa produk hewani sama sekali"},
  "cosmos-shop": {"of": "57a886a1", "story": "Cosmos Shop memadukan menu brunch vegan yang ringkas dengan pojok bahan makanan berisi produk nabati, di sebuah unit lantai dasar dekat Seoul Forest. Kantor pariwisata Seoul sendiri mencantumkannya di antara tempat vegan terkemuka di Seongdong-gu, dan tempat ini pernah masuk peringkat di direktori HappyCow untuk tempat ramah vegan di kota ini.", "esg": "Konter bahan makanan berisi produk nabati di samping dapur"},
  "nammi-plant-lab": {"of": "d082ba1c", "story": "Nammi Plant Lab menjalankan menu Barat yang vegan sepenuhnya — piza, pasta, gnocchi, dan risotto — dari ruang makan penuh tanaman dekat Stasiun Sadang, di sisi Seocho di Gangnam selatan. Tempat ini juga menjual saus pasta buatannya sendiri untuk dibawa pulang.", "esg": "Menu Barat yang seluruhnya nabati dan cukup digemari tamu non-vegan sehingga perlu reservasi"},
  "glunic": {"of": "6b905da7", "story": "Glunic memanggang hidangan penutup bebas gluten dan vegan di sebuah toko kecil yang menghadap Seoul Forest. Setiap produk diberi label sesuai keadaannya yang sebenarnya — sebagian vegan, sebagian bebas gluten, sebagian keduanya — alih-alih dijual dengan satu klaim menyeluruh, termasuk kue kering vegan dan scone beras-tahu dengan krim tahu vanila.", "esg": "Memberi label setiap hidangan penutup sesuai keadaannya yang sebenarnya — vegan, bebas gluten, atau keduanya — alih-alih satu klaim menyeluruh"},
  "morococo": {"of": "b2c245d1", "story": "Morococo Cafe menyajikan tagine Maroko dan hidangan dengan nasi di sebuah teras di Haebangchon, di seberang jalan dari dapur Maroko lain di lingkungan itu. Menu cetaknya didominasi daging, tetapi pengunjung vegan di HappyCow melaporkan bahwa nasi, salad wortel, dan sebuah tagine kuskus dapat dipesan vegan atas permintaan, dengan feta vegan dan susu nabati yang tersedia.", "esg": "Menu yang didominasi daging tetapi tetap mengakomodasi pesanan vegan sepenuhnya atas permintaan"},
  "urt": {"of": "3f8dae9c", "story": "URT menyajikan menu roti dan brunch yang sepenuhnya nabati — jamur panggang kayu bakar, hummus kacang Jangdan, dan pad thai termasuk hidangan yang disebut dalam pencantuman direktori — dari sebuah ruang yang tenang di Seogyo-dong. HappyCow mengategorikannya sebagai tempat 100% vegan; kami belum melihat pernyataan dari pengelolanya sendiri.", "esg": "Dapur vegan sepenuhnya yang dibangun dari bahan musiman organik dan ramah lingkungan"},
  "persian-palace": {"of": "96a0d26d", "story": "Koki asal Iran, Shapour, yang datang ke Korea sebagai mahasiswa pada 1990, membuka Persian Palace pada 2002 di sebuah gang sempit dekat Sungkyunkwan University. Tempat ini menyajikan kebab kobideh, kari, dan es krim safron, dengan skala kepedasan rancangan pemiliknya sendiri. Direktori halal mencantumkannya sebagai bersertifikat, meskipun proyek ini belum melihat sertifikatnya, dan sebuah blog kuliner mencatatnya sebagai milik Muslim.", "esg": "Lebih dari dua dasawarsa masakan Persia milik Muslim yang dikelola mandiri di dekat Sungkyunkwan University"},
  "halal-busan-jib": {"of": "86498a4f", "story": "Beroperasi dengan nama BUSANJIB KBBQ, Busan Jib KBBQ di Myeongdong ini adalah salah satu dari beberapa cabang ramah Muslim di bawah merek halal Busan Jib — sebuah lokasi BSJ Chicken & WOK yang terpisah berada di dekatnya di Myeongdong 9-gil, dan cabang-cabang lain beroperasi di Hongdae. Pencantuman Google Business milik pengelolanya sendiri menggambarkannya sebagai restoran barbeku Korea bersertifikat halal yang menyajikan cita rasa Korea sejak 1987, meskipun proyek ini sendiri belum melihat sertifikatnya.", "esg": "Dapur barbeku Korea halal yang beroperasi di bawah kelompok kecil restoran ramah Muslim dengan beberapa cabang"},
  "busan-jib-hongdae": {"of": "c7ad54e0", "story": "Busan Jib KBBQ Hongdae, dengan nama BUSANJIB KBBQ, berbagi gedung dengan BSJ Chicken di Eoulmadang-ro dekat Hongik University, bagian dari kelompok kecil restoran Korea halal yang sama dengan cabang-cabang Myeongdong. Pencantuman milik pengelolanya sendiri untuk lantai ayam menggambarkannya sebagai bersertifikat halal, meskipun proyek ini sendiri belum melihat sertifikatnya.", "esg": "Gerai kedua di Seoul dari sebuah kelompok kecil restoran Korea halal, kali ini di dekat Hongik University"},
  "vegan-kitchen-myeongdong": {"of": "fc100603", "story": "Vegan Kitchen menyusun menunya dari pengganti berbahan kedelai untuk setiap hidangan yang bernama daging — dari poke bowl hingga \"kotlet babi\" kedelai (돈가스) — sebuah penggantian yang dikonfirmasi oleh profil direktori tentang menu tempat itu sendiri. HappyCow mengategorikannya sebagai restoran Korea vegan dan halal bersertifikat, meskipun proyek ini sendiri belum melihat sertifikat halalnya; bio Instagram pengelolanya sendiri menggambarkannya lebih sederhana sebagai \"tempat vegetarian terbaik\".", "esg": "Menu yang seluruhnya berbahan pengganti kedelai di jantung Myeongdong, dikategorikan HappyCow sebagai vegan sekaligus halal"},
  "hajj-korea-halal-food": {"of": "a8a41df1", "story": "Dikelola oleh sebuah keluarga Muslim, HAJJ Korea Halal Food menyajikan hidangan Korea halal seperti bulgogi dan bibimbap di jalan Usadan-ro yang sama dengan beberapa restoran halal lain di lingkungan itu. Direktori halal menggambarkannya sebagai bersertifikat halal, meskipun proyek ini belum melihat sertifikatnya.", "esg": "Dapur Korea halal yang dikelola keluarga di Usadan-ro, dekat kawasan Masjid Pusat Seoul"},
  "cherry-garden-dongdaemun": {"of": "98f86916", "story": "Dibuka oleh Lee Yeon-sil setelah 25 tahun tinggal di Singapura, Cherry Garden menyiapkan set Korea vegan dan bahan halal yang disiapkan terpisah di samping menu regulernya, sehingga tamu vegan dan Muslim tidak perlu mengajukan permintaan khusus. Situs pariwisata resmi Seoul mencantumkannya sebagai tempat yang menyajikan masakan Korea halal dengan pilihan vegan; proyek ini belum melihat sertifikat halalnya.", "esg": "Dapur Korea dekat Dongdaemun yang dirancang khusus untuk melayani tamu vegan dan halal bersama semua tamu lainnya"},
  "vege-green": {"of": "1fc3bb9a", "story": "Vege Green adalah prasmanan vegan swalayan di Gaepo-dong, Gangnam. HappyCow mencantumkannya dalam kategori vegan ketat dan menyatakan dengan lugas bahwa semua yang disajikannya vegan; pencantuman DiningCode menggambarkan sajian yang seluruhnya nabati, yang bertumpu pada pengganti berbahan kedelai untuk hidangan Korea, Tionghoa, dan Jepang. Stasiun kereta bawah tanah terdekat, Guryong di Jalur Suin-Bundang, berjarak sekitar 31 menit berjalan kaki.", "esg": "Prasmanan yang sudah lama berjalan dan seluruhnya nabati, bukan menu dengan tambahan vegan."},
  "le-vege-wang-yeouido": {"of": "815dc819", "story": "Le Vege Wang Yeouido berada di basemen TP Tower, dua menit berjalan kaki dari Stasiun Yeouido, menyajikan menu poke dan salad yang terbagi antara mangkuk vegan (tahu dan tempe) dan mangkuk lain yang berbahan utama udang atau protein non-vegan lainnya.", "esg": "Jalur vegan berlabel jelas pada menu yang selebihnya campuran, berguna untuk makan cepat di dekat Majelis Nasional."},
  "chick-peace-seongsu": {"of": "e4c61ab9", "story": "Chick Peace Seongsu menyajikan salad dan mangkuk Mediterania tidak jauh berjalan kaki dari Stasiun Seongsu, dengan falafel, hummus, dan sebuah salad vegan pada menu yang sama dengan salad ayam, bakso domba, dan shakshuka ayam.", "esg": "Satu salad vegan yang spesifik dan bernama pada menu Mediterania campuran — bukan klaim vegan menyeluruh."},
  "nimat-incheon-airport-t2": {"of": "b93139c5", "story": "Nimat adalah konter masakan Korea di dalam Culinary Square, pujasera di sisi timur lantai empat Terminal 2. Direktori tempat makan milik Bandara Incheon sendiri menggambarkannya sebagai restoran ramah Muslim yang menyajikan hidangan berbahan halal dalam panci panas. Konter lain di pujasera yang sama menjual hidangan babi, jadi pesanlah di konter Nimat itu sendiri. Tidak ada sertifikat yang kami lihat.", "esg": "Sudut pujasera yang dibuka pada 2024, bukan gerai bersertifikat berusia satu dasawarsa yang digambarkan pers pada 2015 — patut ditanyakan langsung kepada staf tentang sertifikasi saat ini."},
  "rindu-alam-ansan": {"of": "67b02347", "story": "Rindu Alam menyajikan masakan Indonesia dari sebuah unit lantai dua di Damunhwa-gil, bagian dari jalan kuliner multikultural Wongok-dong, Ansan, di seberang Stasiun Ansan. Tempat ini muncul dalam daftar restoran ramah Muslim di provinsi tersebut milik Gyeonggi Tourism Organization sendiri, meskipun tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim milik Provinsi Gyeonggi sendiri"},
  "hursheda-samarkand-ansan": {"of": "5317b3f0", "story": "Hursheda Samarkand menyajikan masakan Uzbek dari sebuah unit lantai dasar di Damunhwa2-gil, di jalan kuliner multikultural Wongok-dong, Ansan. Tempat ini muncul dalam daftar restoran ramah Muslim di provinsi tersebut milik Gyeonggi Tourism Organization sendiri, meskipun tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim milik Provinsi Gyeonggi sendiri"},
  "batavia-ansan": {"of": "de1b14e3", "story": "Batavia menyajikan masakan Indonesia dari sebuah unit lantai dua di Damunhwa-gil, di pintu masuk jalan kuliner multikultural Wongok-dong, Ansan. Tempat ini muncul dalam daftar restoran ramah Muslim di provinsi tersebut milik Gyeonggi Tourism Organization sendiri, meskipun tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim milik Provinsi Gyeonggi sendiri"},
  "imperia-chaihana-ansan": {"of": "2059b553", "story": "Imperia Chaihana menyajikan masakan Uzbek dari sebuah unit lantai dasar di Damunhwa2-gil, di jalan kuliner multikultural Wongok-dong, Ansan. Tempat ini muncul dalam daftar restoran ramah Muslim di provinsi tersebut milik Gyeonggi Tourism Organization sendiri, meskipun tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim milik Provinsi Gyeonggi sendiri"},
  "new-taj-mahal-ansan": {"of": "8cd93a56", "story": "New Taj Mahal menyajikan masakan India dari sebuah unit lantai dasar di Damunhwa1-gil, di jalan kuliner multikultural Wongok-dong, Ansan. Tempat ini muncul dalam daftar restoran ramah Muslim di provinsi tersebut milik Gyeonggi Tourism Organization sendiri, meskipun tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim milik Provinsi Gyeonggi sendiri"},
  "alyamani-corner-ongnyeon": {"of": "4bf6c0c4", "story": "Perdagangan ekspor mobil bekas di Ongnyeon-dong telah menarik pembeli Timur Tengah ke lingkungan itu selama bertahun-tahun, dan restoran halal tradisional pun dibuka untuk melayani mereka, Alyamani Corner salah satunya. Sebuah surat kabar daerah menggambarkannya sebagai restoran halal tradisional Yaman.", "esg": "Dapur halal yang dikelola orang Yaman, melayani komunitas Timur Tengah yang tumbuh di sekitar perdagangan ekspor mobil bekas Ongnyeon-dong"},
  "chahororok": {"of": "da8e82de", "story": "Chahororok menyajikan hidangan set berisi nasi yang dimasak dalam daun teratai, dalam bambu, atau bersama tumbuhan liar, disertai lauk pendamping masakan kuil, dari ruang makan kecil khusus reservasi dekat Stasiun Yeongdeungpo-gu Office. DiningCode mengategorikannya dalam \"vegan\" sekaligus \"masakan kuil\", dan menu tehnya — bubur labu, teh jujube — tersedia berdampingan dengan hidangan set. Dapurnya menyiapkan set sesuai pesanan, sehingga pemesanan tempat lebih dahulu diperlukan.", "esg": "Dapur masakan kuil yang dijalankan satu orang, membuat set nasi dan lauk sesuai pesanan, bukan disiapkan sebelumnya"},
  "poet-room": {"of": "f6aa4993", "story": "Poet Room menempati bekas bengkel kayu yang dialihfungsikan di distrik seni dan bengkel logam Mullae, mempertahankan cangkang betonnya dan mengisinya dengan buku serta seekor kucing penghuni. Di samping kopi dan cheesecake regulernya, DiningCode mencantumkan satu set kue kering vegan dan teh \"no milk\" tanpa susu, serta mengategorikan kafe itu sendiri sebagai vegan.", "esg": "Bengkel kayu berusia puluhan tahun yang digunakan kembali, dengan minuman tanpa susu dan satu set kue kering vegan pada menu reguler"},
  "aseungji": {"of": "f708b050", "story": "Aseungji memadukan hidangan bertahap masakan kuil yang 100% berdasarkan reservasi dengan toko roti yang menjual roti dari tepung beras sebagai pengganti gandum, tanpa mentega, telur, produk susu, atau gula tambahan. DiningCode mengategorikan seluruh pencantuman itu sebagai vegan dan masakan kuil. Hidangan bertahap malam berharga hingga 70.000 won dan perlu dipesan lebih dahulu; toko rotinya memiliki jam buka tersendiri yang lebih pendek untuk tamu tanpa reservasi.", "esg": "Toko roti tepung beras yang menghindari gandum, produk susu, dan telur, di samping hidangan bertahap masakan kuil yang 100% berdasarkan reservasi"},
  "daddys-lamb-hapjeong": {"of": "3af92279", "story": "Daddy's Lamb Steakhouse menyajikan iga domba segar dan sup domba tidak jauh berjalan kaki dari Stasiun Hapjeong. Situs pariwisata resmi Seoul mencatat bahwa dapurnya hanya menggunakan daging domba muda bersertifikat halal — sebuah klaim tentang asal dagingnya, bukan tentang dapur yang bersertifikat, dan tidak ada sertifikat yang kami lihat untuk catatan proyek ini."},
  "veginarang-sinchon": {"of": "116eb0b6", "story": "Veginarang Sinchon adalah cabang kecil dari sebuah restoran vegan masakan kuil, yang menyajikan hidangan seperti kotlet kedelai beras hitam dan yukgaejang sayuran yang dibuat dengan bahan dalam negeri. Pencantumannya menggambarkan tempat ini tidak memakai lima sayuran berbau tajam yang secara tradisional dihindari dalam masakan kuil Korea, dan menjalankan meditasi harian.", "esg": "Dapur masakan kuil: tanpa daging, tanpa lima sayuran berbau tajam (오신채), sebagai praktik rumah ini dan bukan menu campuran."},
  "slunch-factory-hongdae": {"of": "0e77cee6", "story": "Slunch Factory Hongdae meracik hidangan berinspirasi Italia dan Korea — gnocchi bayam, risotto jamur — dengan pilihan nabati yang ditandai jelas di samping pilihan lakto-vegetarian dan pescatarian, alih-alih menjalankan dapur yang vegan sepenuhnya."},
  "gosame-sinchon": {"of": "cff21ed8", "story": "Gosame Sinchon menyajikan masakan rumahan Korea — ikan makerel panggang, tumis cumi, sup tahu lembut — dari dapur yang oleh sebuah pencantuman panduan wisata digambarkan sama sekali tidak menggunakan babi dan alkohol. Kami belum melihat sertifikat halal untuk cabang ini."},
  "yeongmi-gimbap": {"of": "b56c9f9d", "story": "Yeongmi Gimbap, tepat di luar gerbang depan Ewha Womans University, menyediakan gimbap vegan pada menu regulernya di samping jajaran lengkap gimbap dan hidangan minya — ham, kue ikan, dan kepiting imitasi ditiadakan, sedangkan telur dan isian non-vegan lainnya tetap tidak berubah pada menu selebihnya."},
  "kervan-itaewon": {"of": "83ebade7", "story": "Kervan Restaurant Itaewon menyajikan hidangan Turki seperti kebab dan pide dari lantai satu Hyemun Building di Itaewon-ro. Situs pariwisata resmi Seoul menggambarkannya menggunakan bahan bersertifikat halal, dan sebuah ulasan tahun 2026 tentang restoran ini mengulang gambaran bersertifikat halal yang sama, meskipun proyek ini sendiri belum melihat sertifikatnya.", "esg": "Dapur Turki ramah halal di Itaewon-ro, di gedung yang juga ditempati restoran lain yang menyajikan makanan halal"},
  "dubai-restaurant-itaewon": {"of": "9486607b", "story": "Dubai Restaurant menyajikan masakan Timur Tengah dari 192 Itaewon-ro, di jalan yang sama dengan beberapa restoran lain yang menyajikan makanan halal di lingkungan itu, dekat Pintu Keluar 3 Stasiun Itaewon. Sebuah direktori halal mencatat bahwa staf restoran telah memberikan jaminan lisan tentang status halalnya, meskipun proyek ini sendiri belum melihat sertifikatnya.", "esg": "Dapur Timur Tengah ramah halal di Itaewon-ro, dekat Stasiun Itaewon"},
  "sultan-kebab-itaewon": {"of": "526ed04b", "story": "Sultan Kebab menjual kebab Turki dari sebuah kios di Bogwang-ro dekat Stasiun Itaewon. Situs pariwisata resmi Seoul menggambarkannya sebagai salah satu tujuan makanan halal yang mewakili Itaewon, dan sebuah ulasan pelanggan di situs direktori restoran Korea secara terpisah mencatat bahwa tempat ini menggunakan bahan halal; proyek ini sendiri belum melihat sertifikat halalnya.", "esg": "Kios kebab Turki ramah halal di Bogwang-ro, beberapa langkah dari Stasiun Itaewon"},
  "vegetus-haebangchon": {"of": "cca4077e", "story": "Vegetus menjalankan dapur nabati di Haebangchon, dengan jalan menanjak dari Stasiun Noksapyeong. Sebuah platform pencarian restoran Korea menggambarkannya sebagai restoran khusus vegetarian yang sama sekali tidak menggunakan bahan hewani, dengan pilihan bebas gluten pada sebagian menunya.", "esg": "Dapur yang sepenuhnya nabati di Haebangchon dengan pilihan menu bebas gluten"},
  "yang-good": {"of": "523931b2", "story": "Yang Good memanggang daging domba dan ayam ala Korea di Yeoksam-dong, menggunakan daging domba Australia yang disebutnya bersertifikat halal. Direktori restoran halal mencantumkannya sebagai ramah Muslim dan tanpa babi — kunjungan seorang pemeriksa sendiri mendapati dapurnya halal dan dokumen halal dipajang — tetapi tidak satu pun dapat menyebut lembaga yang mensertifikasi, jadi tidak ada sertifikat yang kami lihat untuk restoran itu sendiri. Tempat ini memanggang hingga malam dari Senin sampai Sabtu dan tutup pada hari Minggu.", "esg": "Mendapatkan daging dombanya secara khusus sebagai daging Australia bersertifikat halal, bukan impor generik."},
  "plantude-coex": {"of": "209b9e1c", "story": "Plantude COEX adalah restoran vegan yang dioperasikan Pulmuone Food&Culture di basemen Starfield COEX Mall. Ruang berita Pulmuone sendiri menggambarkannya sebagai restoran bersertifikat vegan pertama di antara perusahaan makanan besar Korea, disertifikasi oleh Vegan Standard Certification Institute — sertifikasi yang mengaudit peralatan dapur dan lingkungan memasak, bukan hanya bahan-bahannya. Menunya mengubah hidangan rumahan Korea dan Barat menjadi nabati, termasuk bibimbap, tteokbokki, dan hidangan mi tahu.", "esg": "Sertifikasi vegannya mencakup peralatan dapur dan lingkungan memasak, bukan hanya bahan-bahannya."},
  "kervan-coex": {"of": "0effea6b", "story": "Kervan Turkish Restaurant COEX menyajikan kebab Turki, pide, dan mezze di basemen Starfield COEX Mall. Situs pariwisata resmi Seoul mencantumkannya di antara restoran \"Halal Certified\" di kota ini dan menyebut Korea Muslim Federation sebagai lembaga yang mensertifikasi, dengan alamat dan nomor telepon yang cocok dengan pencantuman restoran itu sendiri — tetapi kami belum melihat nomor sertifikatnya, jadi di sini tempat ini dicatat sebagai ramah Muslim, bukan bersertifikat.", "esg": "Salah satu dari sedikit restoran yang disebut situs pariwisata Seoul sendiri sebagai bersertifikat halal KMF, bukan hanya pernyataan sendiri."},
  "chick-peace-sinsa": {"of": "f396fc09", "story": "Chick Peace Sinsa, dekat Garosu-gil, menyajikan hidangan Mediterania — hummus, falafel, roti pita, dan salad racikan sendiri — di samping pilihan daging. Menunya memuat satu salad vegan khusus berbahan utama kacang arab, dan hidangan dapat diminta dalam gaya vegan; menu yang lebih luas juga mencakup daging, jadi ini berarti ada pilihan vegan, bukan dapur yang sepenuhnya nabati.", "esg": "Mempertahankan satu salad vegan khusus pada menu yang selebihnya menyajikan daging, alih-alih memperlakukan hidangan nabati sebagai pelengkap belakangan."},
  "bium-cheongdam": {"of": "572202d3", "story": "Bium menyajikan hidangan bertahap Korea berharga tetap di dekat Cheongdam, yang dibangun di atas prinsip masakan kuil Buddha. Michelin Guide menggambarkannya menyajikan \"hidangan yang bebas dari daging, ikan, bawang putih, dan bawang bombai, sesuai dengan prinsip monastik\", dan kokinya memanfaatkan pelatihan masakan kuil untuk membangun rasa dari sayuran dan pasta fermentasi yang diperam lama sebagai pengganti bahan hewani. Tempat ini hanya menawarkan satu hidangan bertahap makan siang dan satu makan malam, tanpa menu à la carte, dan tutup pada hari Minggu dan Senin.", "esg": "Menggunakan pasta fermentasi yang diperam dari enam bulan hingga lebih dari lima tahun sebagai pengganti kaldu berbahan daging atau makanan laut."},
  "star-samarkand-dongdaemun": {"of": "4526821a", "story": "Star Samarkand terletak di Jalan Asia Tengah di Gwanghui-dong dekat Stasiun Dongdaemun History & Culture Park, menyajikan hidangan Uzbek seperti palov dan shashlik. Situs pariwisata resmi Seoul mencantumkannya di antara sekumpulan restoran pilihan di jalan itu yang tidak menjual alkohol dan memiliki juru masak Muslim, meskipun tidak ada lembaga sertifikasi yang disebut dan proyek ini belum melihat sertifikat halalnya.", "esg": "Salah satu dari beberapa dapur di Jalan Asia Tengah yang ditandai situs pariwisata Seoul sebagai tidak menjual alkohol dan memiliki juru masak Muslim di antara stafnya"},
  "samarkand-city-dongdaemun": {"of": "824ebd9c", "story": "Samarkand City terletak di lantai dua sebuah gedung di Jalan Asia Tengah di Gwanghui-dong, sepuluh meter dari Star Samarkand. Situs pariwisata resmi Seoul mencantumkannya di antara sekumpulan restoran pilihan yang sama di jalan itu yang tidak menjual alkohol dan memiliki juru masak Muslim, meskipun tidak ada lembaga sertifikasi yang disebut dan proyek ini belum melihat sertifikat halalnya. Tempat ini tutup pada hari Rabu pertama dan ketiga setiap bulan.", "esg": "Satu lagi dapur di Jalan Asia Tengah yang ditandai situs pariwisata Seoul sebagai tidak menjual alkohol dan memiliki juru masak Muslim di antara stafnya"},
  "tashkent-kebab-dongdaemun": {"of": "95cac907", "story": "Tashkent Kebab menyajikan doner dan kebab ikan yang digambarkan situs pariwisata resmi Seoul sebagai \"sangat langka di Seoul\", dari sebuah gerai di Jalan Asia Tengah di Gwanghui-dong yang buka hingga lewat tengah malam hampir setiap malam. Entri yang sama di situs pariwisata itu menandainya sebagai tidak menjual alkohol dan memiliki juru masak Muslim, meskipun tidak ada lembaga sertifikasi yang disebut dan proyek ini belum melihat sertifikat halalnya.", "esg": "Konter kebab di Jalan Asia Tengah yang ditandai situs pariwisata Seoul sebagai tidak menjual alkohol dan memiliki juru masak Muslim di antara stafnya"},
  "vegan-insa": {"of": "8fbdae96", "story": "Vegan Insa menempati sebuah hanok berusia seabad yang telah direnovasi di Ikseon-dong, menyajikan menu yang sepenuhnya nabati dan bertumpu pada hidangan pokok Korea — bibimbap, tteokbokki, japchae — di samping beberapa hidangan internasional. HappyCow mencantumkannya sebagai restoran khusus vegan, bukan dapur campuran dengan pilihan vegan.", "esg": "Dapur Korea yang sepenuhnya nabati, beroperasi di sebuah hanok berusia seabad yang dilestarikan"},
  "gosari-express": {"of": "fffd6a78", "story": "Gosari Express adalah kedai mi vegan dekat pasar sentral Stasiun Sindang, bagian dari merek restoran pertama perusahaan rintisan pangan Baekaerot. Dapurnya bertumpu pada saus minyak pakis (gosari) andalannya, yang dipakai pada mi bibim, nasi mentega, dan krep cabai ala Taiwan. Michelin Guide dan DiningCode sama-sama mengategorikan seluruh menunya sebagai vegan.", "esg": "Kedai mi vegan berkonsep satu hidangan yang menyatakan sebagian keuntungannya mendanai penghijauan kembali hutan"},
  "saffron-myeongdong": {"of": "351ad5e6", "story": "Saffron menyajikan masakan Arab dan Timur Tengah dari lantai 2 Lotte City Hotel Myeongdong. Kantor pariwisata Seoul sendiri mencantumkannya di antara restoran ramah Muslim di kota ini dan menyatakan bahwa tempat ini hanya menggunakan daging yang disembelih menurut hukum Islam, meskipun kami belum melihat lembaga sertifikasi maupun sertifikatnya. DiningCode secara terpisah menandai beberapa item menu sebagai vegan.", "esg": "Dapur Timur Tengah di dalam hotel yang, menurut keterangannya sendiri, hanya menyajikan daging yang disembelih menurut hukum Islam"},
  "eojjeoda-nongbu-namdaemun": {"of": "0e44d7b7", "story": "Eojjeoda Nongbu Namdaemun menyajikan mangkuk sayuran, pasta, dan kari yang mengusung konsep dari kebun ke meja, menghubungkan hasil bumi berlebih dengan dapur. Empat hidangan pada menu — satu pasta sayuran, satu mangkuk tahu lembut, dan dua kari — ditandai sebagai lini vegannya, dan tempat ini juga menjual versi ayam dan babi dari mangkuk yang sama.", "esg": "Dapur dari kebun ke meja yang bertumpu pada pemanfaatan hasil bumi yang kalau tidak dimanfaatkan akan terbuang"},
  "blu-seoul": {"of": "c34f8793", "story": "Blu Seoul adalah kafe yang vegan sepenuhnya dan bebas gluten di dekat Stasiun Chungmuro, dengan menu yang bertumpu pada hidangan seperti falafel, lasagna vegan, dan hummus. HappyCow mencantumkannya dalam kategori Vegan Restaurant miliknya, bukan sebagai dapur campuran dengan pilihan vegan.", "esg": "Dapur yang vegan sepenuhnya dan bebas gluten, tanpa menu pola makan campuran yang perlu dipilah"},
  "aladdins-lamb-jamsil": {"of": "4cb4ce81", "story": "Aladdin's Lamb memanggang potongan iga domba ala Arab di samping versi bulgogi Korea di dekat Stasiun Jamsilsaenae. Tempat ini menyebut dirinya spesialis halal di Instagram miliknya. Menunya juga mencantumkan soju dan bir. Tidak ada sertifikat yang kami lihat.", "esg": "Hanya menggunakan daging domba halal Australia berusia di bawah dua belas bulan, menurut sebuah pencantuman direktori restoran."},
  "mokro-garden-seongsu": {"of": "35fd2f47", "story": "Mokro Garden adalah kafe hidangan penutup yang dipenuhi tanaman di samping Seoul Forest, tidak jauh berjalan kaki dari Stasiun Seoul Forest. Sebuah direktori restoran melaporkannya sebagai vegan sepenuhnya per Maret 2025, dengan mencatat adanya papan 'ALL VEGAN' di pintu masuk; yang ditawarkannya antara lain croissant, brownies, dan kue wortel vegan.", "esg": "Tidak memakai produk hewani, menurut pencantuman vegan sepenuhnya di sebuah direktori restoran."},
  "room-temperature-seongsu": {"of": "1ef6608e", "story": "Room Temperature adalah kafe brunch bergaya Nordik di samping Seoul Forest. Situs pariwisata resmi Seoul menggambarkannya sebagai tempat yang berpusat pada hidangan organik dan vegan, tanpa menyatakan bahwa seluruh dapurnya berbasis nabati.", "esg": "Digambarkan oleh situs pariwisata Seoul sebagai dapur organik yang berfokus pada hidangan vegan."},
  "great-himalaya-suwon": {"of": "73699c49", "story": "Great Himalaya menyajikan masakan Nepal dan India di dekat Stasiun Suwon. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "nan-suwon": {"of": "36b4e1ed", "story": "Nan menyajikan masakan India dari sebuah unit di lantai dua di Ingye-dong, Suwon. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "suembu-suwon": {"of": "5389a4a9", "story": "Suembu menyajikan masakan India di cabangnya di Stasiun Suwon. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "himalaya-garden-suwon": {"of": "d80b4684", "story": "Himalaya Garden menyajikan masakan Nepal dan India di Ingye-dong, Suwon. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "diwali-seongnam": {"of": "44bc0839", "story": "Diwali menyajikan masakan India, tidak jauh berjalan kaki dari Stasiun Gachon University. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "indian-curry-seongnam": {"of": "2283843d", "story": "Indian Curry menyajikan masakan India di dekat Stasiun Seohyeon. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "inditable-seongnam": {"of": "fbbf61e3", "story": "Indi Table menyajikan masakan India di dekat Stasiun Pangyo. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "newdelhi-goyang": {"of": "346772c3", "story": "New Delhi menyajikan masakan India di dekat Stasiun Hwajeong. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "everest-starfield-hanam": {"of": "0f08732e", "story": "Everest menyajikan masakan India dan Nepal di dalam Starfield Hanam. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "masala-bucheon": {"of": "69757385", "story": "Masala adalah restoran India di kawasan Jung-dong, Bucheon. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "spice-village-pyeongtaek": {"of": "55a1c2ad", "story": "Spice Village adalah restoran India di kawasan Songtan, Pyeongtaek. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "bella-tunisie-suwon": {"of": "d7b121ea", "story": "Bella Tunisie menyajikan masakan Tunisia di dekat kampus Suwon Sungkyunkwan University. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "agra-starfield-suwon": {"of": "7834a2cd", "story": "Agra adalah jaringan restoran India; cabang ini berada di dalam mal Starfield Suwon. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "agra-starfield-anseong": {"of": "4648520e", "story": "Agra adalah jaringan restoran India; cabang ini berada di dalam mal Starfield Anseong. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "suembu-dongtan": {"of": "de07ada8", "story": "Cabang Dongtan dari Suembu menyajikan masakan Nepal dan India di kota baru Dongtan, Hwaseong. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "partune-namyang": {"of": "3e4b3a2b", "story": "Partune menyajikan masakan Uzbekistan di Namyang-eup, Hwaseong. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "royal-restaurant-ansan": {"of": "d8f53101", "story": "Royal Restaurant menyajikan masakan Indonesia di Wongok-dong, distrik khusus multikultural di Ansan. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "salty-ansan": {"of": "2b7c4f94", "story": "Salty menyajikan masakan Nepal dan India di tepi Wongok-dong, distrik multikultural di Ansan. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "asiana-restaurant-ansan": {"of": "101fd461", "story": "Asiana Restaurant menyajikan masakan India di salah satu jalan utama Wongok-dong, distrik multikultural di Ansan. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "rayhon-ansan": {"of": "341efa71", "story": "Rayhon menyajikan masakan Uzbekistan dan Asia Tengah di Sa-dong, Ansan. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "warung-kita-ansan": {"of": "442db633", "story": "Warung Kita menyajikan masakan Indonesia di Wongok-dong, distrik multikultural di Ansan. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "kantipur-ansan": {"of": "75c78356", "story": "Kantipur menyajikan masakan Nepal dan India di Wongok-dong, distrik multikultural di Ansan. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "ginza-ansan": {"of": "1a724945", "story": "Ginza menyajikan masakan India di Gojan-dong, Ansan, dekat pusat kota. Restoran ini tercantum dalam daftar restoran ramah Muslim di provinsi tersebut yang disusun sendiri oleh Gyeonggi Tourism Organization, tetapi tidak ada sertifikat yang kami lihat.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "welcome-to-dubai-suwon": {"of": "47dcd6f6", "story": "Welcome to Dubai menyajikan masakan Arab yang dimasak oleh koki Arab, di dekat Stasiun Suwon. Di Instagram-nya tempat ini menandai dirinya sebagai makanan halal dan vegan, dan sebuah direktori restoran memasukkannya ke kategori vegan. Tidak ada sertifikat yang kami lihat.", "esg": "Ditandai halal dan vegan baik oleh sebuah direktori restoran maupun oleh entri petanya sendiri."},
  "troy-kebab-suwon": {"of": "f2cdacca", "story": "Troy Kebab menyajikan kebab bergaya Turki di kawasan Yeongtong, Suwon. Di Instagram-nya tempat ini menyebut dirinya restoran halal Turki. Tidak ada sertifikat yang kami lihat.", "esg": "Dimasukkan ke kategori halal oleh pencarian milik sebuah direktori restoran."},
  "retro33-yongin": {"of": "ea80da6a", "story": "Retro 33 adalah restoran vegan di Yongin yang profilnya sendiri menyatakan bahwa seluruh menunya vegan.", "esg": "Dapur yang vegan sepenuhnya menurut pernyataannya sendiri."},
  "loving-hut-real-love-wolgok": {"of": "225119c9", "story": "Loving Hut Real Love adalah restoran vegan di lantai bawah tanah sebuah gedung pertokoan kecil, tidak jauh berjalan kaki dari Stasiun Sangwolgok. HappyCow mencantumkannya sebagai 100% vegan, dengan hidangan Korea dan fusi modern. Menunya di Kakao Map memuat sundae gukbap vegan, gimbap vegan, dan paket makan tahu lembut.", "esg": "Menu hidangan Korea sehari-hari yang seluruhnya berbasis nabati, menurut sebuah direktori restoran vegan."},
  "epikore-seongsu": {"of": "5f8e5511", "story": "Epikore menyajikan nasi mangkuk bergaya Korea di sebuah jalan kecil yang tenang di antara Seoul Forest dan Seongsu. HappyCow mencantumkannya sebagai vegan sepenuhnya, dan DiningCode memasukkannya ke kategori vegan sekaligus masakan Korea. Beberapa mangkuknya berbahan dasar doenjang, termasuk mangkuk musim gugur 2026 berisi doenjang apel dan labu kabocha.", "esg": "Dapur nasi mangkuk Korea yang sepenuhnya berbasis nabati, menurut dua direktori restoran."},
  "pureun-deli-seongsu": {"of": "0251882a", "story": "Pureun Deli adalah toko bagel di lantai bawah tanah di sebuah jalan kecil di Seongsu. HappyCow mencantumkannya sebagai vegan sepenuhnya, dan toko ini di Kakao Map menyebut dirinya membuat roti lapis bagel vegan buatan tangan. Minumannya memakai susu oat.", "esg": "Bagel vegan buatan tangan dan minuman dengan susu oat, menurut toko ini dan sebuah direktori vegan."},
  "chorokddeul-hoegi": {"of": "9a6e492c", "story": "Chorokddeul adalah restoran Korea di dekat Stasiun Hoegi dan Sahmyook Seoul Hospital. HappyCow mencantumkannya sebagai restoran vegetarian dengan hidangan vegan; tanyakan hidangan mana saja saat memesan. Restoran ini pindah ke alamatnya yang sekarang, masih di Hwigyeong-dong, dan berbagai daftar tidak sepakat soal hari bukanya, jadi teleponlah lebih dulu.", "esg": "Masakan Korea vegetarian dengan hidangan vegan, menurut sebuah direktori restoran vegan."},
  "kongppadu-oksu": {"of": "1a072dc4", "story": "Kongppadu adalah restoran tahu beberapa menit dari Stasiun Oksu. Menunya bertumpu pada rebusan tahu lembut, rebusan ampas kedelai, dan tahu yang disajikan dalam kuah kedelai, di samping hidangan daging. HappyCow mencantumkannya sebagai restoran bermenu campuran dengan pilihan yang ramah vegan, termasuk rebusan tahu putih dan nasi dalam kuah kedelai. Tanyakan hidangan mana yang vegan saat memesan.", "esg": "Hidangan tahu dan kedelai dengan pilihan yang ramah vegan, menurut sebuah direktori restoran vegan."},
  "achemi-hansung": {"of": "e782ed66", "story": "AcheMi membuat es krimnya dari susu beras yang diolahnya sendiri, beberapa menit berjalan kaki dari Stasiun Hansung University di Jalur 4. HappyCow mencantumkannya sebagai kafe es krim vegan. Es krimnya disajikan dalam cup atau cone, dan tempat ini juga menjual kue es krim.", "esg": "Es krim tanpa susu hewani yang dibuat dari susu beras buatan sendiri, menurut sebuah direktori vegan."},
  "bina-anam": {"of": "c7a45a4d", "story": "Bina adalah restoran India di dekat gerbang utama Korea University, yang menurut situs webnya dikelola oleh koki yang menempuh pelatihan di India. Menunya memiliki bagian vegan yang diberi label, berisi dal, chana masala, dan aloo gobi, dan restoran ini menyatakan bahwa hidangan lain dapat dibuat vegan atas permintaan. Sebuah direktori restoran halal mencantumkannya sebagai tempat yang menyajikan daging halal, dan organisasi pariwisata nasional Korea mencantumkannya sebagai ramah Muslim dalam panduan tahun 2021. Restoran ini juga menyajikan bir dan minuman anggur (wine), dan kami belum melihat sertifikat halalnya.", "esg": "Bagian menu vegan yang diberi label, menurut restoran ini; daging halal, menurut sebuah direktori halal."},
  "le-vegiwang-seongsu": {"of": "37bcd56f", "story": "Le Vegiwang adalah merek salad mangkuk dan kari yang menurut situs webnya bermula di Seongsu, dan ini adalah tokonya di Seongsu, di Yeonmujang 1-gil. HappyCow mencantumkannya sebagai restoran bermenu campuran dengan pilihan vegan, jadi mintalah versi vegan saat memesan.", "esg": "Ada pilihan vegan dalam menu campuran, menurut sebuah direktori vegan."},
  "ooh-breado-sangdo": {"of": "58ef0b61", "story": "Ooh Breado memanggang roti bergaya Korea tanpa bahan hewani, banyak di antaranya dari tepung beras: baguette beras, roti isi kacang merah, roti krim wijen hitam, dan muffin labu. Di lantai atas, Veggie Chan, yang dikelola pemilik yang sama, menyajikan hidangan bergaya Barat yang dimaksudkan untuk dimakan bersama rotinya. HappyCow mencantumkan kedua lantai sebagai vegan, dan daftar restoran vegetarian milik Kota Seoul sendiri mencatat butir-butir menu yang dicakupnya sebagai vegan. Tempat ini berjarak tiga menit berjalan kaki dari Stasiun Sangdo di Jalur 7.", "esg": "Toko roti dan dapur berbahan tepung beras dan hanya nabati dalam satu gedung."},
  "rudys-vegan-dangsan": {"of": "000b1705", "story": "Rudy's Vegan membuat salad, wrap, dan roti lapis dari sayuran, biji-bijian, kacang-kacangan, tahu, tempe, dan bulgogi nabati, dengan sentuhan Korea seperti perilla, gondre (sejenis sayuran gunung), dan saus doenjang, serta nasi burdock truffle sebagai pendamping. Tempat ini berada di pertokoan bawah tanah apartemen Hyundai di Dangsan-ro, sekitar 7 menit berjalan kaki dari Stasiun Yeongdeungpo-gu Office. Hari bukanya tidak tetap, jadi periksalah sebelum berangkat.", "esg": "Protein nabati (tahu, tempe, kacang-kacangan) sebagai pengganti daging di seluruh menu."},
  "vegan-mama-seoul-univ": {"of": "f578d44b", "story": "Vegan Mama memanggang hidangan penutup dan roti vegan, banyak di antaranya berbahan beras atau bebas gluten, dan menyajikan roti lapis terbuka di atas bagel beras dengan bulgogi nabati atau chili. HappyCow menyebut semua hidangan penutupnya vegan; minuman dapat dibuat dengan susu kedelai atau susu sapi, jadi mintalah susu kedelai. Tempat ini berjarak sekitar enam menit berjalan kaki dari Stasiun Seoul National University di Jalur 2.", "esg": "Bahan organik dan non-GMO sedapat mungkin, menurut entrinya di HappyCow."},
  "godeuni-magok": {"of": "517f0056", "story": "Godeuni adalah tempat sangrai kopi dan kafe hidangan penutup di Magok yang kue panggangnya bebas gluten, dan financier-nya, dengan dua belas rasa, juga vegan. Latte dibuat dengan susu oat kecuali Anda meminta susu sapi. Kue musimannya mengandung krim dan tidak vegan, jadi pilihlah dari financier. Tempat ini berjarak empat menit berjalan kaki dari Stasiun Magongnaru, satu perhentian dari Bandara Gimpo dengan Airport Railroad.", "esg": "Susu oat sebagai pilihan bawaan untuk latte."},
  "otsal-seoul-univ": {"of": "5fd93767", "story": "Otsal menyajikan kari India Utara dan Selatan, biryani, dan aneka roti dari sebuah unit bawah tanah di Gwanak-ro, tidak jauh berjalan kaki dari Stasiun Seoul National University. Panduan restoran ramah Muslim dari Korea Tourism Organization mencantumkannya sebagai ramah Muslim, artinya sebagian atau semua hidangannya halal; tidak ada sertifikat yang kami lihat, jadi tanyakan kepada staf hidangan mana yang halal. Perhimpunan pelajar Indonesia di universitas terdekat itu juga merekomendasikannya.", "esg": "Tercantum dalam panduan restoran ramah Muslim dari Korea Tourism Organization."},
  "durga-uijeongbu": {"of": "a0ae21c1", "story": "Cabang Uijeongbu dari Durga menyajikan masakan Nepal dan India di lantai dua sebuah gedung dekat Stasiun Uijeongbu; nama Durga juga memiliki cabang di Seoul. Baik Gyeonggi Tourism Organization maupun Korea Tourism Organization mencantumkannya sebagai ramah Muslim. Kami belum melihat sertifikat halalnya.", "esg": "Dicantumkan sebagai ramah Muslim oleh organisasi pariwisata provinsi maupun nasional."},
  "grey-paju": {"of": "afef41fd", "story": "Grey adalah restoran India di lantai teratas gedung Eiffel Tower dekat Stasiun Yadang. Pengunjung dapat memakai tempat parkir bawah tanah gedung itu. Gyeonggi Tourism Organization mencantumkannya di antara restoran ramah Muslim di provinsi tersebut. Kami belum melihat sertifikat halalnya.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "asia-asia-ilsan": {"of": "7f523347", "story": "Asia Asia menyajikan masakan India di lantai dua Western Dom, jalan perbelanjaan terbuka di dekat Stasiun Jeongbalsan dan Ilsan Lake Park. Gyeonggi Tourism Organization mencantumkannya di antara restoran ramah Muslim di provinsi tersebut. Kami belum melihat sertifikat halalnya.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "annapurna-bucheon": {"of": "26fd37f9", "story": "Annapurna menyajikan masakan India di lantai dua sebuah gedung di Simgok-dong, sekitar sembilan menit berjalan kaki dari Stasiun Bucheon. Baik Gyeonggi Tourism Organization maupun Korea Tourism Organization mencantumkannya sebagai ramah Muslim. Kami belum melihat sertifikat halalnya.", "esg": "Dicantumkan sebagai ramah Muslim oleh organisasi pariwisata provinsi maupun nasional."},
  "has-kebab-dongducheon": {"of": "46ec3f7e", "story": "Has Kebab adalah kedai kebab Turki kecil di jalan utama Dongducheon, beberapa menit berjalan kaki dari Stasiun Bosan di Jalur 1. Gyeonggi Tourism Organization mencantumkannya di antara restoran ramah Muslim di provinsi tersebut. Kami belum melihat sertifikat halalnya.", "esg": "Tercantum dalam survei restoran ramah Muslim yang dilakukan sendiri oleh Provinsi Gyeonggi."},
  "sarbon-gimpo": {"of": "277f3ce9", "story": "Restoran Uzbekistan di Tongjin-eup ini, Sarbon Uzbek Restaurant, dalam entri petanya sendiri menyebut dirinya restoran halal yang memanggang roti non dan pastri samsa setiap hari dalam dua oven. Osh (nasi pilaf) pada menu yang dicantumkannya mengandung daging sapi dan daging kuda. Kami belum melihat sertifikat halalnya.", "esg": "Pemiliknya menyebut dapurnya halal dan memanggang rotinya di tempat setiap hari."},
  "seoul-iya-yeonnam": {"of": "f861cfee", "story": "Seoul-iya menafsirkan ulang masakan rumahan Korea sebagai makanan halal dengan memadukan cita rasa Malaysia dan Korea; situs pariwisata resmi Seoul menyebut chicken kimchi jjim, ayam yang dimasak perlahan bersama kimchi dalam saus pedas, sebagai hidangan andalannya. Situs yang sama mencantumkan bahwa juru masak di dapurnya Muslim dan alkohol tidak dijual. Kami belum melihat sertifikat halalnya. Tempat ini berjarak beberapa menit berjalan kaki dari Stasiun Hongik University dan tutup pada hari Jumat."},
  "nusantaraku-hongdae": {"of": "46048c67", "story": "Nusantaraku memasak masakan Indonesia, tidak jauh berjalan kaki dari Stasiun Hongik University. Situs pariwisata resmi Seoul menyebut bahan-bahannya didatangkan dari Asia Tenggara dan dagingnya bersertifikat halal, dengan nasi goreng ayam, domba, atau sapi sebagai hidangan andalan. Entri yang sama mencatat bahwa juru masaknya Muslim dan alkohol tidak dijual. Tidak ada sertifikat yang kami lihat."},
  "eid-bbq-hongdae": {"of": "c90ad001", "story": "EID BBQ memanggang barbeku bergaya Korea di atas arang, beberapa menit dari Stasiun Hongik University. Menu yang tercantum di DiningCode meliputi iga domba, sirloin berbumbu galbi, dan galbi ayam panggang arang, dengan rebusan kimchi dan tteokbokki sebagai pendamping. Tempat ini adalah cabang barbeku EID di Hongdae, dan Instagram EID menyebut merek tersebut bersertifikat halal; kami belum melihat sertifikat untuk cabang ini."},
  "the-halal-fitzza-hongdae": {"of": "9c67c528", "story": "The Halal Fitzza menjual pizza persegi tipis, potongan besar, sayap ayam, dan pasta di lantai dua sebuah gedung di antara Sangsu dan Hongdae, buka sampai pukul 2 dini hari dan sampai pukul 5 pagi pada akhir pekan. Di Instagram-nya tempat ini menyebut dirinya halal, dan menunya menandai daging sapi dan pepperoni sebagai halal. Tidak ada sertifikat yang kami lihat, dan belum diketahui apakah alkohol disajikan."},
  "jumjumjum-sangam": {"of": "6f40a38e", "story": "jumjumjumjumjumjum menyajikan hidangan vegan delapan sajian yang bertumpu pada saus dan pesto buatan sendiri, di ruangan berlapis aluminium daur ulang dekat Digital Media City. Situs pariwisata resmi Seoul menggambarkannya sebagai restoran vegan, pusat budaya, dan ruang pameran, dan HappyCow mencantumkannya sebagai fusi Korea modern berbasis nabati. Makan siang harus dengan reservasi.", "esg": "Dapur sepenuhnya berbasis nabati; interiornya dibuat dari aluminium daur ulang (menurut situs pariwisata Seoul)."},
  "pul-mangwon": {"of": "e32db052", "story": "Pul, di Mangridan-gil, Mangwon-dong, memasak dengan fermentasi dan kacang-kacangan dari Jeju: nasi merah dengan kacang fermentasi, sup mi kedelai pada musim panas, dan sup kacang rumahan pada musim dingin. Maison Korea menggambarkannya sebagai tempat yang dijalankan dengan menu vegan sebagai poros, dan hey! travel menyebut resep kedelainya diwariskan dari ibu sang pemilik, seorang koki yang pernah memasak untuk kementerian luar negeri Korea di luar negeri. Salah satu pastanya dapat diberi keju kambing, jadi tanyakan hidangan mana yang sepenuhnya berbasis nabati."},
  "bomulseom-kimbap-mangwon": {"of": "ccf24576", "story": "Bomulseom Kimbap menggulung kimbap sesuai pesanan, beberapa menit dari Stasiun Mangwon, praktis untuk piknik di tepi Sungai Han. Menunya memberi label vegan pada dua gulungan, yaitu Bomulseom kimbap khas tempat ini dan kimbap acar sayuran, di samping gulungan tuna, daging sapi, dan keju. Mintalah versi vegan dengan menyebut namanya."},
  "palgyejip-yeonnam": {"of": "ce38cb7f", "story": "Palgyejip menyajikan barbeku Korea, nasi periuk, dan aneka rebusan di ruangan bergaya hanok dengan area duduk luar ruangan di Yeonnam-dong. Situs pariwisata resmi Seoul mencatat bahwa menu vegan tersedia, sehingga seorang vegan dan seorang pemakan daging dapat makan semeja di sini. Tempat ini menyajikan daging babi."},
  "salermari-mangwon": {"of": "b36f95b1", "story": "Salermari adalah kedai bunsik kecil di Mangwon-dong yang menjual salad, kimbap, dan udon dari hasil kebun keluarga. Pemiliknya mengatakan kepada hey! travel bahwa begitu banyak pelanggan vegetarian meminta perubahan sehingga kedai ini membuat kimbap vegan, gulungan chamnamul, dan gulungan bayam-doenjang, dan menunya saat ini juga mencantumkan pangsit vegan. Gulungan lain mengandung bulgogi atau ikan teri, jadi mintalah yang vegan."},
  "camels-kitchen-hapjeong": {"of": "560ce1f3", "story": "Camel's Kitchen memasak hidangan berinspirasi Thailand tanpa daging. Menurut hey! travel, pemiliknya, yang makan ikan tetapi tidak makan daging, sebelumnya mengelola sebuah restoran Thailand di Mangwon selama empat tahun. HappyCow mencantumkan hidangan vegan seperti tahu pedas di atas nasi dan kari merah, di samping hidangan boga bahari dan telur. Jam bukanya berbeda antara satu daftar dan daftar lain, jadi periksalah sebelum berangkat."},
  "hwanggeumlyong-mangwon": {"of": "d968f8ff", "story": "Hwanggeumlyong adalah restoran keluarga masakan Korea-Tionghoa di Poeun-ro, Mangwon, yang menyajikan jajangmyeon, jjamppong, dan hidangan asam manis. HappyCow menyebut hidangan vegannya didaftar terpisah dari menu utama, jadi mintalah daftar vegannya. Tempat ini tutup pada hari Rabu."},
  "istanbul-grill-gongdeok": {"of": "a1393c94", "story": "Istanbul Grill memasak barbeku arang Turki, tidak jauh berjalan kaki dari Stasiun Gongdeok: köfte daging domba cincang, paha ayam panggang, pilaf, hummus, dan roti Turki, menurut menunya di DiningCode. Di Instagram-nya tempat ini menyebut makanannya masakan Turki halal, dan akun itu juga menawarkan bebas biaya corkage untuk anggur yang dibawa tamu sendiri. Tidak ada sertifikat yang kami lihat."},
  "mr-kebab-itaewon": {"of": "451b3b2a", "story": "Mr. Kebab menyajikan kebab Turki, wrap, dan hidangan nasi dari lantai dasar 192 Itaewon-ro. Zabihah menggambarkannya sebagai tempat yang dikelola pemilik Muslim asal Turki yang menegaskan status halalnya, dan kantor pariwisata Seoul pernah mencantumkannya di antara restoran bersertifikat halal di kawasan itu. Tidak ada sertifikat yang kami lihat.", "esg": "Gerai kebab Turki ramah halal di Itaewon-ro, satu menit dari stasiun."},
  "hojibobo-itaewon": {"of": "204f9721", "story": "Hojibobo memasak hidangan Uzbekistan dan Rusia, termasuk shashlik panggang arang dan kebab Adana, dari lantai tiga 140-1 Itaewon-ro. Di Instagram-nya tempat ini menyebut dirinya restoran halal. Menu pesan antarnya mencantumkan salad ham tanpa menyebut ham itu terbuat dari apa, jadi tanyakan sebelum memesannya. Tidak ada sertifikat yang kami lihat.", "esg": "Tempat panggangan Uzbekistan ramah halal di antara Noksapyeong dan Itaewon."},
  "arabesque-itaewon": {"of": "a8ef56d8", "story": "Arabesque menyajikan hidangan Timur Tengah seperti mansaf domba di samping kari bergaya India di lantai dua 227 Itaewon-ro, ke arah Hannam-dong. Korea Tourism Organization mencantumkannya di antara restoran ramah Muslim, dan panduan tahun 2021 dari organisasi itu menggolongkannya sebagai halal atas pernyataan sendiri: restoran ini menyatakan dirinya halal dan memiliki pengelola atau juru masak Muslim. Tidak ada sertifikat yang kami lihat.", "esg": "Dapur Timur Tengah dan India ramah halal di Itaewon-ro."},
  "troy-kebab-itaewon": {"of": "7b5d28a7", "story": "Troy menjual kebab Turki isi ayam, domba, dan campuran serta hidangan nasi dari sebuah gerai kecil di 125 Bogwang-ro. Di Instagram-nya tempat ini menyebut dirinya restoran halal Turki. Tidak ada sertifikat yang kami lihat.", "esg": "Gerai kebab ramah halal di Bogwang-ro."},
  "king-kebab-gyeongridan": {"of": "be897da9", "story": "Cabang King Kebab di Gyeongridan-gil ini membuat wrap Turki isi ayam, domba, Adana sapi, dan falafel. Jaringan King Kebab menyebut makanannya halal di Instagram resminya, yang menyebut nama cabang ini. Tidak ada sertifikat yang kami lihat. Pintu keluar stasiun terdekat berjarak sekitar 700 m.", "esg": "Kedai kebab ramah halal di Gyeongridan-gil."},
  "pak-india-itaewon": {"of": "c0b69cae", "story": "Pak India menyajikan paket hidangan Pakistan dari sebuah ruangan di lantai dua di gang-gang yang bercabang dari Itaewon-ro, setelah pindah dari tempat lamanya di dekat masjid. Korea Tourism Organization mencantumkannya dengan alamatnya yang sekarang di antara restoran ramah Muslim, dan panduan tahun 2021 dari organisasi itu, yang terbit sebelum kepindahan tersebut, menggolongkannya sebagai halal atas pernyataan sendiri: restoran ini menyatakan dirinya halal dan memiliki pengelola atau juru masak Muslim. Tidak ada sertifikat yang kami lihat.", "esg": "Dapur Pakistan ramah halal di dekat Itaewon-ro."},
  "little-india-itaewon": {"of": "3118db57", "story": "Little India memasak kari India Utara seperti chicken tikka masala, kadai, dan saag chicken di Usadan-ro 10-gil, dekat Masjid Pusat Seoul. Korea Tourism Organization mencantumkannya di antara restoran ramah Muslim, dan panduan tahun 2021 dari organisasi itu menggolongkannya sebagai halal atas pernyataan sendiri: restoran ini menyatakan dirinya halal dan memiliki pengelola atau juru masak Muslim. Tidak ada sertifikat yang kami lihat.", "esg": "Rumah makan kari India ramah halal di dekat Masjid Pusat Seoul."},
  "taj-palace-itaewon": {"of": "f582df79", "story": "Taj Palace menyajikan kari India, biryani, dan ayam tandoori di lantai dua 39 Usadan-ro, dengan prasmanan pada akhir pekan dan hari libur. Korea Tourism Organization mencantumkannya di antara restoran ramah Muslim, dan panduan tahun 2021 dari organisasi itu menggolongkannya sebagai halal atas pernyataan sendiri: restoran ini menyatakan dirinya halal dan memiliki pengelola atau juru masak Muslim. Tidak ada sertifikat yang kami lihat.", "esg": "Restoran India ramah halal di Usadan-ro."},
  "bytofu-haebangchon": {"of": "43215567", "story": "byTOFU membuat salad mangkuk, wrap, dan roti lapis berbasis nabati, termasuk roti lapis tahu 'telur tanpa telur', di Haebangchon. The Korea Times pada 2024 menggambarkannya sebagai restoran vegan yang menghindari plastik dan memberi potongan harga kepada pelanggan yang membawa tumbler atau wadah sendiri. Tempat ini dicapai dengan berjalan kaki jauh menanjak (sekitar 1,3 km) dari pintu keluar kereta bawah tanah terdekat.", "esg": "Kafe sepenuhnya berbasis nabati yang memberi potongan harga untuk wadah pakai ulang."},
  "plantude-yongsan": {"of": "75dcc5ad", "story": "Plantude adalah restoran nabati milik Pulmuone; cabang kedua ini dibuka pada 2023 di lantai Taste Park di I'Park Mall, Stasiun Yongsan. Pulmuone menyatakan seluruh menunya berbahan nabati dan disertifikasi oleh Vegan Standard Certification Institute. Hidangannya antara lain gangjeong jamur dan tahu serta pasta yang dibuat dengan gosari (pakis).", "esg": "Dapur yang sepenuhnya nabati dengan sertifikasi vegan dari pihak ketiga, di dalam mal Stasiun Yongsan"},
  "daom-guksujip": {"of": "9f99672d", "story": "Daom Guksujip adalah kedai mi Korea kecil di Cheongpa-ro yang menyajikan janchi guksu, bibim guksu, dan kong guksu musiman. Janchi guksu standarnya memakai kaldu ikan teri, dan menunya menawarkan versi vegan. Letaknya sekitar 16 menit berjalan kaki dari Stasiun Seoul.", "esg": "Mi Korea sehari-hari dengan pilihan vegan, dekat Stasiun Seoul"},
  "bsj-chicken-wok-myeongdong": {"of": "9846dc0c", "story": "BSJ Chicken & WOK adalah restoran saudara di Myeongdong dari Busanjib, restoran BBQ Korea halal di Myeongdong 8-gil, yang dijalankan oleh pengelola yang sama. Pengelola menyebut cabang-cabangnya halal dan menyatakan bahwa cabang-cabang itu bersertifikat, meskipun tidak ada sertifikat yang kami lihat dan tidak ada lembaga sertifikasi yang disebutkan. Daftar usahanya sendiri menyebut adanya ruang salat dan tempat wudu.", "esg": "Dapur ayam goreng Korea dan masakan wok yang dijalankan sebagai bagian dari grup kecil restoran ramah Muslim"},
  "iftar-gyeongbokgung": {"of": "12d76aa6", "story": "IFTAR menyajikan hidangan tradisional Korea, di antaranya bulgogi dan ayam ala galbi, di sebuah hanok hasil renovasi yang berjarak beberapa menit berjalan kaki dari Stasiun Gyeongbokgung. Situs pariwisata Seoul menyebut dapurnya memakai bahan yang bersertifikat sesuai standar halal, memiliki juru masak Muslim, dan tidak menjual alkohol. Restoran ini menyebut dirinya bersertifikat halal, tetapi tidak ada sertifikat yang kami lihat dan tidak ada lembaga sertifikasi yang disebutkan.", "esg": "Masakan Korea halal di hanok yang dipugar di dekat Istana Gyeongbokgung"},
  "myeongdongjeong": {"of": "c3062437", "story": "Myeongdongjeong menyajikan hanjeongsik, hidangan set Korea dengan banyak sajian, dengan tata meja yang meniru hidangan istana kerajaan, satu menit berjalan kaki dari Pintu Keluar 10 Stasiun Myeongdong. Situs pariwisata Seoul menyebut restoran ini memakai daging halal. Restoran ini juga menjual alkohol dan tidak mencantumkan juru masak Muslim, sehingga pernyataan halal itu mencakup dagingnya, bukan dapur yang bersertifikat.", "esg": "Hidangan set Korea bergaya istana yang dibuat dengan daging halal, di tengah Myeongdong"},
  "myeongdong-chaeum": {"of": "3ec813f8", "story": "Chaeum menyajikan table d'hôte Korea, yaitu satu set lengkap nasi, sup, rebusan, dan 18 lauk pendamping yang dibuat setiap hari, di ruang makan bawah tanah yang berjarak dua menit dari Pintu Keluar 3 Stasiun Myeongdong. Situs pariwisata Seoul menggambarkannya sebagai restoran halal. Restoran ini menjual alkohol dan tidak mencantumkan juru masak Muslim, dan tidak ada sertifikat yang kami lihat.", "esg": "Satu meja hidangan set Korea lengkap yang ditawarkan sebagai halal di pusat Myeongdong"},
  "bali-holiday-myeongdong": {"of": "0c412cc0", "story": "Bali Holiday memasak hidangan Indonesia seperti mie goreng, nasi goreng, sate ayam, dan tempe di lantai dua sebuah gedung yang berjarak tiga menit dari Pintu Keluar 3 Stasiun Myeongdong. Situs pariwisata Seoul menyebut setiap hidangan dibuat dengan bahan halal, bahwa restoran ini memiliki juru masak Muslim dan ruang salat, serta tidak menjual alkohol. Tidak ada sertifikat yang kami lihat.", "esg": "Masakan rumahan Indonesia dengan bahan halal dan ruang salat di Myeongdong"},
  "samarkand-main-dongdaemun": {"of": "6ec29bf0", "story": "Ini adalah cabang utama Samarkand di Mareunnae-ro, di kawasan Asia Tengah dekat Dongdaemun History & Culture Park. Situs pariwisata Seoul menyebutnya restoran Jalur Sutra pertama di Korea yang dikelola orang Uzbek dan menyebut shashlik domba yang dipanggang dalam oven batu sebagai hidangan andalannya. Halaman yang sama menyebut restoran ini memiliki juru masak Muslim dan tidak menjual alkohol, meskipun daftar Kakao-nya mengizinkan tamu membawa minuman beralkohol sendiri. Kami belum melihat sertifikat halalnya.", "esg": "Dapur yang dikelola orang Uzbek di komunitas Asia Tengah Gwanghui-dong"},
  "mari-meokja-myeongdong": {"of": "aa0b6d34", "story": "Mari Meokja adalah restoran layanan konter dengan pemesanan lewat tablet di lantai dua, satu menit dari Pintu Keluar 4 Stasiun Myeongdong. Restoran ini menyajikan hidangan Malaysia seperti nasi lemak di samping hidangan Korea. Zabihah, sebuah direktori restoran halal, mencantumkannya sebagai halal sepenuhnya dan tidak menyajikan alkohol, berdasarkan jaminan dari staf. Tidak ada sertifikat yang kami lihat.", "esg": "Konter halal Malaysia dan Korea beberapa langkah dari Stasiun Myeongdong"},
  "jayeondo-sogeumppang-ikseon": {"of": "204ada6d", "story": "Jayeondo adalah toko roti di Ikseon-dong yang membuat roti garam, dijual bersama minuman seperti jus jeruk, dengan tempat duduk di halaman terbuka yang berkurang saat cuaca buruk. Zabihah, sebuah direktori restoran halal, mencantumkannya sebagai halal sepenuhnya dan tidak menyajikan alkohol, berdasarkan jaminan dari staf. Tidak ada sertifikat yang kami lihat.", "esg": "Tempat singgah toko roti yang tercantum halal di gang-gang hanok Ikseon-dong"},
  "soiroum-seochon": {"of": "2d9dd49d", "story": "Soiroum adalah restoran vegan di Pirundae-ro, Seochon, sekitar sepuluh menit berjalan kaki dari Stasiun Gyeongbokgung. HappyCow mencantumkannya sebagai vegan sepenuhnya, dengan burger, mi tumis, sushi sayuran, dan sandwich, serta kue dan yogurt. Menu Kakao-nya memuat sepiring hamburg steak daging kedelai dan kari sup sayuran.", "esg": "Dapur lingkungan yang sepenuhnya nabati di kawasan hanok Seochon"},
  "weirdough-yeonhui": {"of": "09b71797", "story": "Weirdough adalah restoran piza vegan di lantai dua sebuah gedung di Jeungga-ro, Yeonhui-dong, yang dibuka pada Februari 2024 menurut HappyCow. Selain piza, tempat ini menyajikan pasta, hidangan sayuran, dan hidangan penutup. Jaraknya jauh dari kereta bawah tanah: sekitar 25 menit berjalan kaki dari Stasiun Gajwa. Kakao mencatat bahwa reservasi dilakukan melalui Catch Table dan penutupan sementara diumumkan di Instagram.", "esg": "Restoran piza yang sepenuhnya nabati di kawasan permukiman Yeonhui-dong"},
  "myeongdong-joomak": {"of": "db1ad0f3", "story": "Myeongdong Joomak adalah restoran Korea sekaligus kedai minuman beralkohol di lantai dua, di atas sebuah toko di Myeongdong 10-gil. Tempat ini menyajikan daging, tetapi HappyCow melaporkan adanya menu vegetarian berbahasa Inggris yang terpisah dengan hidangan vegan yang ditandai dengan jelas, termasuk bulgogi sapi vegan dengan nasi, pangsit, dan nugget tahu. Beberapa hidangan vegetarian mungkin dapat dibuat vegan atas permintaan.", "esg": "Hidangan Korea vegan yang ditandai dengan jelas di tengah Myeongdong"},
  "ajindang-ikseon": {"of": "89de3b67", "story": "Ajindang membuat hidangan penutup Korea dari beras dan kacang-kacangan di Ikseon-dong: tteok, kue manis tradisional hwagwaja, batang kacang, sikhye, dan sujeonggwa, serta teh. HappyCow mencantumkannya sebagai tempat dengan pilihan vegan, dan seorang pengulas di sana melaporkan bahwa sebagian besar produknya vegan dengan bahan yang diberi label. Kue pesanan khusus perlu dipesan tiga hari sebelumnya.", "esg": "Kue manis beras tradisional Korea, banyak di antaranya nabati, di gang-gang hanok Ikseon-dong"},
  "nimat-incheon-airport-t1": {"of": "ac7ae196", "story": "Nimat adalah konter ramah Muslim di pujasera lantai empat, sisi timur, Terminal 1 Bandara Incheon. Direktori tempat makan milik bandara sendiri menggambarkannya menyajikan nasi Korea dalam mangkuk batu panas yang dibuat dengan bahan bersertifikat kosher, dan mencantumkan bibimbap sayuran dalam mangkuk batu di antara hidangan utamanya. Kami belum melihat sertifikat halalnya.", "esg": "Hidangan Korea ramah Muslim di dalam Terminal 1, yang dicantumkan demikian oleh direktori tempat makan milik bandara sendiri"},
  "food-garden-incheon-airport-t1": {"of": "2f25d0cb", "story": "Food Garden adalah restoran Korea di lantai satu Terminal 1 Bandara Incheon, di area umum dekat Pintu Keluar 12, dan bandara mencantumkannya buka 24 jam. Direktori bandara mencantumkan sup, bibimbap, mi, dan bubur nasi. HappyCow mencantumkan pilihan vegan seperti bibimbap, bubur kimchi taoge, serta bubur jamur dan sayuran; para pengulas HappyCow mencatat bahwa hidangan vegan tidak ditandai di menu, jadi tanyakan kepada staf.", "esg": "Makanan rumahan Korea dengan pilihan vegan, tersedia pada jam berapa pun di area kedatangan"},
  "myeongin-kongguksu-guwol": {"of": "abd01a67", "story": "Myeongin Kongguksu membuat kongguksu, mi dalam kuah dingin dari kedelai giling, dan menu DiningCode-nya menyebut tempat ini hanya memakai kedelai hasil tanam Korea yang digiling dengan gilingan batu tradisional; mi potong pisau kacang merah dan bubur kacang merah juga tercantum. Daftar HappyCow menyebut semuanya vegan secara bawaan kecuali kimchi dan kopi swalayan.", "esg": "Kedelai dan kacang merah hasil tanam Korea sebagai inti hidangan Korea nabati sehari-hari"},
  "manisan-sanchae-ganghwa": {"of": "b9bdd404", "story": "Manisan Sanchae memasak dengan sanchae, sayuran gunung Korea, di jalan pesisir selatan Pulau Ganghwa. Menu DiningCode-nya mencantumkan set bibimbap sayuran gunung, nasi periuk sayuran gunung, dan jeli biji ek buatan tangan. HappyCow mencantumkan pilihan vegan di antara hidangan-hidangan ini; pengulasnya mencatat bahwa sebagian lauk pendamping gratisnya tidak vegan, jadi tanyakan kepada staf.", "esg": "Sayuran gunung dan jeli biji ek: masakan Korea dari tumbuhan liar di Pulau Ganghwa"},
  "chaeyuk-juan": {"of": "dd059ae8", "story": "Chaeyuk Sikdang menyajikan makan siang pekerja Korea berupa tumisan dan rebusan dengan nasi dan lauk pendamping, dan empat hidangannya disajikan dengan daging kedelai, yang oleh menu jaringan itu sendiri diberi label vegan, sebagai pengganti daging babi atau sapi. Ini adalah cabang Juan, dekat stasiun Citizens Park di Jalur 2 Incheon. Kuah rebusannya tidak dijelaskan, jadi tanyakan kepada staf jika hal itu penting bagi Anda.", "esg": "Daging kedelai sebagai pengganti daging babi dalam hidangan set Korea sehari-hari"},
  "lofi-gyeyang": {"of": "373bab5b", "story": "Lofi adalah kafe roti yang tidak jauh berjalan kaki dari stasiun Imhak. HappyCow mencantumkannya sebagai toko roti vegan yang memanggang tanpa tepung putih, gula putih, mentega, atau susu, dan menu DiningCode-nya memberi label vegan pada sebuah spoon cake dan sebuah sandwich bagel beras. Para pengulas HappyCow mencatat bahwa kopi disajikan dengan susu sapi kecuali Anda meminta susu kedelai.", "esg": "Memanggang tanpa mentega, susu, atau gula rafinasi"},
  "myeongaros-cheongna": {"of": "9de34f8b", "story": "Myeongaros memanggang roti dengan tepung beras sebagai pengganti gandum. Menu DiningCode-nya menandai banyak roti sebagai vegan, di antaranya roti beras cokelat, nurungji, mugwort-beri, dan cokelat, serta menandai roti keju sebagai tidak vegan; kue dan minuman susu juga dijual.", "esg": "Roti tepung beras dengan roti vegan yang diberi label jelas"},
  "the-iroun-dongincheon": {"of": "619f1749", "story": "The Iroun adalah kedai kecil salad dan mangkuk biji-bijian dekat stasiun Dongincheon. Menu DiningCode-nya mencantumkan salad protein vegan yang dibuat dengan mi tahu di antara hidangan ayam, babi, dan telur.", "esg": "Salad vegan berlabel pada menu sayuran hijau organik"},
  "mahina-vegan-table": {"of": "e5a2ffdc", "story": "Mahina Vegan Table berada di lantai dua sebuah gedung di dekat Garosu-gil, Sinsa-dong. Situsnya sendiri menggambarkan setiap hidangan di menunya sebagai 100% nabati: hidangan Barat yang sudah dikenal seperti pasta, burger, piza, dan risotto, termasuk carbonara ala Roma yang dibuat dengan kuning telur vegan dan bacon vegan. Karya seni kontemporer terpajang di ruang makan dan musik klasik diputar selama waktu makan. Restoran ini menyajikan makan siang dan makan malam dari Senin sampai Sabtu dan tutup pada hari Minggu; pengelola menerima pemesanan meja melalui Naver Booking dan CatchTable, bukan lewat telepon.", "esg": "Menu yang seluruhnya nabati, termasuk versi nabati dari hidangan berbahan telur dan susu seperti carbonara."},
  "loving-hut-smile-gaepo": {"of": "77897f61", "story": "Loving Hut Smile adalah cabang jaringan Loving Hut, yang situs Korea-nya menyebut semua makanannya dibuat dari bahan yang sepenuhnya vegan. Dapur di Gaepo-dong ini, yang dahulu bernama Loving Hut Land, memasak hidangan Korea sehari-hari tanpa produk hewani: gimbap vegan, jajangmyeon kacang hitam, tteokbokki, bibimbap, dan ayam goreng Korea versi protein kedelai. Beberapa hidangan dibuat dengan lima sayuran berbau tajam (bawang putih, bawang bombai, dan kerabatnya) yang tidak dipakai dalam masakan kuil Buddha; menunya meminta tamu yang menghindarinya untuk memberi tahu saat memesan. Letaknya di kawasan permukiman, sekitar 19 menit berjalan kaki dari stasiun kereta bawah tanah terdekat.", "esg": "Dapur yang seluruhnya bebas bahan hewani, dengan versi bebas gluten untuk beberapa hidangan."},
  "plantude-godeok": {"of": "26d5190f", "story": "Plantude adalah merek restoran vegan milik perusahaan jasa boga Pulmuone, dan ini adalah cabang ketiganya, di lantai empat IPARK The River Mall di Godeok. Menurut pengumuman Pulmuone sendiri, setiap item di menu memiliki sertifikasi vegan dari Korea Agency of Vegan Certification, seperti di cabang-cabang lainnya. Menunya condong ke masakan Korea: mi hangat dengan gyoza, gangjeong tahu dan jamur yang digoreng renyah, pangsit berisi shiitake dan tahu, dan rebusan tahu, di samping pasta dan hidangan anak-anak. Letaknya sekitar 26 menit berjalan kaki dari Stasiun Godeok.", "esg": "Menu bersertifikat yang vegan sepenuhnya, sebagian besar bertumpu pada tahu, jamur, dan bahan nabati Korea lainnya."},
  "gomone-kongtang-dunchon": {"of": "00526e32", "story": "Gomone memasak hidangan kedelai Korea di dekat Stasiun Dunchon-dong. Daftar restoran vegetarian Seoul mencantumkan lima hidangannya sebagai vegan: kongguksu dingin dan hangat (mi dalam susu kedelai kental), kongtang (sup dari kedelai jangdan Paju giling yang hanya dibumbui garam, menurut menunya), panekuk kacang hijau, dan sepotong tahu segar. Menu selebihnya mencakup sup ikan pollock kering dan tumis daging babi, jadi ini bukan dapur vegetarian. Cheonggukjang dan kongbiji (rebusan ampas kedelai) di sini dicantumkan sebagai pescatarian, bukan vegan.", "esg": "Bertumpu pada kedelai Korea yang digiling sendiri di tempat, dari kedelai jangdan Paju dalam negeri menurut menunya."},
  "kervan-famille-station": {"of": "ac774db3", "story": "Cabang jaringan restoran Turki Kervan ini berada di Famille Station, kompleks restoran di samping Seoul Express Bus Terminal. Situs pariwisata resmi Seoul menggambarkan Kervan sebagai jaringan yang menyajikan makanan halal, dimasak oleh koki Turki. Menunya berpusat pada potongan daging domba panggang, piring kebab campur, pide, dan set makan siang hari kerja. Kami belum melihat sertifikat untuk cabang ini: situs pariwisata itu menyebut sertifikasi KMF hanya untuk restoran Kervan di COEX dan Itaewon. Restoran ini buka setiap hari dari pukul 11:00 sampai 21:00.", "esg": "Memanggang di atas api terbuka dengan gaya Turki, dengan piring saji untuk berbagi yang porsinya cocok untuk rombongan."},
  "loving-hut-ansan-gojan": {"of": "04fca714", "story": "Ini adalah cabang Ansan dari Loving Hut, jaringan restoran vegan yang situs Korea-nya menyebut setiap hidangan di menunya vegan dan tidak mengandung bahan hewani; standar tertulisnya juga tidak memperbolehkan madu. Cabang ini berjarak sekitar tujuh menit berjalan kaki dari Stasiun Gojan. Menu yang tercantum berbeda antara situs peta dan situs direktori, jadi periksa apa yang sedang disajikan saat Anda tiba.", "esg": "Standar vegan seluruh jaringan yang tidak memperbolehkan bahan hewani, produk sampingannya, dan madu."},
  "mananim-recipe-gyedong": {"of": "334d8fda", "story": "Mananim Recipe adalah restoran Korea kecil di gang antara Stasiun Anguk dan Gye-dong. Daftar restoran vegetarian Kota Seoul menilai bibimbap, mi pedas hangat, ketan kacang hijau, dan kari hijaunya sebagai vegan; satu pasta dalam daftar yang sama memakai keju buatan sendiri.", "esg": "Sebagian besar hidangan yang tercantum dinilai vegan dalam daftar restoran vegetarian Kota Seoul."},
  "eomma-siktak-yeonhui": {"of": "3847b3d1", "story": "Eomma Siktak ('Meja Ibu') adalah restoran Korea kecil di Yeonhui-dong yang oleh pemiliknya disebut restoran vegan pada daftar petanya. Dalam praktiknya menunya berpasangan: bibimbap, mi buah dingin, mangkuk nasi burdock, dan kari masing-masing tersedia dalam versi biasa, sebagian dengan daging babi atau sapi, dan versi vegan yang diberi nama tersendiri. Pesanlah hidangan yang bertanda 비건. Letaknya sekitar 20 menit berjalan kaki dari Stasiun Hongik University.", "esg": "Versi vegan untuk setiap hidangan utama, diberi nama tersendiri di menu."},
  "maru-jayeonsik-gimbap-insadong": {"of": "0880839c", "story": "Maru adalah konter jajanan Korea kecil di dalam pusat perbelanjaan Insadong Maru, yang menjual gimbap, tteokbokki, mi, dan sate kue ikan. Daftar restoran vegetarian Kota Seoul menilai setiap item yang dicantumkannya di sini sebagai vegan, termasuk gimbap tahu goreng dan kue ikan nabati; tanyakan tentang apa pun yang tidak ada dalam daftar itu. Tempat duduknya berada di luar konter, di bawah atap.", "esg": "Setiap hidangan pada entri daftar restoran vegetarian Kota Seoul dinilai vegan."},
  "bebab-hongdae": {"of": "86dcc6b7", "story": "Bebab adalah restoran kecil bibimbap dan rebusan dekat Stasiun Hongik University; situs webnya menyebut keluarga di baliknya lebih dahulu menjalankan toko lauk selama satu dekade. Situs itu menyebut setiap hidangan berawal vegan dan daging ditambahkan sebagai pilihan, menandai bibimbap tahu, terung goreng, dan set rebusan tahu lembut sebagai vegan, serta menggambarkan kimchinya sebagai vegan. Dapur yang sama menyajikan hidangan sapi, babi, dan ayam, jadi pesanlah item yang bertanda vegan.", "esg": "Nabati secara bawaan: situsnya menyebut daging ditambahkan ke dasar vegan."},
  "seondong-boribap-seongbuk": {"of": "881d957c", "story": "Seondong Boribap menyajikan nasi jelai dengan sayuran berbumbu, nasi mangkuk batu, dan panekuk di Seongbuk-ro. Catatan pemilik pada daftar petanya menyebut usaha ini sudah berjalan sekitar 40 tahun dan dinobatkan sebagai 'toko seratus tahun' (백년가게) oleh Kementerian UKM dan Startup Korea. Daftar restoran vegetarian Kota Seoul menilai nasi jelai, nasi mangkuk batu, dan panekuk kentang sebagai vegan; hidangan gurita, makanan laut, dan sapi ada di menu yang sama.", "esg": "Tiga hidangan pokok dinilai vegan dalam daftar restoran vegetarian Kota Seoul."},
  "ibap-gyedong": {"of": "ee94739c", "story": "Ibap adalah restoran kecil di gang dari Stasiun Anguk menuju Istana Changdeokgung, yang menyajikan nasi kepal dan mangkuk nasi Korea. Daftar restoran vegetarian Kota Seoul menilai tiga nasi kepalnya sebagai vegan: nasi daun teratai, sayuran liar dengan kacang-kacangan, dan jamur dengan hijiki. Nasi kepal lainnya mengandung ayam, sapi, tuna, atau Spam.", "esg": "Tiga nasi kepal dinilai vegan dalam daftar restoran vegetarian Kota Seoul."},
  "dubu-gongjakso-sadang": {"of": "1357931a", "story": "Dubu Gongjakso menyajikan tahu dalam rebusan tahu lembut, hotpot, dan hidangan set, tidak jauh berjalan kaki dari Stasiun Sadang. Daftar restoran vegetarian Kota Seoul menilai beberapa hidangan sebagai vegan, di antaranya tahu lembut putih polos, bibimbap kecambah dengan tahu lembut, dan tahu goreng wajan; mi susu kedelai khas rumahnya mengandung telur. Sebagian besar menunya berupa daging atau makanan laut, jadi mintalah hidangan tahu polos.", "esg": "Beberapa hidangan tahu dinilai vegan dalam daftar restoran vegetarian Kota Seoul."},
  "alt-a-itaewon": {"of": "66778b72", "story": "ALT.a memasak hidangan yang biasa dipesan orang Korea dari restoran Tionghoa di lingkungan mereka — jajangmyeon kacang hitam, sup mi pedas jjamppong, hidangan goreng asam manis — dengan bahan nabati dan pengganti daging, yang oleh Michelin Guide digambarkan sebagai 100% nabati. Menunya mencakup jajangmyeon truffle, jjamppong jamur, dan jamur enoki renyah dalam saus yurin kecap-cuka. Letaknya di Bogwang-ro, sekitar empat menit berjalan kaki dari pintu keluar 4 Stasiun Itaewon, dan buka untuk makan siang dan makan malam dengan jeda di sore hari.", "esg": "Protein nabati dan pengganti daging sebagai pengganti daging babi dan makanan laut di seluruh menu Korea-Tionghoa"},
  "veggies-yeonhui": {"of": "ddd1807d", "story": "Veggies menyebut dirinya restoran yang vegan sepenuhnya. Hidangannya memadukan masakan Barat dengan sayuran Korea: pasta pesto kucai yang disajikan dengan gosari (pakis) berbumbu, taco rice di atas jelai dengan patty lentil dan jamur, dan gnocchi dalam krim porcini dan susu kedelai. Letaknya di jalan permukiman di Yeonhui-dong, sekitar setengah jam berjalan kaki dari Stasiun Gajwa, sehingga bus atau taksi adalah cara yang lebih mudah untuk ke sana.", "esg": "Susu kedelai, krim tahu, dan lentil sebagai pengganti produk susu dan daging di seluruh menu"},
  "plant-yeonnam": {"of": "b6c24575", "story": "Plant bermula di Itaewon dan menyatakan seluruh perusahaannya 100% vegan; ini adalah restoran keduanya, di sisi Yeonnam kawasan Hongdae. Menu Yeonnam berpusat pada bowl dan wrap — falafel, hummus dengan tempe, lentil, burrito bowl, wrap Caesar tahu — serta kue. Letaknya sekitar lima menit berjalan kaki dari pintu keluar 3 Stasiun Hongik Univ., buka sepanjang hari tanpa jeda, dan tutup pada hari Senin.", "esg": "Menu yang sepenuhnya nabati dari kacang-kacangan, tempe, dan tahu"},
  "plant-bakery-haebangchon": {"of": "b0527834", "story": "Plant Bakery Cafe adalah kafe roti di lantai dua sebuah gedung di Haebangchon, dibuka oleh Plant, yang menjalankan restoran vegan di Itaewon dan Yeonnam; pengelola menggambarkan seluruh usahanya sebagai 100% vegan dan menyebut adanya atap gedung yang dapat disewa. Ini adalah kafe roti, bukan restoran, dan berjarak sekitar sebelas menit berjalan kaki menanjak dari pintu keluar 2 Stasiun Noksapyeong.", "esg": "Kafe roti yang dijalankan oleh usaha yang menyebut dirinya 100% vegan"},
  "yongtokki-imun": {"of": "aecb5613", "story": "Yongtokki menyatakan semua yang dipanggangnya dibuat dari 100% bahan nabati, dipanggang dan dijual pada hari yang sama. Raknya berisi roti khas toko roti Korea — roti kacang merah berisi kacang dari Gunsan, roti garam yang dibuat dengan mentega nabati, brioche susu kedelai berbentuk beruang — di samping bagel dan cinnamon roll, dengan pilihan yang berganti setiap minggu. Letaknya di deretan toko lantai dasar sebuah kompleks apartemen, sekitar lima belas menit berjalan kaki dari pintu keluar 4 Stasiun HUFS, dan tutup pada hari Minggu dan Senin.", "esg": "Mentega nabati dan susu kedelai sebagai pengganti produk susu; dibuat setiap hari dalam jumlah kecil"},
  "ssingpu-coffee-ansan": {"of": "9622d2fc", "story": "Ssingpu Coffee (幸福咖啡, 'kopi kebahagiaan') menyebut dirinya kafe dan toko roti vegan. Tempat ini menyangrai biji kopinya sendiri untuk kopi seduh manual dan memanggang roti beras — roti beras ragi merah, roti garam beras yang dibuat dengan mentega vegan — serta menyajikan patbingsu dengan dasar es susu kedelai. Letaknya di Wolpi-dong, Ansan, jauh dari kereta bawah tanah, jadi rencanakan naik bus atau taksi; tempat ini tutup pada hari Selasa.", "esg": "Tepung beras, susu kedelai, dan mentega vegan sebagai pengganti gandum dan produk susu"},
  "duduri-dupang-mangwon": {"of": "7e434271", "story": "Duduri Dupang memanggang hidangan penutup vegan bebas gluten: gâteau, cheesecake vegan tanpa kacang, spoon cake, brownies tepung beras, dan yogurt susu kedelai ala Yunani, dengan pilihan yang berganti setiap hari. Ini adalah kafe untuk kue dan kopi, bukan untuk makan besar, sekitar lima menit berjalan kaki dari pintu keluar 2 Stasiun Mangwon.", "esg": "Tepung beras dan susu kedelai sebagai pengganti gandum, telur, dan produk susu"},
  "dou-luv-me-bupyeong": {"of": "d567cea2", "story": "Dou Luv Me membuat susu kedelainya sendiri dan membuat semua yang lain darinya: es krim soft-serve kedelai, puding krim kedelai dalam cup, kukis dan sablé, serta soda melon dengan krim kedelai di atasnya. Ini adalah tempat singgah untuk hidangan penutup, bukan tempat untuk makan besar, dua menit berjalan kaki dari pintu keluar 2 Stasiun Bupyeong; hari bukanya berubah-ubah, jadi periksa sebelum berangkat.", "esg": "Susu kedelai buatan sendiri sebagai pengganti produk susu"},
  "ever-halal-yongin": {"of": "3252700b", "story": "Ever Halal adalah restoran Korea yang tidak jauh berkendara dari Everland, dengan andalan bulgogi sapi makan sepuasnya. Pengelola menyatakan daging sapinya berasal dari Australia dan bersertifikat halal resmi, dan Zabihah melaporkan adanya tanda halal di tempat serta tidak ada alkohol. Tidak ada sertifikat yang kami lihat. Letaknya di jalan utama di Pogok-eup, lebih dari dua kilometer dari stasiun Everline terdekat, sehingga bus atau taksi adalah cara yang realistis untuk ke sana."},
  "kwanho-gwanghwamun": {"of": "043dc240", "story": "Kwanho adalah restoran barbeku domba Korea yang berjarak beberapa menit dari Stasiun City Hall. Staf memanggang daging domba di meja dari awal sampai akhir: French rack domba muda, shoulder rack, dan hidangan domba yang diasapi jerami, serta hotpot domba. Menunya memberi label halal pada setiap hidangan domba, dan Halalfoodle mencantumkan restoran ini sebagai tempat yang menyajikan daging halal. Tidak ada sertifikat yang kami lihat, dan bir serta minuman anggur (wine) disajikan. Restoran ini buka setelah tengah hari."},
  "pasha-kebab-sinchon": {"of": "6da7293e", "story": "Pasha Kebab & Burger menyajikan kebab ala Turki dan Mesir, rice box, dan burger sapi di dekat jalan utama Sinchon, buka sampai tengah malam. Zabihah menggambarkannya sebagai restoran halal yang dijalankan pemilik asal Mesir dan tidak menyajikan alkohol, serta menyebut staf menggambarkan makanannya bersertifikat halal. Tidak ada sertifikat yang kami lihat."},
  "nirvana-insadong": {"of": "f1a3fff4", "story": "Nirvana menyajikan kari India Utara, ayam tandoori, biryani, dan aneka roti dari sebuah ruangan di lantai dua di jalan utama Insadong. Zabihah mencatat adanya tanda halal di tempat, pernyataan pengelola bahwa dapurnya '100% Halal', dan tidak ada alkohol. Tidak ada sertifikat yang kami lihat. Pemberitahuan Kakao milik restoran itu sendiri menyebut restoran tutup setiap hari Selasa."},
  "om-restaurant-gwanghwamun": {"of": "7e134305", "story": "Cabang Gwanghwamun dari Om Restaurant menyajikan masakan India Utara dan Nepal, dari samosa dan ayam tandoori hingga tikka domba dan set dal bhat, di ruangan bawah tanah yang dihiasi karya seni Nepal. Zabihah mencantumkannya sebagai halal sepenuhnya dan tidak menyajikan alkohol, berdasarkan perkataan staf bahwa makanannya bersertifikat halal. Tidak ada sertifikat yang kami lihat."},
  "snack-pack-melbourne-paju": {"of": "5c5bb092", "story": "Snack Pack Melbourne di Paju menyajikan 'halal snack pack' khas Australia (kentang goreng dengan ayam, sapi, atau domba dan saus di atasnya) di samping taco dan quesadilla. Zabihah melaporkan bahwa menunya menyatakan makanannya halal, bahwa semua dagingnya diproses secara Islami, dan bahwa alkohol tidak disajikan. Letaknya di kawasan permukiman, lebih dari dua kilometer dari Stasiun Yadang."},
  "sechawan-hoehyeon": {"of": "0b1a78b7", "story": "Sechawan adalah kafe Malaysia di jalan kecil antara Myeongdong dan Hoehyeon yang menampilkan diri sebagai tempat sarapan halal sebelum seharian di kota, buka pukul 8 pagi. Dua direktori halal mencantumkannya sebagai halal sepenuhnya dan tidak menyajikan alkohol, dan Zabihah melaporkan adanya sertifikat halal yang dipajang di tempat. Tidak ada sertifikat yang kami lihat, sehingga lembaga penerbitnya tidak diketahui."},
  "byeollan-ori-changsin": {"of": "d6ba387e", "story": "Byeollan Ori menyajikan bebek dengan dua cara: diasap dan dipanggang dengan kulit renyah, dan sebagai sup bebek yang kental, dengan satu set yang menghadirkan separuh dari masing-masing di meja. Panduan ramah Muslim dari Korea Tourism Organization menggolongkannya sebagai Pork Free (tanpa babi), artinya tidak ada daging babi yang digunakan; itu bukan klaim halal, alkohol dijual, dan tidak ada sertifikat yang kami lihat."},
  "hyeongje-yukhoe-jongno": {"of": "8607afd9", "story": "Hyeongje Yukhoe menyajikan yukhoe, daging sapi mentah yang diiris halus dan dibumbui wijen dan pir, serta daging sapi goreng wajan, bibimbap sapi, dan gurita hidup cincang. Panduan ramah Muslim dari Korea Tourism Organization menggolongkannya sebagai Pork Free (tanpa babi), artinya tidak ada daging babi yang digunakan; daging sapinya tidak disebut halal, alkohol dijual, dan tidak ada sertifikat yang kami lihat."},
  "ildossi-dakgalbi-gwanghwamun": {"of": "ce93ee8e", "story": "Ildossi Dakgalbi memasak dakgalbi, ayam yang ditumis dengan saus gochujang dan sayuran di atas pelat panas di meja Anda, dalam versi polos, taoge, dan keju. Panduan ramah Muslim dari Korea Tourism Organization menggolongkan cabang ini sebagai Pork Free (tanpa babi), artinya tidak ada daging babi yang digunakan; ayamnya tidak disebut halal, dan tidak ada sertifikat yang kami lihat."},
  "ildossi-dakgalbi-bangbae": {"of": "2a9914e3", "story": "Cabang Bangbae dari Ildossi Dakgalbi ini memasak ayam tumis pedas di meja, termasuk versi keju dan versi dengan usus sapi Korea. Panduan ramah Muslim dari Korea Tourism Organization menggolongkannya sebagai Pork Free (tanpa babi), artinya tidak ada daging babi yang digunakan; dagingnya tidak disebut halal, dan tidak ada sertifikat yang kami lihat."},
  "hamcho-ganjang-gejang-myeongdong": {"of": "e4e1e82f", "story": "Hamcho Ganjang Gejang mengkhususkan diri pada ganjang-gejang, rajungan mentah yang diperam dalam kecap asin, di sini dibumbui dengan hamcho (glasswort), di samping versi berbumbu pedas dan rebusan makanan laut. Panduan ramah Muslim dari Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menawarkan beberapa hidangan halal sementara mungkin menjual alkohol; alkohol dijual di sini dan kami belum melihat sertifikat halalnya."},
  "itaewon-kitchen": {"of": "61f12976", "story": "Itaewon Kitchen berada di atas satu deret anak tangga di Usadan-ro dekat Masjid Pusat Seoul, dengan menu campuran: nasi lemak Malaysia, kebab koobideh Iran, serta piza dan hidangan nasi dengan daging domba atau ayam. Panduan Korea Tourism Organization mencantumkannya sebagai Self-certified, artinya pemilik menyatakan makanannya halal, dan situs pariwisata Seoul mencatat adanya juru masak Muslim dan tidak ada alkohol. Tidak ada sertifikat yang kami lihat, karena pernyataan halal oleh pemilik sendiri memang tidak memiliki sertifikat."},
  "kervan-cafe-usadan": {"of": "079306fa", "story": "Kervan Café adalah gerai hidangan penutup dan brunch milik grup Turki Kervan, di gang di bawah Masjid Pusat Seoul. Tempat ini menyajikan kaymak (krim kental) dengan roti dan madu, baklava, simit, Turkish delight, menemen, dan kopi atau teh Turki. Panduan Korea Tourism Organization mencantumkannya sebagai Self-certified, artinya pemilik menyatakan makanannya halal, dan situs pariwisata Seoul mencatat tidak ada alkohol yang dijual. Tidak ada sertifikat yang kami lihat."},
  "kervan-bakery-itaewon": {"of": "7d241744", "story": "Kervan Bakery menjual kue-kue Turki buatan seorang koki pastry Turki: baklava, Turkish delight, kukis, dan puding, serta kaymak dengan roti. Panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai Halal-certified, kategori yang dikhususkannya bagi lembaga sertifikasi terakreditasi seperti Korea Muslim Federation, tetapi tidak ada sertifikat yang kami lihat dan halaman pariwisata yang sekarang tidak lagi menampilkan kategori itu."},
  "kali-daehakro": {"of": "92bf3bd9", "story": "Kali memasak kari India Utara, di antaranya chicken makhani, korma, vindaloo, dan prawn masala, di lantai atas di sebuah jalan di kawasan teater Daehak-ro dekat Stasiun Hyehwa. Panduan Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menawarkan beberapa hidangan halal sementara mungkin menjual alkohol. Kami belum melihat sertifikat halalnya."},
  "couscous-seochon": {"of": "35013e8b", "story": "CousCous menyajikan hidangan Tunisia di dekat Gyeongbokgung: couscous dengan rebusan, brik (pastry renyah berisi) dan ojja (telur yang dimasak dalam saus tomat berbumbu), sebagian besar sebagai menu set. Panduan Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menawarkan beberapa hidangan halal sementara mungkin menjual alkohol. Kami belum melihat sertifikat halalnya."},
  "durga-gwanghwamun": {"of": "18c2b767", "story": "Durga memasak kari domba dan ayam, roti tandoor, dan set makan siang di lantai bawah tanah Le Meilleur Jongno Town, di antara Jonggak dan Gwanghwamun. Panduan Korea Tourism Organization menggolongkan cabang utama ini sebagai ramah Muslim, kategori yang didefinisikannya sebagai menawarkan beberapa hidangan halal sementara mungkin menjual alkohol. Kami belum melihat sertifikat halalnya."},
  "luna-asia-samseong": {"of": "6bc24dbd", "story": "Luna Asia menyajikan hidangan India, yaitu butter chicken, ayam tandoori, palak paneer, biryani domba, dan kadai gosht, di jalan kecil di Samseong-dong. Panduan Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menawarkan beberapa hidangan halal sementara mungkin menjual alkohol. Kami belum melihat sertifikat halalnya."},
  "casablanca-sandwicherie": {"of": "b302713a", "story": "Casablanca membuat sandwich ala Maroko, yaitu ayam berbumbu, domba dengan cabai, udang berbumbu, dan omelet Berber, di sebuah kedai kecil di Sinheung-ro, Haebangchon. Panduan Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menawarkan beberapa hidangan halal sementara mungkin menjual alkohol. Kami belum melihat sertifikat halalnya."},
  "manokamana-daehakro": {"of": "24d6a066", "story": "Cabang Daehak-ro dari Manokamana menyajikan ayam tandoori, butter chicken, mutton tikka, dan biryani di dekat Stasiun Hyehwa. Panduan Korea Tourism Organization menggolongkan cabang ini sebagai ramah Muslim, kategori yang didefinisikannya sebagai menawarkan beberapa hidangan halal sementara mungkin menjual alkohol. Ini adalah cabang yang terpisah dari Manokamana Songdo, yang sudah ada di peta. Kami belum melihat sertifikat halalnya."},
  "hello-india-yeonnam": {"of": "e58e56fd", "story": "Hello India menyajikan kari ayam, kari daging domba dewasa (mutton), dan kari makanan laut serta chowmein di jalan kecil di Yeonnam-dong. Panduan Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menawarkan beberapa hidangan halal sementara mungkin menjual alkohol. Kami belum melihat sertifikat halalnya."},
  "om-restaurant-gongdeok": {"of": "14fc3461", "story": "Cabang Gongdeok dari Om menyajikan ayam tandoori, chicken malai kebab, tikka domba, kari dengan naan, dan thali harian di dekat Stasiun Gongdeok. Panduan Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menawarkan beberapa hidangan halal sementara mungkin menjual alkohol. Ini adalah cabang yang terpisah dari Om Restaurant Gwanghwamun. Kami belum melihat sertifikat halalnya."},
  "kitchen-of-india-jamsil": {"of": "bd564f8d", "story": "Kitchen of India menyajikan ayam tandoori, chicken tikka dan mutton tikka, seekh kebab, kari, dan biryani di sebuah unit bawah tanah di Olympic-ro dekat Stasiun Jamsil. Panduan Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menawarkan beberapa hidangan halal sementara mungkin menjual alkohol. Restoran ini tutup pada hari Senin. Kami belum melihat sertifikat halalnya."},
  "manokamana-sinchon": {"of": "9889d189", "story": "Cabang Sinchon dari Manokamana menyajikan butter chicken, mutton korma, prawn masala, serta kari lentil dan sayuran, beberapa menit dari Stasiun Sinchon. Panduan Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menawarkan beberapa hidangan halal sementara mungkin menjual alkohol. Salah satu setnya disertai pilihan lassi atau anggur merah. Ini adalah cabang yang terpisah dari Manokamana Daehak-ro dan Manokamana Songdo. Kami belum melihat sertifikat halalnya."},
  "pooja-2-dongdaemun": {"of": "996a4b95", "story": "Pooja 2 menyajikan ayam tandoori, kari ayam dan kari domba, biryani, serta paket thali, beberapa menit dari Stasiun Dongdaemun History & Culture Park. Panduan Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menyediakan sebagian hidangan halal dan mungkin menjual alkohol. Kami belum melihat sertifikat halalnya."},
  "aangan-ewha": {"of": "bccf63de", "story": "Aangan Ewha menyajikan ayam tandoori dan ayam afghani, hidangan tikka campur, serta kari ayam, domba, udang, dan paneer di jalan menuju Ewha Womans University. Panduan Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menyediakan sebagian hidangan halal dan mungkin menjual alkohol. Kami belum melihat sertifikat halalnya."},
  "taj-myeongdong": {"of": "80442c35", "story": "Taj Myeongdong menyajikan chicken tikka masala, palak paneer, vindaloo udang, biryani, dan paket makan siang hari kerja dari lantai dua yang menghadap Katedral Myeongdong. Panduan Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menyediakan sebagian hidangan halal dan mungkin menjual alkohol. Restoran ini tutup pada hari Senin. Kami belum melihat sertifikat halalnya."},
  "yeougol-sushi-seogyo": {"of": "8f06c942", "story": "Yeougol Sushi Seogyo menyajikan paket sushi, potongan perut tuna, sashimi campur, dan nasi mangkuk dengan ikan mentah di dekat Stasiun Hongik University. Panduan Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menyediakan sebagian hidangan halal dan mungkin menjual alkohol. Menunya sebagian besar ikan dan hidangan laut; sushi daging sapi Wagyu dan ayam gorengnya tidak disebut halal, dan sake, bir, serta soju dijual di sini. Kami belum melihat sertifikat halalnya."},
  "delhi-india-sangsu": {"of": "dfd334c6", "story": "Delhi India menyajikan butter chicken, kari ayam dan kari domba, hidangan udang, ayam tandoori, serta kari paneer dan kari sayuran di sebuah jalan kecil antara Sangsu dan Hapjeong. Panduan Korea Tourism Organization menggolongkannya sebagai ramah Muslim, kategori yang didefinisikannya sebagai menyediakan sebagian hidangan halal dan mungkin menjual alkohol. Salah satu paketnya disajikan dengan pilihan lassi atau minuman anggur (wine). Kami belum melihat sertifikat halalnya."},
  "loving-hut-yeongdong": {"of": "2ebeacb4", "story": "Loving Hut Yeongdong adalah cabang Yeongdong dari Loving Hut, jaringan restoran vegan yang situs Koreanya menyatakan bahwa setiap hidangan di menunya vegan dan tidak mengandung bahan hewani. Restoran ini terletak di jalan utama Yongsan-myeon dan tutup pada hari Rabu. Jaraknya sekitar 19 km lewat jalan darat dari Stasiun Yeongdong, sehingga mobil atau bus lokal adalah cara yang realistis untuk mencapainya.", "esg": "Standar vegan untuk seluruh jaringan yang tidak mengizinkan bahan hewani."},
  "yeobeop-bapsang-daejeon": {"of": "c0bbddd1", "story": "Yeobeop Bapsang adalah dapur kecil masakan kuil di Jeonmin-dong, di bagian utara Yuseong-gu. HappyCow menggambarkannya sebagai masakan kuil Buddha Korea yang vegan, disajikan sebagai satu paket berisi sup, nasi, dan lauk pendamping, pada jam makan siang dan dengan reservasi. Dapur yang sama pernah memasak daging dan hidangan laut untuk pesanan rombongan pribadi, jadi saat memesan tempat, sampaikan bahwa Anda menginginkan paket vegan. Letaknya jauh dari kereta bawah tanah; naiklah bus atau taksi.", "esg": "Masakan kuil Korea yang berbahan dasar sayuran musiman."},
  "chayhana-daejeon": {"of": "b04cf4ad", "story": "Chayhana adalah restoran Uzbek di sebuah jalan kecil dekat Woosong University di Dong-gu. Direktori halal Zabihah mencantumkannya sebagai halal sepenuhnya dan tidak menjual alkohol, dengan mengutip pengelolanya: 'Hanya makanan yang dijamin halal yang disajikan'. Direktori itu juga mencatat adanya sertifikat dalam berkasnya, tetapi tidak ada sertifikat yang kami lihat. Jaraknya sekitar 25 menit berjalan kaki dari Stasiun Daedong di Jalur 1 Metro Daejeon."},
  "afiya-halal-gungdong": {"of": "3d1a918a", "story": "Afiya Halal Restaurant adalah restoran Asia Tengah di Gung-dong, kawasan mahasiswa di dekat Chungnam National University. Akun Instagram milik pengelolanya sendiri menggambarkan makanannya sebagai makanan halal Uzbek, India, dan Turki. Menunya berpusat pada daging domba muda, sapi, dan ayam, termasuk kue somsa dan paket sate tusuk. Tidak ada sertifikat yang diklaim, dan salah satu saladnya berisi sosis yang jenis dagingnya tidak disebutkan, jadi tanyakanlah. Restoran ini berbagi ruang dengan sebuah toko bahan makanan kecil, dan jaraknya sekitar setengah jam berjalan kaki dari Stasiun Yuseong Spa."},
  "dongmoon-nami-island": {"of": "eb29f954", "story": "Dongmoon adalah restoran fusion Asia di lantai satu Baplex, di tengah Pulau Nami. Situs pulau itu sendiri menyatakan bahwa makanan halal tersedia di sini bagi pengunjung Muslim dan menyebutnya restoran halal bersertifikat. Daftar sertifikat KMF menunjukkan sertifikat restoran yang masih berlaku atas nama NAMMOON, Inc., perusahaan yang terdaftar di alamat pulau itu, tetapi sertifikat tersebut tidak menyebut nama Dongmoon sendiri. Menurut halaman tanya jawab pulau itu, ruang salatnya berada di gedung Baplex yang sama. Pulau Nami dicapai dengan feri dari dermaga di sisi Gapyeong, jadi sediakan waktu untuk penyeberangan."},
  "plantiful-gangneung": {"of": "e11a3f22", "story": "Plantiful menyebut dirinya sebagai tempat pembuatan krim dan toko roti vegan. Produk yang tercantum adalah keju krim nabati yang difermentasi dengan kultur yang ditumbuhkan dari biji-bijian organik Korea yang dikecambahkan. Sebagian besar penjualannya dilakukan lewat pengiriman paket dan tempat ini pernah mengumumkan libur musiman, jadi periksa halaman Kakao atau Instagram-nya sebelum berjalan kaki 14 menit dari Stasiun Gangneung. Tempat ini adalah toko, bukan restoran untuk makan di tempat.", "esg": "Keju nabati yang difermentasi dengan kultur dari biji-bijian Korea yang dikecambahkan."},
  "may-green-wonju": {"of": "d74fcfa2", "story": "May Green adalah kafe sekaligus toko roti di Musil-dong, Wonju. Menunya di DiningCode melabeli banyak bagel dan roll cake tepung berasnya sebagai vegan dan dibuat tanpa tepung terigu, dengan isian krim susu kedelai. Sebagian minumannya memakai produk susu atau susu kental manis, jadi tanyakan mana saja yang vegan saat Anda memesan."},
  "batmat-yangyang": {"of": "0a5cd68f", "story": "Batmat menyajikan pasta segar, risotto, dan salad yang dibuat dari tanaman pangan asli Korea. Menunya mencantumkan hummus dari kedelai asli Bukdaegi, 'couscous' dari jewawut, dan pasta segar yang dibuat dari varietas gandum Korea. Menu di DiningCode menggambarkan pasta wijen hitamnya, yang dibuat dengan krim kedelai, sebagai vegan; menunya berganti mengikuti musim, jadi tanyakan apa yang nabati pada hari itu. Jam bukanya singkat dan reservasi dianjurkan. Letaknya cukup jauh di luar kota Yangyang, jadi datanglah dengan mobil atau taksi.", "esg": "Menu yang disusun dari varietas benih asli Korea berupa kacang-kacangan, gandum, dan jewawut."},
  "asalam-jeju": {"of": "bdfe12fa", "story": "Asalam adalah restoran Yaman di pusat kota lama Kota Jeju. Profilnya sendiri menggambarkannya sebagai halal serta menyajikan makanan Yaman autentik dan makanan vegan, dan HappyCow melaporkan adanya ruang salat bagi tamu Muslim. Menunya meliputi hidangan nasi dengan daging domba muda dan ayam, wrap, hummus, dan falafel. Panduan ramah Muslim Korea Tourism Organization tahun 2021 mencantumkannya sebagai bersertifikat halal, tetapi tidak ada sertifikat yang kami lihat."},
  "bagdad-jeju": {"of": "652108ef", "story": "Bagdad telah menyajikan masakan India Utara di Kota Jeju sejak 2005. Pada Maret 2022 restoran ini pindah dari dekat Balai Kota ke pusat kota lama, beberapa jalan dari Pasar Dongmun. Profilnya sendiri menggambarkan makanannya sebagai masakan India halal, dan panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai ramah Muslim. Menunya mencakup kari seperti chicken masala dan korma, biryani, dan hidangan tandoori, dengan beberapa kari vegan."},
  "biwon-samgyetang-jeju": {"of": "3dd08beb", "story": "Biwon Samgyetang adalah restoran Korea yang berpusat pada samgyetang, ayam muda yang direbus perlahan dengan ginseng dan beras, tidak jauh berjalan kaki dari Arboretum Halla di Kota Jeju. Pada November 2025 restoran ini menjadi salah satu dari empat restoran di Jeju yang diberitakan pers menerima sertifikat halal Indonesia yang mencakup tempat usaha dan dapurnya, yang diserahkan oleh PT SUCOFINDO dan HPN-K. Tidak ada sertifikat yang kami lihat. Sup iga sapi juga ada di menunya."},
  "crab-story-jeju-airport": {"of": "d93e6b1c", "story": "Crab Story Jeju Airport menyajikan kepiting salju, kepiting raja, dan lobster, dengan bubur abalon pada jam makan siang, di jalan pesisir Seohaean-ro tepat di sebelah barat Bandara Internasional Jeju. Pada November 2025 restoran ini menjadi salah satu dari empat restoran di Jeju yang diberitakan pers menerima sertifikat halal Indonesia yang mencakup tempat usaha dan dapurnya. Tidak ada sertifikat yang kami lihat. Kepiting dan lobster dijual dengan harga pasar."},
  "loving-hut-jeju-seogwipo": {"of": "907b6160", "story": "Loving Hut Jeju Seogwipo adalah cabang Jeju dari Loving Hut, jaringan restoran vegan yang situs Koreanya menyatakan bahwa setiap hidangan di menunya vegan dan tidak mengandung bahan hewani. Restoran ini terletak di jalan raya pesisir Iljudong-ro di Namwon-eup, antara Seogwipo dan Pyoseon. Cabang ini menerima reservasi lewat telepon.", "esg": "Menu vegan untuk seluruh jaringan tanpa bahan hewani."},
  "e-um-jeju": {"of": "a43bd9bc", "story": "E-um menyajikan satu paket vegan musiman, yang dimasak dengan gaya masakan rumahan Korea, dari sebuah ruangan kecil di jalan pesisir dekat Batu Yongduam di Kota Jeju. HappyCow mencantumkannya sebagai restoran vegan dan DiningCode menggolongkannya sebagai vegan; paketnya berganti setiap bulan. Tempat ini buka pada sore hari dari Kamis hingga Senin, dan HappyCow menyebut reservasi diwajibkan."},
  "tathata-aewol": {"of": "d5faa45f", "story": "Tathata adalah kafe kecil di desa Aewol di pesisir barat laut Jeju yang oleh HappyCow dicantumkan sebagai vegan sepenuhnya, menyajikan bingsu, hidangan penutup es serut Korea, dan minuman. Kafe ini buka pada sore hari, Kamis hingga Minggu."},
  "andyu-cafe-hallim": {"of": "9b0f35e3", "story": "And Yu Cafe adalah kafe dan dapur vegan di jalan utama yang melintasi Hallim di pesisir barat Jeju, yang oleh HappyCow dicantumkan sebagai vegan sepenuhnya dan, menurut kata-katanya, dijalankan sebagai kafe vegan Inggris/Korea sejak 2018. Menu saat ini memuat sandwich tempe dan tahu, burger, quesadilla, dan kari hijau Thailand. Bir disajikan di sini."},
  "vegan-table-baram-aewol": {"of": "286a9311", "story": "Vegan Table Baram adalah kafe vegan di Napeup, sebuah desa pedalaman di Aewol, yang oleh HappyCow dicantumkan sebagai vegan, menyajikan roti dan kue panggang, salad, pasta, dan hidangan brunch. Jam bukanya berbeda-beda antara satu daftar dan daftar lain, jadi periksa dulu sebelum berangkat."},
  "cafe-901-jeju": {"of": "b391045d", "story": "Cafe 901 adalah kafe vegan di jalan pegunungan 1100-ro di selatan Kota Jeju, yang oleh HappyCow dicantumkan sebagai vegan dan digambarkan sebagai kafe makanan mentah dan detoks yang berdiri pada 2017. Menunya memuat jus cold-pressed, smoothie, sup, salad, dan sandwich seperti sandwich jamur. Tempat ini dicapai dengan berkendara atau naik taksi dari kota."},
  "five-seventh-gujwa": {"of": "ae0c4cc0", "story": "Five Seventh adalah kafe vegan yang menghadap ke laut di jalan pesisir Haemajihaean-ro di Gujwa, di timur laut Jeju. HappyCow mencantumkannya sebagai vegan, menyajikan burger, focaccia, mi, salad, dan roti serta kue panggang, dengan satu rak kecil bahan makanan."},
  "sunshine-walk-seogwipo": {"of": "2ca9b3c4", "story": "Sunshine Walk adalah kafe vegan kecil di Sangye-dong, sebuah desa di pedalaman dari kawasan resor Jungmun di Seogwipo. HappyCow mencantumkannya sebagai vegan, menyajikan hidangan dengan keju tahu, selai sayuran, dan kopi, serta mencatat bahwa tempat parkirnya berada di dekat balai desa Sangye 1-dong, satu menit berjalan kaki dari kafe. Kafe ini hanya buka beberapa hari dalam seminggu."},
  "avec-aewol": {"of": "6f872cff", "story": "Avec adalah restoran di lantai dua sebuah gedung di jalan pesisir Aewol, di sebelah barat Kota Jeju, yang oleh HappyCow dicantumkan sebagai vegan. HappyCow menggambarkan menu comfort food berupa sandwich terbuka, burger, dan pasta. Restoran ini tutup pada hari Rabu."},
  "dasoni-jeju": {"of": "0bafe5ce", "story": "Dasoni adalah rumah teh dan restoran tradisional Korea di Ora-dong, Kota Jeju, dengan taman dan tempat duduk lesehan. HappyCow menggambarkannya sebagai masakan Buddha dalam suasana yang tenang dan menyebut hidangannya dapat dibuat tanpa bawang-bawangan (allium), tetapi dapurnya tidak vegan sepenuhnya: kimchinya mengandung ikan, jadi tanyakan apa saja kandungan setiap hidangan. Menunya mencakup sujebi perilla, bibimbap, nasi daun teratai, jeli biji ek, dan beragam teh."},
  "vegi-narang-kitchen-geochang": {"of": "6dea927f", "story": "Vegi Narang Kitchen adalah restoran vegan di lantai dua sebuah gedung di Namha-myeon, di pedesaan sebelah timur kota Geochang. HappyCow mencantumkannya sebagai vegan dan menggambarkan masakannya sebagai masakan kuil yang dibuat tanpa lima umbi berbau tajam (bawang putih, bawang bombai, dan kerabatnya). HappyCow menyebut salad jamur, kotlet kedelai, dan avocado roll di antara hidangannya, dan menu di Kakao Map mencantumkan tiga hidangan yang sama. Restoran ini melayani makan siang dan makan malam dengan jeda pada sore hari; hari tutupnya belum pasti, jadi periksa dulu sebelum bepergian. Letaknya jauh dari terminal bus Geochang, jadi rencanakan untuk naik taksi.", "esg": "Dapur nabati di sebuah kabupaten pedesaan."},
  "cafe-narang-geochang": {"of": "d328a4d0", "story": "Cafe Narang adalah kafe vegan yang berjarak beberapa pintu dari Vegi Narang Kitchen di Namha-myeon, Geochang. HappyCow mencantumkannya sebagai vegan dan menggambarkannya sebagai kafe meditasi di dalam sebuah komunitas Buddha, yang menyajikan granola, yogurt, dan kue keberuntungan; Kakao Map mencantumkan kopi, teh, dan ade, dengan latte yang disebut vegan. Kafe ini tutup pada hari Senin. Kunjungan ke sini paling baik digabungkan dengan makan di Vegi Narang Kitchen, karena keduanya harus dicapai dengan taksi dari terminal bus Geochang."},
  "loving-hut-jinju": {"of": "040e5a0f", "story": "Loving Hut Jinju adalah cabang Jinju dari Loving Hut, jaringan restoran vegan yang situs Koreanya menyatakan bahwa setiap hidangan di menunya vegan dan tidak mengandung bahan hewani. Halaman cabang ini dan Kakao Map sama-sama mencantumkan hidangan bergaya Korea seperti bibimbap sayuran, sup pangsit, dan kotlet kedelai beras cokelat. Jam bukanya berbeda antara pengelola, Kakao Map, dan dua direktori, jadi teleponlah sebelum Anda berangkat. Letaknya di Hadae-dong, sekitar empat kilometer dari terminal bus antarkota.", "esg": "Standar vegan untuk seluruh jaringan yang tidak mengizinkan bahan hewani maupun produk sampingannya."},
  "ssongddi-and-bread-changwon": {"of": "d15b1a21", "story": "Ssongddi & Bread adalah toko roti kecil di Dogye-dong, Changwon, yang oleh HappyCow dicantumkan sebagai vegan sepenuhnya: kue kering, baguette, scone, dan sandwich yang dibuat dengan mayones vegan buatan sendiri dan ham nabati, serta kue tar dengan pesanan di muka. Kakao Map mencantumkan roti beras dan latte gandum oat atau kedelai. Toko ini buka Selasa hingga Sabtu. Jaraknya sekitar tiga setengah kilometer dari Stasiun Changwon, jadi naiklah bus atau taksi."},
  "yeonggam-yeonggam-ulsan": {"of": "9b986eb7", "story": "Yeonggam Yeonggam menyebut dirinya kompleks budaya vegan, dan HappyCow menggambarkannya sebagai kafe hidangan penutup yang vegan sepenuhnya dan juga menjadi tempat pertunjukan, kelas, dan pertemuan. HappyCow mencantumkan kopi, teh, latte kedelai, kue tar, madeleine, dan wafel. Tempat ini berada di Okgyo-ro di Jung-gu, pusat kota lama Ulsan. Hari bukanya berbeda antara satu sumber dan sumber lain, jadi periksa dulu sebelum berangkat. Ulsan tidak memiliki kereta bawah tanah: jaraknya sekitar tiga setengah kilometer dari Stasiun Taehwagang."},
  "mimigotgan-ulsan": {"of": "440c1b70", "story": "Mimigotgan adalah toko roti kecil di Yaeum-dong, Nam-gu, yang oleh HappyCow dicantumkan sebagai toko roti vegan yang menjual roti, kue kering, dan kue tar. Menu di Kakao Map saat ini menampilkan roti tawar beras ragi merah. Toko ini buka Senin hingga Sabtu dari 11:00 hingga 18:00. Jaraknya sekitar empat kilometer dari Stasiun Taehwagang, jadi naiklah bus atau taksi."},
  "gimye-mebbangso-gimhae": {"of": "24425f14", "story": "Gimye Mebbangso adalah kafe sekaligus toko roti di Nae-dong, Gimhae, yang oleh HappyCow dicantumkan sebagai vegan sepenuhnya. Pemiliknya menggambarkan tempat ini memanggang tanpa mentega, telur, susu, tepung putih, atau gula putih, dan menunya di Kakao Map mencantumkan sandwich vegan, scone, kue kering, dan roti beras berkulit tipis dengan isian pasta kacang merah atau pasta kacang arab. Tempat ini juga mengadakan kelas membuat roti dan kue vegan. Hari bukanya berbeda antara satu sumber dan sumber lain, jadi periksa dulu sebelum berangkat. Jaraknya sekitar 16 menit berjalan kaki dari Stasiun Yeonji Park di jalur kereta ringan Busan–Gimhae."},
  "taj-mahal-gimhae": {"of": "e824adcc", "story": "Taj Mahal Gimhae adalah restoran India di lantai dua sebuah gedung di Seosang-dong. Zabihah mencantumkannya sebagai halal sepenuhnya dengan alkohol tidak diperbolehkan dan melaporkan adanya sertifikat halal dalam berkasnya; tidak ada sertifikat yang kami lihat. Menunya mencantumkan kari ayam, sapi, dan domba muda, tandoori, biryani, dan hidangan panggang Arab, tanpa babi. Jaraknya sekitar delapan belas menit berjalan kaki dari Stasiun Suro King's Tomb di jalur kereta ringan Busan–Gimhae."},
  "samsoo-jangeo-suseong": {"of": "91e3787d", "story": "Samsoo Jangeo menyajikan belut panggang sebagai paket makan, di atas nasi, atau dalam sup, di lantai dua sebuah gedung di Sincheondong-ro di Suseong-gu. Baik situs kuliner Kota Daegu maupun panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai ramah Muslim, kategori yang memperbolehkan alkohol dan berarti sebagian atau semua hidangannya halal; ini masakan Korea, bukan jenis masakan yang biasa ditemukan dalam daftar halal. Kami belum melihat sertifikat halalnya, jadi tanyakan hidangan mana yang halal saat Anda memesan."},
  "new-saladin-seongseo": {"of": "19118765", "story": "New Saladin Seongseo, cabang Seongseo dari New Saladin, memasak masakan India dan Pakistan, dari ayam tandoori hingga seekh kebab domba dan kari, di lantai tiga sebuah gedung dekat kampus Seongseo Keimyung University. Situs kuliner Kota Daegu dan panduan Korea Tourism Organization tahun 2021 sama-sama mencatatnya sebagai bersertifikasi mandiri: dikelola atau dimasak oleh Muslim dan dinyatakan halal oleh pemiliknya, tanpa sertifikat dari pihak ketiga. Panduan tahun 2021 juga mencantumkannya sebagai memiliki ruang salat; tanyakan saat tiba apakah ruang itu masih tersedia."},
  "new-saladin-dongseongro": {"of": "b34d40ab", "story": "New Saladin Dongseong-ro, cabang pusat kota dari New Saladin, menyajikan paket makan India yang berpusat pada kari, naan, samosa, dan ayam tandoori, di sebuah ruang bawah tanah di dekat Dongseong-ro, jalan perbelanjaan utama Daegu. Situs kuliner Kota Daegu dan panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai ramah Muslim, yang berarti sebagian atau semua hidangannya halal dan alkohol mungkin dijual, dan direktori Halalfoodle menggambarkannya sebagai halal sebagian. Kami belum melihat sertifikat halalnya."},
  "baraji-dongseongro": {"of": "13c0d5d5", "story": "Baraji Restaurant (Balaji dalam panduan pariwisata) menyajikan masakan India dan Nepal seperti biryani, pangsit momo, paneer, dan dal di Dongseong-ro di pusat Daegu; situs kuliner kota itu menyebut juru masaknya orang Nepal. Kota Daegu dan panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai ramah Muslim, yang berarti sebagian atau semua hidangannya halal sementara alkohol mungkin dijual, dan direktori Halalfoodle menandainya sebagai menyajikan alkohol. Kami belum melihat sertifikat halalnya."},
  "tara-banwoldang": {"of": "4590d383", "story": "Tara menyajikan hidangan India dan Nepal seperti ayam tandoori, kari ayam dan kari udang, paneer, dan naan, di lantai tiga sebuah gedung dekat Stasiun Banwoldang. Situs kuliner Kota Daegu dan panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai ramah Muslim, yang berarti sebagian atau semua hidangannya halal sementara alkohol mungkin dijual; alkohol, termasuk soju, dijual di sini. Kami belum melihat sertifikat halalnya."},
  "indo-bangnanggi-knu": {"of": "408bbf1f", "story": "Indo Bangnanggi menyajikan hidangan India seperti chicken tikka, dal makhani, dan salmon tandoori di gerbang utara Kyungpook National University. Situs kuliner Kota Daegu dan panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai ramah Muslim, yang berarti sebagian atau semua hidangannya halal sementara alkohol mungkin dijual. Kami belum melihat sertifikat halalnya. Tidak ada stasiun metro di dekatnya; bus berhenti di gerbang utara universitas tersebut."},
  "taj-mahal-in-korea-sinmae": {"of": "f8d2cb2f", "story": "Taj Mahal in Korea menyajikan hidangan India seperti ayam tandoori, kari domba muda dan kari domba, palak paneer, dan biryani di lantai dua sebuah gedung dekat Stasiun Sinmae. Situs kuliner Kota Daegu dan panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai ramah Muslim, yang berarti sebagian atau semua hidangannya halal sementara alkohol mungkin dijual; sebuah ulasan pengunjung menyebut minuman anggur (wine) India. Kami belum melihat sertifikat halalnya."},
  "raga-sinmae": {"of": "771ad8f0", "story": "Raga memasak kari India dan Pakistan seperti murgh makhani, rogan josh, dan mutton do pyaza, di sebuah jalan kecil dekat Stasiun Sinmae. Situs kuliner Kota Daegu dan panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai ramah Muslim, yang berarti sebagian atau semua hidangannya halal sementara alkohol mungkin dijual. Kami belum melihat sertifikat halalnya."},
  "loving-hut-pyeonghwa-daegu": {"of": "0bb0a8a7", "story": "Loving Hut Pyeonghwa adalah cabang Daegu dari Loving Hut, jaringan vegan yang situs Koreanya menyatakan bahwa setiap hidangan dan bahan harus vegan sepenuhnya. Menunya condong ke masakan Korea: paket makan, ssambap berupa nasi bungkus daun dengan bulgogi vegan, hotpot bulgogi kedelai, dan sup biji perilla, di samping 'ayam' kedelai dan mi Korea-Tionghoa. Restoran ini hanya buka untuk makan siang, Senin hingga Sabtu, dan berjarak sekitar 25 menit berjalan kaki dari Stasiun Dongdaegu."},
  "ohaeng-color-food-bongdeok": {"of": "7848faac", "story": "Ohaeng Color Food membuat gimbap gulung sesuai pesanan, dari isian kubis dan jamur hingga versi daging kedelai, di samping nasi kembang kol dan salad. Menunya menyebut kari vegan dan, di DiningCode, pizza persegi vegan yang dibuat tanpa tepung terigu; menu lainnya mencakup gimbap cumi kering, jadi ini menu campuran yang memiliki pilihan vegan, bukan dapur vegan. Tanyakan gimbap mana yang bebas telur dan kecap ikan."},
  "park-soseon-halmae-gomtang-hyeonpung": {"of": "b16db36a", "story": "Wonjo Hyeonpung Park So-seon Halmaejip Gomtang adalah restoran di Hyeonpung, di kabupaten Dalseong di selatan Daegu, yang menyajikan gomtang, sup bening dari daging sapi yang direbus lama, beserta versi babat sapi dan buntut sapi serta hidangan daging sapi rebus. Situs kuliner Kota Daegu dan panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai tanpa babi: restoran ini tidak menyajikan babi, meskipun daging sapinya tidak disebut halal. Letaknya di luar jaringan metro, jadi rencanakan untuk naik bus atau mobil."},
  "juwangsan-samgyetang-hyeonpung": {"of": "978af3ac", "story": "Juwangsan Samgyetang Hyeonpung, cabang Hyeonpung dari Juwangsan Samgyetang, menyajikan samgyetang, ayam muda yang diisi beras dan direbus perlahan dengan ginseng, dalam sekitar delapan belas versi, dari yang polos hingga kuah perilla, abalon, dan ramuan herbal obat. Situs kuliner Kota Daegu dan panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai tanpa babi: babi tidak disajikan, meskipun ayamnya tidak disebut halal. Letaknya di luar jaringan metro, jadi rencanakan untuk naik bus atau mobil."},
  "yeonhwajeong-samgyetang-nongong": {"of": "8f6ddadc", "story": "Yeonhwajeong Samgyetang Nongong, di Nongong, menyajikan samgyetang, ayam muda utuh yang direbus perlahan dengan beras dan ginseng, dalam beberapa versi termasuk kuah abalon dan kuah jamur obat, serta sup nasi tiram pada musimnya. Situs kuliner Kota Daegu dan panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai tanpa babi: babi tidak disajikan, meskipun ayamnya tidak disebut halal. Letaknya di luar jaringan metro, jadi rencanakan untuk naik bus atau mobil."},
  "beotkkot-nadeul-beoseotjip-okpo": {"of": "e29bc29e", "story": "Beotkkot Nadeul Beoseotjip, yang namanya berarti 'rumah jamur tamasya bunga sakura', menyajikan hotpot dan sup jamur Korea, termasuk jamur neungi (scaly hedgehog), beserta hidangan bebek dan ayam, di Okpo di tepi selatan Daegu. Situs kuliner Kota Daegu dan panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai tanpa babi: babi tidak disajikan, meskipun dagingnya tidak disebut halal. Letaknya di luar jaringan metro, jadi rencanakan untuk naik bus atau mobil."},
  "vegenarang-gwangalli": {"of": "f7b2d97a", "story": "Vegenarang Gwangalli menyajikan masakan Korea bergaya kuil di lantai sembilan sebuah gedung dekat tepi laut Millak di ujung timur Pantai Gwangalli. HappyCow menggambarkannya sebagai restoran yang vegan sepenuhnya, dan dapurnya sendiri menggambarkan masakannya sebagai masakan kuil yang dimasak tanpa lima sayuran berbau tajam. Paket makannya terdiri atas nasi daun teratai, rebusan tahu lembut, kotlet kacang, dan lauk pendamping musiman. Jaraknya lebih dari dua kilometer dari stasiun kereta bawah tanah terdekat, jadi bus atau taksi adalah cara termudah.", "esg": "Dapur masakan kuil yang sepenuhnya nabati dan juga menghindari lima sayuran berbau tajam."},
  "soban-vegan-dongdaesin": {"of": "f79e6d3a", "story": "Soban Vegan menyebut dirinya restoran vegan, dan HappyCow mencantumkannya sebagai restoran vegan yang menyajikan masakan rumahan Korea dengan sup dan banyak lauk pendamping. Menunya berpusat pada paket makan Korea: rebusan tahu lembut atau rebusan pasta kedelai, bulgogi kedelai, dan nasi daun teratai, dengan ayam kedelai sebagai pendamping. Jaraknya 7 menit berjalan kaki dari Stasiun Dongdaesin di Jalur 1. Restoran ini tutup pada hari Rabu dan Minggu.", "esg": "Dapur masakan rumahan Korea yang sepenuhnya nabati."},
  "pyeonhan-jipbap-mandeok": {"of": "233e5b73", "story": "Pyeonhan Jipbap menyebut dirinya meja makan vegan bergaya Korea, dan HappyCow mencantumkannya sebagai restoran vegan yang menyajikan comfort food Korea. Menunya berupa paket makan Korea dengan nasi dan lauk pendamping, versi vegan dari sup pedas yukgaejang, sup pangsit, nasi daun teratai, dan ayam kedelai; paket masakan siap olahnya juga dijual di tempat ini. Letaknya di bagian permukiman Mandeok-dong, sekitar tujuh menit berjalan kaki dari Stasiun Namsanjeong di Jalur 3.", "esg": "Dapur masakan rumahan Korea yang sepenuhnya nabati."},
  "arp-yeongdo": {"of": "84569582", "story": "ARP mengambil namanya, menurut MICHELIN Guide, dari 'around plants', dan Guide tersebut menyebut menunya 100% vegan. Masakannya memadukan bahan-bahan Korea dengan masakan lain: pasta yang dibuat dengan pakis kering dan jamur adalah hidangan andalan yang disebut oleh Guide tersebut, di samping burger vegan dan hidangan musiman. Arak beras buatan sendiri disajikan di sini. Dari Stasiun Nampo jaraknya sekitar 22 menit berjalan kaki melintasi Jembatan Yeongdo.", "esg": "Menu yang sepenuhnya nabati, termasuk keju vegan dari minyak kelapa yang dibuat sendiri."},
  "bollywood-gwangalli": {"of": "aa3669a5", "story": "Bollywood Indian Restaurant adalah restoran India Utara yang tidak jauh berjalan kaki dari Pantai Gwangalli, memasak ayam tandoori, kari, dan naan dalam tandoor. Zabihah mencatat jaminan dari staf bahwa dagingnya halal, adanya seorang staf Muslim, dan tidak adanya alkohol; tidak ada sertifikat yang kami lihat. Menunya memuat daftar panjang kari kacang arab, lentil, jamur, dan sayuran. Shisha juga ditawarkan. Restoran ini tutup pada hari Selasa."},
  "cappadocia-namsan-busan": {"of": "634a18d2", "story": "Cappadocia adalah restoran Turki di Namsan-dong, di sebelah Masjid Al-Fatah Busan. Visit Busan menggambarkan makanannya sebagai bersertifikat halal, dan panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai bersertifikasi mandiri; tidak ada sertifikat yang kami lihat. Menu makan siangnya memuat semur daging sapi, kebab ayam, dan pide keju, dan paket makannya disajikan dengan sup, roti, hidangan penutup, dan teh. Jaraknya sekitar tujuh menit berjalan kaki dari Stasiun Dusil di Jalur 1."},
  "samarkand-busan-station": {"of": "3bb56549", "story": "Samarkand adalah restoran Uzbek di kawasan lama Texas Street di seberang Stasiun Busan, yang juga memasak beberapa hidangan Rusia. Halalfoodle mencantumkannya sebagai menyajikan daging halal, dan panduan Korea Tourism Organization tahun 2021 mencantumkannya sebagai ramah Muslim. Bir disajikan di sini, dan tidak ada sertifikat yang kami lihat. Menunya memuat plov, mi lagman, iga domba muda yang dimasak perlahan, samsa, dan borscht. Jaraknya empat menit berjalan kaki dari Stasiun Busan."},
  "half-moon-meat-bupyeong": {"of": "064bce8c", "story": "Half Moon Meat (반달고깃) membuat dakgangjeong Korea, ayam goreng renyah yang dilumuri saus manis, di dalam Pasar Bupyeong Kkangtong di Nampo. Halalfoodle mencantumkannya sebagai halal sepenuhnya dan bersertifikat halal, tetapi tidak ada sertifikat yang kami lihat. Bir disajikan di sini. Jaraknya sekitar 12 menit berjalan kaki dari Stasiun Jagalchi di Jalur 1."},
  "warung-jaya-nampo": {"of": "84c31e17", "story": "Warung Jaya adalah restoran Indonesia kecil di lantai dua di Nampo, memasak rendang, nasi goreng, sate ayam dan sate kambing, batagor, serta hidangan nasi dengan ayam dan bebek goreng atau bakar. Halalfoodle mencantumkannya sebagai menyajikan daging halal, dan tempat ini juga menjual bahan makanan Indonesia. Tidak ada sertifikat yang kami lihat. Jaraknya sembilan menit berjalan kaki dari Stasiun Nampo."},
  "bakso-bejo-nampo": {"of": "0ad9bb20", "story": "Bakso Bejo Korea Nampo, cabang Nampo dari Bakso Bejo Korea, adalah restoran Indonesia di lantai tiga dan empat sebuah gedung di Nampo-dong. Halalfoodle mencantumkannya sebagai menyajikan daging halal, dan seorang pengulas di sana menyebut adanya ruang salat dan bahan makanan Indonesia yang dijual. Tidak ada sertifikat yang kami lihat, dan menu terkini tidak ditemukan. Jaraknya sekitar sembilan menit berjalan kaki dari Stasiun Nampo."},
  "royal-india-seomyeon": {"of": "d6fa9c28", "story": "Royal India Seomyeon adalah restoran India dan Nepal di lantai enam Samjeong Tower di Seomyeon. Halalfoodle mencantumkannya sebagai menyajikan daging halal; tidak ada sertifikat yang kami lihat. Menunya mencakup hidangan tandoori dan tikka, kari makhani dan tikka masala, palak paneer, dan biryani, dengan paket makan untuk dua hingga lima orang. Jaraknya sekitar sembilan menit berjalan kaki dari Stasiun Seomyeon."},
  "asha-hadan": {"of": "a8bfe36c", "story": "Asha Hadan adalah restoran India dan Nepal di lantai dua di samping Stasiun Hadan, dekat muara Sungai Nakdong. Halalfoodle mencantumkannya sebagai menyajikan daging halal; tidak ada sertifikat yang kami lihat. Bir dan anggur disajikan di sini. Menunya memuat kari ayam, domba, udang, dan sayuran, tandoori, tikka, seekh kebab, dan paket makan. Jaraknya empat menit berjalan kaki dari Stasiun Hadan di Jalur 1."},
  "loving-hut-seosin-jeonju": {"of": "41d1fba9", "story": "Loving Hut Seosin adalah cabang Jeonju dari Loving Hut, jaringan restoran vegan yang situs Koreanya menyatakan bahwa setiap hidangan di menunya vegan dan tidak mengandung bahan hewani. Cabang Seosin menyajikan prasmanan makan siang berisi nasi, sup, bubur, dan lauk pendamping Korea, dan HappyCow menyebut ada hidangan utama daging tiruan di antaranya. Restoran ini hanya buka untuk makan siang, 11:30 hingga 15:00, dan tutup pada hari Minggu. Letaknya cukup jauh dari Stasiun Jeonju, jadi naiklah bus atau taksi.", "esg": "Standar vegan untuk seluruh jaringan yang tidak mengizinkan bahan hewani maupun produk sampingannya."},
  "gamloheon-jeonju": {"of": "d3e5be04", "story": "Gamloheon menyajikan masakan yakseon Korea, paket makan yang berlandaskan gagasan makanan sebagai obat, dan HappyCow mencantumkannya sebagai vegan sepenuhnya. Menu saat ini berpusat pada paket makan: satu hidangan yakseon dasar, dan satu paket dengan tteokgalbi nabati yang oleh restoran ini digambarkan dibuat dengan hasil dari kebunnya sendiri. Letaknya di gedung aula pertunjukan di 20 Hyeonmu 1-gil, tepat di sebelah barat Hanok Village."},
  "haetteuneun-jip-gwangju": {"of": "16a055db", "story": "Haetteuneun Jip adalah restoran Korea bergaya keluarga di Juwol-dong yang oleh HappyCow dicantumkan sebagai vegan sepenuhnya. Restoran ini memasak versi vegan dari hidangan Korea sehari-hari: bubur kacang merah dan bubur dongji, sup mi biji perilla, jjamppong sayuran, dan jamur asam manis. HappyCow mencatat tempat duduknya lesehan, jadi bersiaplah melepas sepatu. Letaknya di jalan permukiman sekitar tiga kilometer dari stasiun kereta bawah tanah terdekat, jadi naiklah bus atau taksi."},
  "present-vegan-cafe-jeonju": {"of": "d934024f", "story": "Present Vegan Cafe (프레종 dalam bahasa Korea) adalah kafe brunch yang oleh HappyCow dicantumkan sebagai vegan sepenuhnya. Menunya meliputi salad falafel dalam roti pita, avocado roll dengan daging nabati, sandwich ciabatta barbeku, dan latte yang dibuat dengan susu kedelai atau susu oat. Letaknya di bagian permukiman Jeonju, dicapai dengan bus atau taksi dari stasiun."},
  "fig-from-vegan-jeonju": {"of": "d3706488", "story": "Fig from Vegan (채식주의자의 무화과, 'buah ara sang vegetarian') adalah kafe yang oleh HappyCow digambarkan vegan sepenuhnya, dengan roti dan kue panggang buatan sendiri serta daftar panjang teh, ade, dan latte. Kafe ini buka Rabu hingga Minggu dari tengah hari hingga pukul 9 malam. Letaknya di lingkungan Junghwasan-dong, dicapai dengan bus atau taksi dari Stasiun Jeonju."},
  "sujata-gwangju": {"of": "65bd3813", "story": "Sujata adalah prasmanan makan sepuasnya dengan masakan Korea bergaya kuil sedikit di bawah pintu masuk Taman Nasional Mudeungsan, di jalan menuju kuil Jeungsimsa. HappyCow menggambarkan beragam hidangan vegan; tidak ada sumber yang menyebut seluruh prasmanannya nabati, jadi tanyakan tentang hidangan apa pun yang Anda ragukan. Tempat ini hanya melayani makan siang dan juga menjual makgeolli, kue beras, dan kopi. Dari stasiun Hakdong·Jeungsimsa Entrance jaraknya sekitar 30 menit berjalan kaki menanjak, atau naik bus sebentar ke halte Dongsanmaeul Entrance."},
  "salim-classic-vegetarian-buffet-gwangju": {"of": "4f7a7b05", "story": "Salim Classic Vegetarian Buffet adalah prasmanan vegetarian makan sepuasnya di Juwol-dong yang menyajikan sebagian besar hidangan Korea dengan beberapa hidangan Barat. HappyCow melaporkan bahwa semua yang ada di prasmanan itu vegan kecuali pizza keju, jadi vegan dapat menyantap hampir semuanya tetapi sebaiknya melewatkan yang satu itu. Tempat ini dicapai dengan bus atau taksi dari stasiun kereta bawah tanah terdekat."},
  "pulkkot-sesang-buffet-jeonju": {"of": "3d1fe57f", "story": "Pulkkot Sesang adalah prasmanan vegetarian besar di pinggiran barat daya Jeonju. HappyCow mencantumkannya sebagai vegetarian dengan pilihan vegan, termasuk daging tiruan dan hidangan sayuran; beberapa hidangan memakai produk susu, telur, atau madu, jadi vegan sebaiknya bertanya. Tempat ini jauh dari angkutan umum, jadi datanglah dengan mobil atau taksi."},
  "slow-city-yakcho-bapsang-damyang": {"of": "71792a2c", "story": "Slow City Yakcho Bapsang adalah prasmanan swalayan di Changpyeong, desa berpagar batu di Damyang, yang bertumpu pada lauk pendamping dari tanaman obat dan, menurut HappyCow, bibimbap beras hitam. HappyCow melaporkan bahwa semuanya vegan kecuali supnya, yang memakai kaldu ikan dan disajikan terpisah. Tamu mengambil makanan sendiri dan, seperti disebut dalam pengumuman pemilik di Kakao, juga mencuci piringnya sendiri. Changpyeong tidak memiliki stasiun kereta, jadi datanglah dengan bus atau mobil."},
  "jeongseureon-gimbap-gwangju": {"of": "b9a051a5", "story": "Jeongseureon Gimbap adalah kedai gimbap dan jajanan di deretan pertokoan sebuah kompleks apartemen di Gwangju. HappyCow melaporkan adanya menu vegan terpisah berisi gimbap tahu, tteokbokki, pangsit, dan sup mi, dan menu kedai itu sendiri menandai gimbap tahu goreng dan daun perilla sebagai vegan. Menu regulernya mencakup daging babi dan Spam, jadi pesanlah dari hidangan vegan. Tempat ini tidak berada di jalur kereta bawah tanah, jadi naiklah bus."},
  "daejeob-gwangju": {"of": "4bfb2903", "story": "Daejeob adalah rumah makan Korea kecil yang dikelola keluarga di pusat kota lama, beberapa menit berjalan kaki dari Stasiun Culture Complex dan Asia Culture Center. HappyCow melaporkan adanya menu vegan terpisah yang mencakup mi, rebusan, bibimbap, pangsit, bulgogi, dan kotlet. Menu regulernya mencakup daging babi, jadi mintalah versi vegan. Tempat ini buka pukul 10:30 hingga 19:00 dan tutup pada hari Minggu."},
  "pungnamjeong-jeonju": {"of": "ca29dbd6", "story": "Pungnamjeong menyajikan bibimbap Jeonju dan bibimbap mangkuk batu di Hanok Village, berhadapan dengan Katedral Jeondong. HappyCow mencantumkannya sebagai tempat yang melayani vegan dengan bibimbap ramah vegan dan lauk pendamping; mangkuk standarnya tidak vegan sebagaimana disajikan, jadi mintalah versi vegan saat Anda memesan. Tempat ini buka setiap hari pukul 10:30 hingga 21:00."},
  "nanulteo-suncheon": {"of": "49273691", "story": "Nanulteo mengkhususkan diri pada masakan biji ek: salad dan bibimbap jeli biji ek, mi biji ek, dan panekuk biji ek, ditambah sup biji perilla. HappyCow mencantumkan hidangan vegan termasuk panekuk biji ek, sup, dan hidangan tahu; beberapa paket disertai daging, jadi tanyakan hidangan mana yang vegan. Tempat ini sekitar 32 menit berjalan kaki dari Stasiun Suncheon."},
  "gohyang-meokgeori-gangneung": {"of": "f38a7d30", "story": "Gohyang Meokgeori (\"makanan kampung halaman\") adalah restoran kecil di lantai dua Pasar Jungang Gangneung, pasar tradisional utama kota itu. Menunya adalah makanan Pantai Timur Korea: hwangtae-gui, pollock kering yang diolesi saus cabai manis lalu dipanggang; bbogeuljang, rebusan pasta kedelai kental yang mendidih dan disajikan dengan nasi; nasi mangkuk batu dengan ikan panggang; serta hotpot makanan laut pedas yang dibuat dengan tahu lembut dari desa Chodang di dekatnya, tempat tahu secara tradisional digumpalkan dengan air laut. Menu saat ini tidak mencantumkan daging babi. Itu adalah pernyataan tentang menunya, bukan klaim halal, dan kami belum melihat sertifikat halalnya. Pada 2021 Korea Tourism Organization mencantumkannya dalam panduan restoran ramah Muslim. Pasar ini sekitar 23 menit berjalan kaki dari Stasiun Gangneung."},
  "mountain-fishtail-cheonan": {"of": "3b5912b3", "story": "Mountain Fishtail adalah restoran India dan Nepal di lantai dua tepat di dekat Stasiun Cheonan. Direktori halal Zabihah mencantumkannya sebagai halal sepenuhnya dan tidak menyajikan alkohol, serta menyebut bahwa staf memberikan jaminan lisan atas status halalnya. Zabihah juga mencatat adanya sertifikat dalam arsipnya, tetapi tidak ada sertifikat yang kami lihat, dan tidak ada lembaga sertifikasi yang disebutkan."},
  "kebab-island-eumseong": {"of": "b324c289", "story": "Kebab Island adalah kedai kebab Turki di Daeso-eup, di Kabupaten Eumseong. Instagram milik pengelolanya sendiri menggambarkannya sebagai spesialis kebab Turki yang menyajikan makanan halal. Tidak ada klaim sertifikat. Tempat ini buka pukul 10:30 hingga 21:00 dan tutup pada hari Senin. Tidak ada stasiun kereta di dekatnya, jadi perlu bus atau mobil."},
  "seivegan-daejeon": {"of": "efd49502", "story": "Seivegan adalah toko roti vegan di Seonhwa-dong, di pusat kota lama Daejeon. Situs webnya sendiri menyatakan bahwa setiap produknya bebas gluten dan dibuat tanpa produk susu, telur, atau kacang-kacangan, untuk orang yang memiliki alergi dan untuk vegetarian. Toko ini pindah ke sini dari Noeun-dong pada Juni 2024. Instagramnya menyebut bahwa toko ini juga menerima pesanan daring.", "esg": "Standar nabati dan bebas alergen untuk seluruh toko roti."},
  "eats-vegan-sejong": {"of": "7ebb218c", "story": "Eats Vegan adalah toko roti kecil di deretan pertokoan sebuah kompleks apartemen di Eojin-dong, dekat Government Complex Sejong. Instagramnya sendiri menggambarkannya sebagai 100% vegan, dengan pilihan bebas gluten dan rendah gula, dan toko ini membuat roti, kue, kue kering, dan paket hadiah. Sejong tidak memiliki metro, jadi tempat ini dicapai dengan bus BRT dan berjalan kaki sekitar 15 menit.", "esg": "Toko roti 100% vegan menurut pernyataan pengelolanya sendiri."},
  "bakefit-cheonan": {"of": "de1f1118", "story": "Bakefit adalah kafe toko roti di Ssangyong-dong, Cheonan. Instagramnya sendiri menyebutnya kafe toko roti vegan dan mencantumkan kue kering beras vegan, kue kering beras cokelat, dan kue vegan. Menu minumannya juga memuat latte, teh susu, smoothie yogurt, dan milkshake, dan tidak disebutkan susu apa yang dipakai, jadi tanyakan jika Anda memerlukan yang nabati. Tempat ini sekitar delapan menit berjalan kaki dari Stasiun Ssangyong dan tutup pada hari Senin."},
  "urikong-sondubu-anyang": {"of": "234a17e4", "story": "Urikong Sondubu membuat tahunya sendiri dan menyajikannya dalam rebusan tahu lembut, rebusan pasta kedelai, dan, pada musim panas, kongguksu, mi dingin dalam kuah kedelai. HappyCow mencantumkan bahwa di sini ada pilihan vegan. Menunya juga memuat hidangan kerang, tiram, dan daging sapi, jadi beri tahu staf bahwa Anda tidak makan daging, ikan, atau telur dan tanyakan rebusan mana yang cocok untuk Anda. Tempat ini sekitar 14 menit berjalan kaki dari Stasiun Indeogwon."},
  "indeogwon-bibimguksu-anyang": {"of": "44df9bb2", "story": "Ini adalah cabang utama Anyang dari Indeogwon Bibimguksu, kedai mi yang dikenal dengan bibim-guksu, mi gandum tipis yang diaduk dengan saus cabai manis pedas. HappyCow menyebut hidangan itu sebagai pilihan vegan dan bahwa hidangan lainnya tidak vegan. Mintalah tanpa telur atau taburan lainnya. Tempat ini 6 menit berjalan kaki dari Stasiun Indeogwon."},
  "busong-guksu-sangdong": {"of": "9cdae8d7", "story": "Busong Guksu adalah kedai mi lingkungan yang berjarak lima menit dari Stasiun Sangdong. HappyCow menyebut sebagian besar hidangannya mengandung daging atau ikan; pilihan vegannya adalah kongguksu, mi dalam kuah kedelai dingin, yang dipesan tanpa telur. Menu menandainya sebagai sajian khusus musim panas, jadi mungkin tidak disajikan pada musim dingin, dan HappyCow memperingatkan bahwa sebagian besar lauk pendampingnya tidak vegetarian."},
  "gapyeong-sundubu-ganseok": {"of": "f747b8be", "story": "Gapyeong Sundubu adalah restoran Korea kecil yang menyajikan boribap, nasi jelai yang dicampur sayuran berbumbu, dengan tahu lembut dan rebusan doenjang sebagai pendamping. HappyCow mencantumkan pilihan vegan: tahu goreng wajan, panekuk kentang, dan mangkuk nasinya, yang dipesan tanpa telur. Menunya juga memuat daging babi rebus, ikan pari fermentasi, dan pollock kering, dan rebusannya tidak digambarkan sebagai vegan, jadi sebutkan apa yang Anda hindari saat memesan. Tempat ini 11 menit berjalan kaki dari Stasiun Ganseogogeori."},
  "samdaejjae-sondubu-osan": {"of": "3aa47fa6", "story": "Samdaejjae Sondubu, yang namanya berarti 'tahu buatan tangan generasi ketiga', menyajikan rebusan tahu lembut, rebusan kedelai, dan, pada musim panas, kongguksu. HappyCow mencantumkan tahu lembut perilla, tahu lembut polos, dan tahu panggangnya sebagai pilihan vegan. Sebagian besar sisa menunya adalah daging babi, daging sapi, atau makanan laut, jadi mintalah hidangan tahu tanpa kaldu daging atau makanan laut. Tempat ini sekitar 2,3 km dari Stasiun Osan, jadi lebih mudah naik taksi atau bus."},
  "samdaejjae-sondubu-singal": {"of": "9a4313ba", "story": "Samdaejjae Sondubu di Singal ini membuat tahunya sendiri. HappyCow mencantumkan beberapa hidangan yang vegan atau dapat dibuat vegan: kotlet tahu (dubu-man donkkaseu), rebusan tahu lembut, tahu goreng wajan, dan kongguksu. Selebihnya menunya didominasi hotpot daging babi, daging sapi, dan makanan laut, jadi katakan bahwa Anda menginginkan hidangan tanpa daging, makanan laut, atau telur. Tempat ini 26 menit berjalan kaki dari Stasiun Giheung."},
  "jaseon-nongwon-suwon": {"of": "3ddf7c5d", "story": "Jaseon Nongwon adalah restoran Korea tradisional di samping titik awal jalur pendakian Gwanggyosan di Suwon utara, yang menyajikan nasi jelai, cheonggukjang, dan panekuk gurih. HappyCow menyebut beberapa hidangan vegan: salad jeli biji ek pedas di atas selada dan panekuk labu manis. Selebihnya, menunya mencakup daging babi, bebek, ayam, dan makanan laut, dan paket nasi jelai disertai lauk pendamping lain, jadi bertanyalah sebelum memesan. Capailah dengan bus ke terminal akhir Gwanggyosan."},
  "kong-ji-young-kitchen-yongin": {"of": "7a2ddba2", "story": "Kong Ji Young Kitchen adalah restoran kecil dekat Stasiun Dongbaek yang dikelola seorang koki, yang menggambarkannya sebagai restoran vegan kecil dengan menu yang mengikuti musim. Menu saat ini memuat bibimbap musiman, mangkuk nasi jamur pedas, serta steik hamburg, burger, dan pasta tomat nabati. Telur goreng ditawarkan sebagai tambahan gratis pada bibimbap, jadi katakan bahwa Anda menginginkannya tanpa telur. Tempat ini hanya memiliki beberapa meja."},
  "golgujaengine-yeoju": {"of": "295b8d1c", "story": "Golgujaengine adalah restoran Korea pedesaan di Yeoju timur yang dikenal dengan masakan bergaya kuil: satu set hidangan berisi sayuran gunung berbumbu, sup doenjang, tahu, dan nasi. HappyCow menggambarkan lauk pendamping, sup doenjang, tahu, dan nasinya sebagai vegan. Menunya juga mencantumkan hidangan daging babi, jadi pastikan kepada staf bahwa hidangan di meja Anda tidak mengandung daging atau kecap ikan. Tempat ini jauh di pedesaan dan memerlukan mobil atau taksi dari Stasiun Yeoju."},
  "bonjuk-songdo-sindosi": {"of": "79bd2b5f", "story": "Cabang Songdo dari Bonjuk, jaringan bubur nasi Korea, ini berada di gedung Songdo Millennium di Convensia-daero. HappyCow menyebut tiga bubur vegan: kacang hijau, kacang merah dengan nasi, dan labu manis. Sebagian besar menunya adalah bubur abalon, daging sapi, makanan laut, atau ayam serta bibimbap daging, dan catatan HappyCow hanya berlaku untuk cabang ini. Tempat ini 27 menit berjalan kaki dari Stasiun Incheon National University."},
  "vishop-pyeongtaek": {"of": "edc695a9", "story": "Vishop adalah toko roti dan kafe vegan di Bijeon-dong, Pyeongtaek. Pemiliknya menyatakan bahwa tidak satu pun produk panggangannya memakai produk susu, telur, madu, atau bahan hewani lainnya, dan HappyCow mencantumkannya sebagai vegan. Di sini ada roti tepung beras Korea, bagel tahu, scone, dan kue kering, banyak di antaranya bebas gula atau bebas gluten, ditambah minuman dengan susu nabati. Tempat ini jauh di sebelah timur Stasiun Pyeongtaek, jadi naiklah bus atau taksi."},
  "bakery-rafeulrafeul-ilsan": {"of": "7e3bca88", "story": "RafeulRafeul hanya membuat roti vegan, dari tepung beras Korea dan bahan nabati, sebagaimana dinyatakan pemiliknya. Di sini ada roti tawar beras, baguette dan ciabatta beras bebas gula, roti kastanye, roti isi kacang merah, dan roti garam yang dibuat dengan mentega vegan buatan toko roti itu sendiri. Tempat ini 11 menit berjalan kaki dari Stasiun Daehwa."},
  "sophie-vegan-bakery-maseok": {"of": "3218d7ac", "story": "Sophie Vegan Bakery adalah toko roti vegan kecil di Hwado-eup, dekat Stasiun Maseok di Jalur Gyeongchun. HappyCow menggambarkannya sebagai toko roti vegan yang menghindari pengawet dan pewarna buatan serta memiliki pilihan bebas gluten. Minumannya dibuat dengan susu oat, kedelai, atau kelapa."},
  "littlebrown-yongin": {"of": "262da948", "story": "Littlebrown adalah toko roti vegan di Cheongdeok-dong, Yongin, yang membuat roti tawar tepung beras Korea: polos, mugwort Jindo, beras ketan hitam, serta zaitun dan rosemary, ditambah ciabatta beras. HappyCow mencantumkannya sebagai toko roti vegan. Ini adalah toko kecil khusus bawa pulang di kawasan permukiman sekitar 4 km dari Stasiun Guseong, jadi pergilah dengan bus atau taksi."},
  "bodlebodle-bakery-anyang": {"of": "673e21bf", "story": "Bodle Bodle Bakery adalah toko roti dan kafe vegan kecil di sebuah jalan permukiman di Manan-gu, Anyang. HappyCow menggambarkannya sebagai vegan sepenuhnya dan mencantumkan roti beras, pound cake beras yuzu, financier, brownies, roti isi krim, scone, dan kue kering. Jika Anda memesan latte, periksa susu apa yang dipakai. Tempat ini sekitar 25 menit berjalan kaki dari Stasiun Anyang."},
  "heewarae-ganghwa": {"of": "98644a8b", "story": "Heewarae adalah tempat sangrai kopi dengan pemandangan ladang di bagian tenggara Pulau Ganghwa. HappyCow menyebut bahwa setiap hidangan penutupnya, termasuk kue, roti, dan kue keringnya, dibuat hanya dengan bahan nabati. HappyCow tidak menyebut hal yang sama tentang minumannya, jadi tanyakan susu apa yang dipakai untuk latte. Tempat ini berada di pedesaan dan memerlukan mobil atau taksi."},
  "moandave-suwon": {"of": "2d5a47c8", "story": "Moandave adalah kafe hidangan penutup beberapa menit dari Stasiun Sungkyunkwan University yang pemiliknya menggambarkan hidangan penutupnya sebagai dibuat dari bahan nabati. HappyCow menyebut produk panggangannya, seperti kue kering, madeleine, dan kue, vegan, tetapi susu sapi dipakai dalam minuman kecuali Anda meminta susu nabati. HappyCow juga mencatat adanya diskon jika Anda membawa wadah sendiri."},
  "happy-bakery-songtan": {"of": "b375ee72", "story": "Happy Bakery membuat roti tepung beras tidak jauh berjalan kaki dari Stasiun Songtan di Pyeongtaek utara. HappyCow mencantumkan produk vegan termasuk crumble, dan beberapa roti di menunya digambarkan dibuat dengan mentega vegan atau mayones vegan. Cantuman HappyCow sendiri tidak konsisten soal apakah semuanya vegan, jadi tanyakan tentang produk apa pun yang Anda ragukan."},
  "ohnews-bucheon": {"of": "9a685fc9", "story": "OhNew’s adalah kafe toko roti di Yakdae-dong, Bucheon, yang oleh pemiliknya disebut kafe toko roti vegan. HappyCow menyebut kue, kue kering, crumble, dan scone-nya vegan, tetapi produk susu dan madu dipakai dalam beberapa minuman. Menu saat ini menandai produk seperti puding pisang dan kue Victoria sebagai vegan. Tempat ini 33 menit berjalan kaki dari Stasiun Sinjung-dong."},
  "selah-icheon": {"of": "016201ac", "story": "Selah adalah kafe toko roti di Changjeon-dong, Icheon, dengan jajaran produk panggangan yang berganti setiap hari. HappyCow menyebut produk panggangannya vegan dan bahwa susu sapi ditawarkan untuk minuman, yang dibenarkan oleh latte dan susu vanilla bean di menunya. Mintalah susu nabati, atau pesan teh susu vanila yang dilabelinya vegan. Tempat ini sekitar 2,6 km dari Stasiun Icheon."},
  "newsual-inn-ansan": {"of": "218ca926", "story": "Newsual Inn adalah bar dan restoran di Ungshin Art Plaza di Gojan-dong, Ansan. HappyCow menyebut menunya melabeli hidangan vegan, seperti salad tahu, salad daun bawang panggang dengan daging nabati, pasta ragu tomat, dan pasta krim kedelai, dan bahwa tempat ini memiliki minuman beralkohol vegan. Menunya juga memuat makanan laut dan daging. Tempat ini terutama sebuah bar: alkohol disajikan, dan HappyCow mencantumkan jam buka dari tengah hari atau pertengahan sore hingga larut malam."},
  "bitgaram-vegan-buffet-chungju": {"of": "cd1e639a", "story": "Bitgaram adalah prasmanan vegan makan sepuasnya yang hanya melayani makan siang, dengan sekitar empat puluh hidangan menurut hitungan HappyCow, sebagian besar masakan Korea. Tempat ini pindah dari Allim-ro ke lokasinya saat ini di Sindae 2-gil di Danwol-dong. Letaknya jauh di luar pusat kota: perhitungkan naik taksi atau bus kota dari Stasiun Chungju."},
  "dameun-haneulchae-mokpo": {"of": "3053d97b", "story": "Dameun Haneulchae adalah prasmanan vegan Korea di Sang-dong, tidak jauh dari Pyeonghwa Square dan bebatuan Gatbawi di tepi laut Mokpo. HappyCow mencantumkannya sebagai vegan sepenuhnya tanpa tambahan MSG. Tempat ini melayani makan siang; periksa hari tutupnya sebelum Anda pergi. Dari Stasiun Mokpo, tempat ini dicapai dengan taksi atau bus melintasi kota."},
  "teumssag-gongju": {"of": "23c30443", "story": "Teumssag adalah toko buku independen dan kafe di pusat Gongju yang seluruh isi menunya vegan. Hidangan utamanya adalah sajian khusus musiman yang dicantumkan sebagai menu akhir pekan, dengan kopi susu oat, chai kedelai, teh herbal, dan bir craft. HappyCow mencatat bahwa menunya berganti setiap bulan dan diumumkan di Instagram, jadi periksa di sana sebelum Anda pergi. Tempat ini sepuluh menit berjalan kaki dari Pasar Sanseong di kota tua."},
  "cheongchun-jeppangso-cheongyang": {"of": "155190cb", "story": "Cheongchun Jeppangso adalah toko roti vegan kecil di kota Cheongyang yang digambarkan HappyCow sebagai toko yang didirikan untuk membuat roti sehat bagi penduduk yang menua. Toko ini menjual roti dan produk panggangan manis. Jam bukanya belum terkonfirmasi, jadi ada baiknya menelepon dulu; tempat ini sekitar 21 menit berjalan kaki dari terminal bus antarkota Cheongyang."},
  "sintobuli-yakcho-songnisan": {"of": "0f38163e", "story": "Sintobuli Yakcho Sikdang terletak di jalan dari terminal bus Songnisan naik menuju kuil Beopjusa. Menunya bertumpu pada tanaman herbal gunung, sayuran liar, jamur, dan akar deodeok; HappyCow mencantumkan hotpot jamur, bibimbap sayuran liar, panekuk jamur, dan deodeok panggang di antara pilihan vegannya. Dapurnya juga menyajikan bulgogi dan ayam, jadi katakan bahwa Anda vegan saat memesan."},
  "sandulle-cheonan": {"of": "b39685a8", "story": "Sandulle menyajikan paket nasi daun teratai dengan aneka lauk pendamping sayuran di Anseo-dong, di jalan menuju kuil Seongbulsa di tepi timur Cheonan. HappyCow mencatat ada pilihan vegan berupa sayuran dan tahu dengan nasi. Menunya juga memuat perut babi asap dan bebek, dan ulasan menyebut daging ikut disajikan bersama paketnya, jadi mintalah tanpa daging."},
  "banya-dolsotbap-jeonju": {"of": "daa3e560", "story": "Banya Dolsotbap memasak nasi sesuai pesanan dalam mangkuk batu panas, disajikan dengan lauk pendamping, di kawasan Hyoja-dong di sebelah barat pusat Jeonju. HappyCow menyebut nasi mangkuk batu vegetarian andalannya dapat dibuat vegan dengan tidak menyertakan telur; tanyakan juga tentang lauk pendampingnya. Menunya juga memuat daging sapi dan bulgogi. Tempat ini dicapai dengan bus atau taksi dari stasiun."},
  "jongno-hoegwan-jeonju": {"of": "8efb34a5", "story": "Jongno Hoegwan menyajikan bibimbap gaya Jeonju tidak jauh berjalan kaki dari Katedral Jeondong, di tepi Hanok Village. HappyCow menyebut bibimbapnya dapat dibuat vegan atas permintaan, jadi beri tahu staf saat Anda memesan; mangkuk standarnya dan sebagian besar menunya mengandung daging sapi."},
  "sinbaengi-jeonju": {"of": "d615a575", "story": "Sinbaengi menyajikan sup nasi taoge khas Jeonju dan bibimbap sejak pukul 8 pagi di sebuah hanok tradisional di dalam Hanok Village. HappyCow mencantumkan sup taoge vegetariannya sebagai pilihan vegan jika Anda meminta telurnya tidak disertakan, dan menyarankan untuk menanyakan apakah kimchinya mengandung kecap ikan. Menunya juga memuat bibimbap sayuran dan bibimbap daging sapi."},
  "jeonwon-maeul-gunsan": {"of": "d5bff428", "story": "Jeonwon Maeul menyajikan ssambap — nasi mangkuk batu yang dimakan dengan dibungkus selada dan sayuran hijau bersama lauk pendamping sayuran — dengan pilihan daging babi pedas atau daging kedelai. HappyCow mencantumkan paket daging kedelai sebagai pilihan vegannya dan memperingatkan bahwa kimchinya mengandung ikan. Tempat ini berada di kawasan Susong-dong, dicapai dengan taksi dari Stasiun Gunsan."},
  "younghee-pat-kalguksu-gunsan": {"of": "c28ced51", "story": "Younghee's adalah kedai mi di Naun-dong yang mengkhususkan diri pada pat-kalguksu, mi potong tangan dalam sup kacang merah kental, dan bubur kacang merah dengan bola ketan; HappyCow mencantumkan keduanya sebagai vegan. Kedai ini juga membuat mi kerang dan, pada musim panas, mi susu kedelai. Tempat ini dicapai dengan taksi atau bus dari terminal bus Gunsan."},
  "beomamgol-patjuk-suncheon": {"of": "655dd38a", "story": "Beomamgol Patjuk adalah restoran kecil bergaya rumahan di Wangji-dong yang menyajikan bubur kacang merah, bubur titik balik musim dingin dengan bola beras, bubur kacang, dan, pada musim panas, mi susu kedelai dingin, yang semuanya dicantumkan HappyCow sebagai vegan; bibimbapnya dapat dibuat vegan tanpa telur. Tempat ini dicapai dengan taksi atau bus dari Stasiun Suncheon."},
  "sarangson-patjuk-beobwon-suncheon": {"of": "d6394af3", "story": "Cabang Sarangson Patjuk ini, dekat gedung pengadilan Suncheon di Wangji-dong, membuat bubur kacang merah, bubur titik balik musim dingin, dan bubur lima biji-bijian dengan bola beras, yang dicantumkan HappyCow sebagai vegan; mi susu kedelai musim panasnya dapat dibuat vegan atas permintaan. Menunya juga memuat sup daging sapi dan mi kerang."},
  "hyegyeong-eonni-kalguksu-suncheon": {"of": "804f9af4", "story": "Hyegyeong Eonni adalah restoran kecil di Haeng-dong, di sekitar lorong-lorong kafe Okridan-gil di Suncheon lama, yang menyajikan mi potong pisau dengan kerang dan simping, panekuk sayuran dan makanan laut, serta bibimbap. HappyCow menyebut bibimbap vegetariannya dapat dibuat vegan atas permintaan; sup minya dibuat dengan kerang-kerangan."},
  "jungsung-gimbap-mokpo": {"of": "c1bb4511", "story": "Jungsung Gimbap adalah kedai gimbap kecil dekat kawasan sejarah modern Mokpo, sekitar 12 menit berjalan kaki dari Stasiun Mokpo. HappyCow melaporkan adanya gulungan vegan yang dibuat dengan rumput laut, acar lobak, tahu goreng, dan sayuran; gulungan itu tidak diberi label di menu, jadi mintalah dan pastikan telur dan ham tidak disertakan."},
  "jeil-banjeom-gwangju": {"of": "9b88f153", "story": "Jeil Banjeom adalah restoran Korea-Tionghoa dekat Geumnamno di pusat kota Gwangju. HappyCow melaporkan adanya menu vegan terpisah yang mencakup mi saus kacang hitam, jjamppong pedas, nasi goreng, mapo tahu, dan 'udang' kung pao vegan; mintalah menu itu, karena menu yang dipajang tidak menampilkannya. Tempat ini delapan menit berjalan kaki dari Stasiun Geumnamno 5-ga."},
  "taewon-daejeon": {"of": "9d107674", "story": "Taewon adalah restoran Korea-Tionghoa di kawasan Dunsan, Daejeon. HappyCow melaporkan adanya menu vegan terpisah, termasuk hidangan yang dimasak tanpa lima sayuran berbau tajam yang dihindari dalam masakan Buddha, dan menyarankan untuk memesan tempat lebih dulu. Menu regulernya didominasi daging babi, daging sapi, dan makanan laut."},
  "hawaiian-recipe-jeonju": {"of": "3fd0cd6f", "story": "Hawaiian Recipe adalah dapur kecil bernuansa Hawaii di Hyanggyo-gil, di dekat sekolah Konfusianisme lama di tepi Jeonju Hanok Village. Menu saat ini mencantumkan kari vegan di samping hidangan udang dan acai bowl; tanyakan kari lain mana yang nabati."},
  "cobe-wanju": {"of": "cd846249", "story": "Cobe adalah kafe brunch vegetarian kecil di Jeonbuk Innovation City, di tepi barat Jeonju, yang dibuka pada akhir 2024. HappyCow menyebut sebagian besar menunya vegan, termasuk roti lapis 'pulled pork' jamur dan döner tahu; kafe ini juga menjual roti sourdough. Beberapa hidangan memakai telur atau produk susu, jadi periksalah."},
  "yo-la-tengo-daejeon": {"of": "7f427fe8", "story": "Yo La Tengo adalah pub musik kecil di lantai dua di Daeheung-dong, pusat kota lama Daejeon, enam menit berjalan kaki dari Stasiun Jungang-ro. Selain koktail dan bir, tempat ini menyajikan makanan bar; HappyCow mencantumkan ayam goreng vegan, sayuran panggang dengan nugget tahu bawang putih, dan mi bibim acar sayuran di antara pilihan vegannya. Tempat ini hanya buka pada malam hari."},
  "bread-and-roses-gwangju": {"of": "573ef87c", "story": "Bread and Roses adalah kafe toko roti kecil di dekat Chungjang-ro di pusat kota Gwangju, 15 menit berjalan kaki dari Stasiun Culture Complex dan Asia Culture Center. HappyCow melaporkan bahwa sekitar sembilan dari sepuluh rotinya, dan semua minumannya, vegan; tanyakan roti mana yang mengandung produk susu atau telur. HappyCow mencantumkannya sebagai buka hanya Kamis hingga Sabtu, jadi periksa sebelum Anda pergi."},
  "saesil-gyeongsan": {"of": "d9c2366d", "story": "Saesil adalah restoran hidangan set Korea (hansik) di Gyeyang-dong, Gyeongsan, yang dicantumkan HappyCow sebagai vegan sepenuhnya dan digambarkannya sebagai restoran Korea vegan dengan tempat duduk lesehan dan ruang pribadi. HappyCow juga mencatat bahwa tempat ini menyajikan bir atau anggur. Tempat ini sekitar 35 menit berjalan kaki dari Stasiun Gyeongsan, jadi taksi atau bus lokal adalah cara yang lebih mudah untuk ke sana."},
  "kavsar-gyeongsan": {"of": "9176bf82", "story": "Kavsar adalah restoran Asia Tengah di lantai dua sebuah gedung di Dungji-ro, jalan restoran asing dekat Yeungnam University di Gyeongsan. Instagramnya sendiri menggambarkan makanannya sebagai halal ('Halol' dalam bahasa Uzbek), dan Halalfoodle mencantumkannya sebagai tempat yang menyajikan daging halal. Tidak ada sertifikat yang kami lihat. Menunya di DiningCode berisi daging domba muda, daging sapi, dan ayam: lagman, sate kebab domba muda dan kebab Adana, salad, dan yogurt buatan sendiri; salad Olivier-nya mengandung sosis yang jenis dagingnya tidak disebutkan. Tidak ada alkohol yang tercantum di menu. Tempat ini sekitar 13 menit berjalan kaki dari Stasiun Yeungnam Univ. di Jalur 2 Daegu."},
  "maharaja-changwon": {"of": "cb541fa6", "story": "Maharaja adalah restoran India di lantai tiga pertokoan Jeonwon di Jungang-dong, Changwon; halaman Facebook-nya sendiri menyebutnya restoran halal, dan Halalfoodle mencantumkannya sebagai tempat yang menyajikan daging halal. Tidak ada sertifikat yang kami lihat, dan tempat ini juga menyajikan bir dan minuman anggur (wine). Menunya meliputi kari ayam dan kari domba muda, biryani, masala udang dan ikan, serta hidangan lentil dan kacang arab. Tempat ini tutup di antara waktu makan siang dan makan malam. Dari Stasiun Changwon Jungang, jaraknya hampir satu jam berjalan kaki, jadi naiklah bus kota atau taksi."},
  "yella-gyeongju": {"of": "7908f8dd", "story": "YELLA! adalah restoran burger kecil bergaya Amerika di sebuah jalan kecil dekat pusat kota lama Gyeongju, tidak jauh berjalan kaki dari kawasan taman makam kuno. Selain smash cheeseburger dan buffalo wings, tempat ini menyajikan hidangan yang dilabelinya vegan: taco wrap vegan dan ayam vegan dengan kentang goreng. Dapurnya juga memasak daging, jadi ini adalah tempat dengan pilihan vegan, bukan restoran vegan. Tempat ini sekitar 23 menit berjalan kaki dari terminal bus antarkota Gyeongju, dan tutup pada hari Minggu."},
  "small-bakery-ulsan": {"of": "dc6e7c1c", "story": "Small Bakery adalah toko roti lingkungan di pertokoan apartemen Hillstate di Gangdong, di pesisir Buk-gu, Ulsan. Toko ini menyebut dirinya toko roti vegan, dan HappyCow mencantumkannya untuk roti, pastry, dan hidangan penutup vegan. Toko ini membuat roti setiap hari untuk hari itu juga dan mungkin tutup lebih awal bila habis terjual. Hari bukanya berbeda antara satu sumber dan sumber lain (Instagram toko itu sendiri menyebut tutup Senin dan Selasa), jadi periksa sebelum pergi. Tidak ada kereta di dekatnya; tempat ini dicapai dengan bus kota atau mobil."},
  "love-and-communication-nampo": {"of": "50557c34", "story": "Love and Communication adalah kafe vegan yang dicapai dengan menaiki satu tangga dari Gwangbok-ro di Nampo-dong. HappyCow mencantumkannya sebagai vegan sepenuhnya, dengan roti lapis, pasta, hidangan fusi bernuansa Korea, dan hidangan penutup buatan sendiri. Menu saat ini mencakup pasta minyak bawang putih tempe, kari dengan bola nasi, dan roti lapis focaccia tomat, dan tempat ini menyajikan anggur, bir, dan koktail selain kopi dan teh. Tempat ini tutup pada hari Senin; HappyCow menyebut reservasi diwajibkan.", "esg": "Dapur kafe yang sepenuhnya nabati."},
  "arp-eulsuk-hadan": {"of": "1708d0cf", "story": "ARP Eulsuk adalah restoran vegan di lantai empat Museum of Contemporary Art Busan di Pulau Eulsukdo. HappyCow mencantumkannya sebagai vegan, dengan sajian paket bergaya Korea berisi hidangan pembuka, hidangan utama, dan minuman. Tempat ini buka untuk makan siang dan sore hari, Selasa hingga Minggu, dan berjarak sekitar 40 menit berjalan kaki, atau naik bus sebentar, dari Stasiun Hadan.", "esg": "Dapur yang sepenuhnya nabati."},
  "nayutas-kitchen-oryun": {"of": "c93ddc3b", "story": "Nayuta's Kitchen adalah restoran vegan organik kecil sekaligus ruang kelas memasak di Oryun-dong, di samping Waduk Hoedong di tepi utara Busan. HappyCow mencantumkannya sebagai vegan, dengan hidangan seperti pho jamur dan pasta krim wortel, dan menyebut reservasi diwajibkan. Tempat ini hanya buka beberapa hari dalam seminggu, jadi pesanlah tempat lebih dulu; letaknya jauh dari kereta bawah tanah.", "esg": "Masakan organik yang sepenuhnya nabati."},
  "home-bistro-dalmaji": {"of": "d6876f9b", "story": "HOME Bistro and Cafe adalah bistro vegan di jalan Dalmaji di atas Pantai Haeundae, dengan tempat duduk di luar ruangan. HappyCow mencantumkannya sebagai vegan dengan menu minuman yang banyak, termasuk anggur. Menu saat ini mencakup taco, piza, sepiring hummus, dan roti lapis 'tuna' vegan. Tempat ini buka Selasa hingga Sabtu; periksa jamnya sebelum pergi, karena cantuman yang ada berbeda-beda.", "esg": "Dapur yang sepenuhnya nabati."},
  "ksana-ilgwang": {"of": "2b07a760", "story": "Ksana adalah kafe toko roti vegan di perbukitan Ilgwang, di Kabupaten Gijang, Busan; pemiliknya menggambarkannya sebagai kafe vegan dengan suasana vintage Prancis selatan, dan tempat ini berada di balik gerbang merah muda di sebuah bangunan putih. HappyCow mencantumkannya sebagai toko roti bergaya Prancis yang vegan sepenuhnya dengan kue seperti kue wortel dan crumble buah, dan menyebut kue pesanan khusus dapat dipesan. Tempat ini sekitar tiga kilometer dari Stasiun Ilgwang, jadi paling mudah naik taksi atau mobil.", "esg": "Toko roti yang sepenuhnya nabati."},
  "ohh-good-thing-jeonpo": {"of": "a6941580", "story": "Ohh good thing adalah kafe hidangan penutup vegan kecil di jalan-jalan kafe Jeonpo-dong. HappyCow menyebut tempat ini tidak memakai telur, mentega, susu, gula putih, atau produk hewani lainnya, dan membuat produk panggangannya dengan beras, gandum lokal, dan gula mentah, serta bahwa beberapa hidangan penutupnya bebas gluten. Hidangan penutupnya berganti mengikuti musim. Tempat ini sekitar sepuluh menit berjalan kaki dari Stasiun Jeonpo dan tutup pada hari Selasa dan Rabu.", "esg": "Hidangan penutup nabati dalam kemasan bawa pulang ramah lingkungan (HappyCow)."},
  "moonggoojeom-vegan-bakery-jeonpo": {"of": "32a2cd60", "story": "Moonggoojeom adalah toko roti yang vegan sepenuhnya di sebuah pertokoan kecil di Jeonpo-dong, di antara Seomyeon dan Pasar Bujeon. HappyCow mencantumkan kue kering dan pound cake beserta kopi; menunya sendiri menambahkan puding pistachio, kue kering bola kacang, dan biscotti. Tempat ini buka pada tengah hari dan tutup pada awal malam.", "esg": "Toko roti yang sepenuhnya nabati."},
  "rainbow-crust-toseong": {"of": "d574375a", "story": "Rainbow Crust adalah toko roti vegan yang mengkhususkan diri pada roti tepung beras, tujuh menit berjalan kaki dari Stasiun Jagalchi. HappyCow mencantumkannya sebagai toko roti vegan di lantai dasar gedung Vegan Mart, dengan roti seperti kayu manis kacang, bluberi, dan cokelat teh hijau. Kopinya dibuat dengan susu oat atau kedelai. Tempat ini buka pagi-pagi pada hari kerja.", "esg": "Toko roti yang sepenuhnya nabati."},
  "rice-bread-man-sajik": {"of": "f2a36622", "story": "Rice Bread Man adalah toko roti bawa pulang di Sajik-dong yang membuat roti tawar dan roti kecil tepung beras. HappyCow mencantumkannya sebagai vegan sepenuhnya sejak Juli 2024, ketika toko ini berhenti menjual produk susu dan daging; rotinya mencakup roti tawar beras kastanye dan ara, roti garam, dan roti kacang merah. Tidak ada meja, jadi tempat ini untuk bawa pulang. Tempat ini tutup pada hari Minggu.", "esg": "Toko roti yang sepenuhnya nabati."},
  "azimae-kitchen-nampo": {"of": "747add37", "story": "Azimae Kitchen adalah restoran Korea kecil di Jalan Arirang, Nampo-dong, yang memasak hidangan rumahan dan jajanan kaki lima. Tempat ini bukan dapur vegan — daging babi dan makanan laut ada di menunya — tetapi HappyCow menyebut hidangan vegannya diberi label dengan jelas: bibimbap lobak muda, nasi goreng kimchi, paket doenjang-jjigae, dan pangsit goreng, dengan gimbap dan tteokbokki vegan pada hari Sabtu. HappyCow juga menyebut stafnya fasih berbahasa Inggris. Tempat ini tutup pada hari Minggu."},
  "bibibim-gamcheon": {"of": "978ff6b7", "story": "Bibibim adalah restoran Korea kecil di Desa Budaya Gamcheon, desa di lereng bukit dengan rumah-rumah yang dicat. Tempat ini juga menyajikan bulgogi dan ayam, tetapi HappyCow mencantumkan hidangan vegan termasuk japchae kecap asin dan japchae pedas, panekuk kentang, serta tteokbokki dengan saus merah atau kecap asin, dan menu saat ini menambahkan pangsit sayur. Jalan kaki naik dari Stasiun Toseong cukup curam; ada juga bus desa."},
  "still-green-gangneung": {"of": "80d2e3d2", "story": "STILL, GREEN adalah restoran vegan kecil di dekat kota tua Gangneung yang memasak dengan sayuran organik setempat. HappyCow mencantumkannya sebagai vegan sepenuhnya. Hidangan musimannya disajikan ala Korea dengan nasi, lauk pendamping, dan sup; ada juga hidangan kari, pasta musiman, serta hidangan roti dan sup. Tempat ini hanya buka Kamis sampai Sabtu, dari 10:00 sampai 15:00, dan pengunjung diharapkan memesan tempat terlebih dahulu.", "esg": "Memasak dengan sayuran organik dari pertanian setempat (HappyCow)."},
  "cafe-hygge-gangneung": {"of": "e610ae12", "story": "Hygge Cafe Vegan Bakery adalah toko roti dan kafe yang vegan sepenuhnya di Byeongsan-dong, di sisi selatan Gangneung dekat bandara. HappyCow mencantumkan croissant, bagel, kue, dan roti kayu manis, serta tempat duduk di luar ruangan. Tempat ini dapat dicapai dengan bus atau taksi dari Stasiun Gangneung. Tanda terbaru bahwa tempat ini masih beroperasi adalah pembaruan menunya pada Agustus 2026, jadi periksa dahulu sebelum datang secara khusus.", "esg": "Toko roti yang sepenuhnya nabati."},
  "geuriun-boribap-sokcho": {"of": "e45b4ff4", "story": "Geuriun Boribab adalah restoran Korea di Sokcho yang berpusat pada nasi jelai, disajikan dengan sayuran gunung Gangwon dan semur kedelai. Tempat ini bukan dapur vegan — ikan makerel bakar dan tteokgalbi ada di menunya — tetapi HappyCow menyebut pemiliknya memahami pola makan vegan dan bahwa vegan dapat memesan nasi jelai dengan sayuran gunung. Paket makannya untuk dua orang atau lebih. Tempat ini buka pagi-pagi untuk sarapan dan tutup pada pertengahan sore, serta tutup pada hari Selasa."},
  "gohyang-sancheon-chodang-sundubu": {"of": "c91dadb1", "story": "Gohyang Sancheon Chodang Sundubu adalah restoran tahu lembut di Chodang, desa di Gangneung yang dikenal dengan tahu yang dipadatkan dengan air laut. Tempat ini bukan dapur vegan, tetapi HappyCow menyebut tempat ini menawarkan rebusan tahu lembut vegan dengan nasi atas permintaan, dan bahwa reservasi diwajibkan. Mintalah versi vegan saat memesan, karena lauk pendampingnya tidak dijelaskan. Tempat ini buka pukul 07:30 untuk sarapan dan tutup pada hari Rabu."},
  "yeah-vegan-bakery-wasan": {"of": "76fe2551", "story": "Yeah's Vegan Bakery Cafe adalah kafe hidangan penutup vegan kecil di Wasan-ri, sebuah desa pedalaman di timur laut Jeju. HappyCow mencantumkannya sebagai vegan sepenuhnya, dan menunya menggunakan mugwort Jeju, labu, lemon, dan krim kedelai dalam crumble, tart, dan cup cake, dengan financier dari tepung beras. Tempat ini tutup pada hari Selasa dan Rabu; mobil atau taksi adalah cara yang praktis untuk ke sana.", "esg": "Toko roti yang sepenuhnya nabati."},
  "ppangsagye-sagye": {"of": "948c4b82", "story": "Ppangsagye adalah toko roti vegan di Sagye-ri, desa di kaki Gunung Sanbangsan di pesisir barat daya Jeju. HappyCow mencantumkannya sebagai toko roti vegan yang menjual roti dan kudapan manis, dan menyebut hanya minuman yang dijual setelah rotinya habis, jadi datanglah lebih awal. Kopinya dibuat dengan susu kedelai atau susu oat. Tempat ini hanya buka pada hari kerja.", "esg": "Toko roti yang sepenuhnya nabati dan menggunakan bahan organik (HappyCow: 'Organic')."},
  "flexible-baker-sagye": {"of": "212feadf", "story": "The Flexible Baker adalah toko roti yang vegan sepenuhnya di desa Sagye, di kaki Sanbangsan di pesisir barat daya Jeju, yang menurut HappyCow dikelola oleh pasangan Korea-Amerika. Tempat ini memanggang pai ala Amerika, kue bundt, dan kukis bebas gluten dengan hasil bumi musiman Jeju dan Korea. Tempat ini hanya buka Jumat sampai Minggu; HappyCow menyebut minuman bawa pulang memerlukan gelas Anda sendiri.", "esg": "Diskon jika membawa wadah sendiri; minuman bawa pulang hanya dengan gelas sendiri (HappyCow)."},
  "jeju-chom-omegi": {"of": "d4d38021", "story": "Jeju Chom Omegi membuat omegi-tteok, kue beras tradisional Jeju, dalam empat jenis: kacang merah, injeolmi (bubuk kedelai sangrai), kacang-kacangan campur, dan wijen hitam. HappyCow mencantumkan kue berasnya sebagai vegan. Ini adalah toko bawa pulang yang berjarak sekitar sepuluh menit berjalan kaki dari terminal bus antarkota Jeju, buka sejak pagi-pagi, dan juga mengirimkan pesanan dalam kotak.", "esg": "Kue beras tradisional Jeju, dibuat sepenuhnya dari bahan nabati."},
  "jeju-mellow-seogwipo": {"of": "eac872eb", "story": "Jeju Mellow adalah restoran Korea kecil sekaligus toko nol sampah di Hogeun-dong, di sisi barat Seogwipo. Menunya saat ini adalah paket vegetarian berupa nasi daun teratai dengan lauk pendamping sayuran. HappyCow menyebut sebagian besar hidangannya vegan atau dapat dibuat vegan atas permintaan, jadi sampaikan hal itu saat memesan. Tempat ini tutup pada hari Selasa dan Rabu.", "esg": "Toko nol sampah yang menggunakan kemasan ramah lingkungan (HappyCow)."},
  "yetnal-patjuk-seongeup": {"of": "0cf23ba4", "story": "Yetnal Patjuk menyajikan bubur kacang merah tradisional di sebuah rumah batu Jeju yang telah direnovasi di dekat Desa Rakyat Seongeup. HappyCow menyebut sebagian besar hidangannya vegan: bubur kacang merah dengan bola-bola beras, mi kalguksu kacang merah, bubur labu, dan bubur wijen hitam. Tidak semuanya dijelaskan, jadi tanyakan tentang hidangan lainnya. Tempat ini tidak jauh berjalan kaki dari desa rakyat tersebut dan tutup pada hari Senin."},
  "misocheon-jeju": {"of": "cb062600", "story": "Smile Heaven adalah rumah teh tradisional Korea sekaligus restoran kecil di Ildo-dong, Kota Jeju. HappyCow mencantumkan hidangan vegan, vegetarian, dan hidangan bunga: bibimbap bunga dengan akar burdock dan konjak, tahu dan jamur renyah dengan saus asam manis, serta salad jeli biji ek. Tidak semuanya vegan — affogato-nya menggunakan es krim — jadi tanyakan dahulu. Tempat ini juga menyajikan teh jujube, teh jahe, dan teh ssanghwa, serta tutup pada hari Minggu."},
  "babiboyak-nohyeong": {"of": "d4e50f5f", "story": "Babiboyak ('nasi adalah obat') adalah restoran Korea yang hanya buka untuk makan siang di Nohyeong-dong, Kota Jeju. HappyCow menyebut semuanya vegan kecuali satu hidangan yang dibuat dengan kecap ikan, dan mencantumkan bibimbap, sup pasta kedelai, semur wijen, tahu, dan banyak lauk pendamping. Tanyakan hidangan mana yang memakai kecap ikan. Tempat ini buka dari menjelang siang sampai pertengahan sore dan tutup pada hari Minggu."},
  "bapjitneun-sigan-pyeongdae": {"of": "d2c0232d", "story": "Bapjitneun Sigan ('waktu menanak nasi') menyajikan masakan rumahan Korea dari sebuah ruangan di lantai atas di Pyeongdae, desa di pesisir timur Jeju dekat Sehwa. Dapurnya juga memasak ikan dan daging babi, tetapi empat hidangan ditandai vegetarian dan dibuat dengan kaldu sayuran: sup pakis dan biji perilla, nasi terung doubanjiang, nasi kari, dan semur jamur pedas. HappyCow mencantumkan keempatnya sebagai pilihan vegan di tempat ini. Tempat ini buka Rabu sampai Minggu mulai tengah hari."},
  "memilae-hallim": {"of": "5a0fea42", "story": "Memilae adalah restoran buckwheat khas Jeju di jalan pesisir di Hallim, di sisi barat pulau. Tempat ini juga menyajikan hidangan daging babi dan daging sapi, tetapi HappyCow menyebut vegan dapat memesan kalguksu buckwheat dan biji perilla, sujebi buckwheat, dan bingtteok, yaitu krep buckwheat tipis yang digulung dengan isi lobak berbumbu dan merupakan hidangan khas Jeju. HappyCow menyebut reservasi diwajibkan."},
  "bappulkkot-eunpyeong": {"of": "98dea1f0", "story": "Jeonhwan Village Kitchen Bappulkkot adalah dapur komunitas milik kelompok Transition Town di Eunpyeong. Cantumannya sendiri menggambarkan makanannya sebagai hidangan vegan rumahan dari hasil bumi musiman non-GMO, dan HappyCow mencantumkannya sebagai restoran vegan yang sebagian besar menggunakan bahan lokal dan organik. Menunya pendek: paket makan harian berisi nasi, sup, dan lauk pendamping, serta chaegaejang, sup sayuran pedas ala yukgaejang. HappyCow hanya memberikan jam makan siang pada hari kerja, jadi periksa dahulu sebelum pergi. Jaraknya tiga menit berjalan kaki dari Stasiun Gusan di Jalur 6."},
  "dalyang-hyehwa": {"of": "c8cefa13", "story": "Vegan Cafe Dalyang adalah kafe vegan di Hyehwa-ro, 16 menit berjalan kaki dari Stasiun Hyehwa. HappyCow mencantumkannya sebagai vegan, dengan sajian makanan fusi Barat dan Asia. Menu pada cantuman petanya mencakup ayam goreng berbahan kedelai, banh mi vegan, dan latte susu kedelai. Cantuman menu itu terakhir disunting pada 2024, jadi hidangan dan harganya mungkin sudah berubah."},
  "jihwaja-cheongun": {"of": "9e2b9c8b", "story": "Jihwaja menyajikan masakan istana kerajaan Korea dalam bentuk paket hidangan berurutan. Sebagian besar paketnya mengandung daging sapi atau makanan laut, tetapi menunya juga memiliki paket vegan (비건코스) seharga 160.000 won per orang, dan HappyCow menggambarkan menu terpisah yang vegan sepenuhnya, terdiri atas hidangan pembuka, hidangan utama, dan hidangan penutup. HappyCow menyebut permintaan khusus dilayani dengan reservasi di muka. Jaraknya sekitar 23 menit berjalan kaki dari Stasiun Gyeongbokgung menaiki Jahamun-ro, atau sebentar naik bus."},
  "malgeumine-changdong": {"of": "e922b690", "story": "Malgeumine hanya menyajikan satu hal: paket makan rumahan Korea (baekban) berisi nasi, sup, dan lauk pendamping. HappyCow menyebut tempat ini menawarkan versi vegan sepenuhnya dari menu biasanya, jadi mintalah paket vegan saat memesan. Ini adalah restoran lingkungan yang berjarak sekitar 22 menit berjalan kaki dari Stasiun Changdong."},
  "baengnyeonok-seocho": {"of": "8a43ecb0", "story": "Baengnyeonok membuat tahunya sendiri setiap hari. HappyCow menyebutkan nama hidangan vegannya: tahu sutra dengan nasi (자연식순두부) dan tahu putih atau tahu kacang hitam buatan sendiri, yang disajikan segar atau digoreng di wajan. Menu selebihnya mencakup daging babi, bebek, dan makanan laut, jadi pesanlah dengan menyebut nama hidangannya. Jaraknya 12 menit berjalan kaki dari Stasiun Nambu Bus Terminal di Jalur 3, di seberang Seoul Arts Center."},
  "cheongchun-sujebi-insadong": {"of": "c0fd525f", "story": "Cheongchun Sujebi Insadong membuat sujebi, sup berisi adonan gandum yang disobek dengan tangan, dan mi potong pisau. Menunya memberi label versi vegan secara terpisah: sujebi atau kalguksu vegan, panekuk vegan, pangsit vegan, dan tteokgalbi protein kedelai. Versi biasa dan panekuk udangnya tidak vegan, jadi pesanlah yang bertanda 비건. Jaraknya enam menit berjalan kaki dari Stasiun Anguk."},
  "mokmyeoksanbang-namsan": {"of": "f36dc96a", "story": "Mokmyeoksanbang adalah restoran bibimbap di lereng bawah Namsan, di jalur pejalan kaki yang naik dari Myeong-dong. HappyCow menyebut tempat ini menawarkan bibimbap vegan. Menunya tidak menandai hidangan mana yang vegan dan mencakup hidangan daging, jadi mintalah bibimbap vegan dengan menyebut namanya. Jaraknya 11 menit berjalan kaki dari Stasiun Myeong-dong."},
  "mokmyeoksanbang-namsan-tower": {"of": "3f7f0d75", "story": "Cabang Mokmyeoksanbang ini terletak di samping N Seoul Tower di puncak Namsan. HappyCow mencantumkan pilihan vegan termasuk bibimbap, ssambap, salad jeli biji ek, dan tteokbokki; menunya juga memiliki hidangan daging sapi dan daging babi dan tidak ada yang diberi label vegan, jadi tanyakan saat memesan. Jalan kaki naik dari Stasiun Myeong-dong memakan waktu sekitar 20 menit dan curam; kereta gantung Namsan dan bus juga naik ke atas."},
  "ijo-siktak-euljiro": {"of": "ff9f9fe5", "story": "Lee & Cho's Table menyajikan bibimbap dan nasi periuk (sotbap) di lantai atas di Euljiro. HappyCow menyebut dua hidangan diberi label vegan: bibimbap sayuran liar dan hidangan gondre (thistle) dengan tahu dan nasi. Mangkuk lainnya mengandung daging sapi atau daging babi. HappyCow mencatat tempat ini hanya menerima uang tunai. Jaraknya enam menit berjalan kaki dari Stasiun Euljiro 3-ga."},
  "monggeul-sundubu-itaewon": {"of": "a4360fc5", "story": "Monggeul Monggeul Sundubu Itaewon membuat tahunya sendiri dan menyajikan rebusan tahu lembut, hidangan tahu, serta mi dingin kuah susu kedelai. HappyCow menyebut beberapa hidangan vegan atau dapat dibuat vegan, termasuk tahu lembut putih dan tahu lembut perilla, tahu goreng wajan, dan mi dingin kuah susu kedelai. Kaldunya tidak dijelaskan, jadi katakan bahwa Anda vegan saat memesan. Hidangan daging babi dan tiram juga ada di menunya. Jaraknya sembilan menit berjalan kaki dari Stasiun Noksapyeong."},
  "sandotori-imjatang-eungam": {"of": "9697bfd9", "story": "Cabang Sandotori Imjatang ini memasak hampir semuanya dari biji ek: mi biji ek dengan sayuran, jeli biji ek dalam kaldu dengan nasi, jeli biji ek tumis sayuran, dan sup biji perilla (imjatang). HappyCow mencantumkan beberapa hidangan sebagai vegan atau dapat dibuat vegan; mintalah tumisannya tanpa saus tiram, dan tanyakan tentang kaldunya. Jaraknya sekitar 20 menit berjalan kaki dari Stasiun Eungam."},
  "sonyeo-bangatgan-seongsu": {"of": "1199858e", "story": "Sonyeo Bangatgan Seoul Forest menyajikan nasi yang dimasak dengan sayuran liar pegunungan, dengan paket yang menambahkan semur atau daging babi. HappyCow menyebut nasi sayuran gunung polos (산나물밥) adalah pilihan vegannya; lauk pendamping dan sausnya tidak dijelaskan, jadi katakan bahwa Anda vegan saat memesan. HappyCow mencatat adanya menu berbahasa Inggris. Jaraknya sembilan menit berjalan kaki dari Stasiun Ttukseom."},
  "urikong-sondubu-dobong": {"of": "c84fe1b8", "story": "Urikong Sondubu adalah restoran tahu di antara deretan rumah makan di titik awal jalur pendakian Dobongsan. HappyCow menyebut tempat ini memiliki hidangan vegan. Menunya tidak menandai hidangan mana yang vegan dan mencakup daging dan makanan laut, jadi tanyakan hidangan tahu dan kaldu mana yang nabati. Jaraknya 13 menit berjalan kaki dari Stasiun Dobongsan."},
  "daewon-kalguksu-guui": {"of": "5f6017e4", "story": "Daewon Kalguksu adalah rumah makan mi potong pisau di lantai dua dengan tempat duduk lesehan. HappyCow menyebutkan nama pilihan vegannya: mi dingin kuah susu kedelai dan mi buckwheat pedas pada musim panas, serta mi perilla pada musim dingin; mintalah tanpa telur. Kalguksu standar dan pangsitnya tidak digambarkan sebagai vegan. Jaraknya tiga menit berjalan kaki dari Stasiun Guui."},
  "memiljaengi-sillim": {"of": "a9384747", "story": "Memiljaengi memasak dengan buckwheat: mi, krep, panekuk, dan bibimbap kecambah. HappyCow menyebut bibimbap dengan micro greens dan beras cokelat adalah vegan dan pemiliknya dapat menyesuaikan hidangan lain; mintalah tanpa kecap ikan. Sebuah ulasan pelanggan menyebut saus mi buckwheat pedasnya mengandung ikan pollack kering. Jaraknya 13 menit berjalan kaki dari Stasiun Seoul National University Venture Town di Jalur Sillim."},
  "haurim-snu": {"of": "0d8f8de3", "story": "Haurim menyajikan masakan pedesaan Korea: nasi dengan sayuran gondre, akar deodeok bakar, bibimbap sayuran liar, dan jeli biji ek dengan nasi. HappyCow menyebut hidangan-hidangan ini vegan atau dapat dibuat vegan; mintalah bibimbap tanpa telur. Sebagian besar menu selebihnya adalah daging atau ikan. Cantuman menunya terakhir disunting pada 2023, jadi harganya mungkin sudah berubah. Jaraknya empat menit berjalan kaki dari Stasiun Seoul National University."},
  "sunhuine-bindaetteok-gwangjang": {"of": "544b52de", "story": "Sunhuine Bindaetteok menggiling dan menggoreng panekuk kacang hijau (bindaetteok) di Pasar Gwangjang. HappyCow menyebut panekuk kacang hijau polosnya vegan; lewatkan kimchinya, yang mengandung kecap ikan. HappyCow juga melaporkan bahwa panekuk tersebut memakai minyak dan peralatan yang sama dengan panekuk daging, jadi vegan yang ketat mungkin ingin bertanya. Hidangan daging, udang, dan yukhoe tidak vegan. Jaraknya tiga menit berjalan kaki dari Stasiun Jongno 5-ga."},
  "hangaram-bukchang": {"of": "6f80c103", "story": "Hangaram menyajikan paket makan Korea (jeongsik), yang sebagian besar berpusat pada daging atau makanan laut. HappyCow menyebut menu vegan tersedia jika Anda memintanya, dan bahwa reservasi diwajibkan, jadi pesanlah tempat terlebih dahulu dan katakan bahwa Anda memerlukan menu vegan. Jaraknya 9 menit berjalan kaki dari Stasiun City Hall."},
  "ilsang-yangjae": {"of": "04fdca67", "story": "Ilsang menyajikan masakan kuil Korea sebagai paket makan harian, paket spesial yang lebih besar, dan paket hidangan berurutan. HappyCow mencantumkannya sebagai vegetarian dan menyebut dapurnya akan menghilangkan telur dan produk susu jika Anda meminta vegan, jadi mintalah saat memesan. HappyCow memberikan jam buka pada waktu makan siang. Jaraknya hampir 30 menit berjalan kaki dari Stasiun Yangjae, jadi bus atau taksi lebih mudah."},
  "cow-tteokbokki-ewha": {"of": "8a8bcb01", "story": "Cow Tteokbokki adalah kedai tteokbokki di dekat Ewha Womans University dengan menu tanpa daging yang terpisah: tteokbokki polos, mala, jjajang, dan rosé, bola-bola nasi, dan kentang goreng. HappyCow menyebutnya menu vegan, sedangkan cantuman kedai itu sendiri melabeli hidangannya 채식 (vegetarian) dan versi carbonara mungkin mengandung produk susu, jadi pastikan mana yang vegan saat memesan. HappyCow mencatat adanya menu digital dalam empat bahasa. Jaraknya tujuh menit berjalan kaki dari Stasiun Ewha Womans University."},
  "maju-iyagi-suyu": {"of": "7b2a96ad", "story": "Maeul Chatjip Maju Iyagi adalah rumah teh dan toko roti lingkungan di lantai dua di Suyu-dong. HappyCow mencantumkannya sebagai vegan: kue dan aneka panggangan, minuman susu kedelai, burger tahu, dan roti lapis yang dibuat dengan keju dan mentega nabati buatan sendiri. Menunya menyebut burger tahu tidak disajikan pada hari Selasa dan Jumat, yaitu saat roti beragi alami dipanggang. Tempat ini tidak menggunakan gelas atau alat makan sekali pakai. Jaraknya 14 menit berjalan kaki dari Stasiun Hwagye di Ui LRT."},
  "cafe-yeorm-namgajwa": {"of": "29a1e638", "story": "Cafe Yeorm adalah tempat sangrai kopi kecil sekaligus kafe baca. Menunya menyebut setiap makanannya vegan dan bahwa latte dibuat dengan susu oat atau susu kacang polong sebagai pengganti susu sapi. Makanannya ringan: roti gandum hitam atau ciabatta dengan selai dan acar, dan HappyCow menyebut baguette dengan jamur dan mayones tahu. Tempat ini ditata untuk satu atau dua orang per meja dan meminta rombongan empat orang atau lebih agar tidak datang bersama. Jaraknya 26 menit berjalan kaki dari Stasiun Gajwa, jadi bus lebih mudah."},
  "vegan-ire-chungjeongno": {"of": "fad53476", "story": "Vegan Ire adalah kafe hidangan penutup vegan kecil. HappyCow menggambarkannya sebagai sepenuhnya vegan, dengan kopi, latte kedelai, minuman ade buah, teh, scone, dan kukis, dan menunya mencantumkan kue teh serta beragam teh. HappyCow mencatat menunya berbahasa Korea. Jaraknya sepuluh menit berjalan kaki dari Stasiun Chungjeongno."},
  "jigu-jegwa-yeonnam": {"of": "22257c3e", "story": "Jigu Jegwa adalah toko roti bawa pulang kecil di Yeonnam-dong. Cantumannya sendiri menyebut tempat ini memanggang dengan bahan nabati, dan HappyCow mencantumkannya sebagai toko roti yang sepenuhnya vegan dengan kue, kukis, tart, muffin, dan roti loyang. Tidak ada tempat duduk. HappyCow menyarankan untuk memeriksa Instagram-nya sebelum pergi, karena produknya bisa habis terjual. Jaraknya sekitar 20 menit berjalan kaki dari Stasiun Hongik University."},
  "love-it-box-amsa": {"of": "14dc919b", "story": "Love It Box adalah toko kue panggang vegan kecil di dekat Stasiun Amsa. Cantumannya sendiri dan HappyCow sama-sama menyebut kue panggangnya tidak mengandung produk susu, telur, tepung rafinasi, gula putih, atau pewarna buatan. Tempat ini membuat kukis, butter bar, dan bottle cake. HappyCow tidak memiliki jam bukanya, jadi periksa Instagram-nya sebelum pergi. Jaraknya empat menit berjalan kaki dari Stasiun Amsa di Jalur 8."},
  "yeonhwa-baru-gyeongju": {"of": "516398b9", "story": "Yeonhwa Baru menyajikan masakan kuil Buddha Korea di Seoak-dong, di sisi barat Gyeongju. HappyCow mencantumkannya sebagai vegan dan menyebut semua makanannya vegan. Menunya memiliki paket makan dengan banyak hidangan berurutan, bibimbap sayuran gunung, panekuk kacang hijau dan panekuk kentang, hidangan jamur asam manis, dan hidangan daging kedelai yang dimasak semur. Jaraknya sekitar 2,5 km dari terminal bus antarkota, jadi naiklah taksi atau bus.", "esg": "Masakan kuil yang dibuat tanpa bahan hewani."},
  "daereungwon-bonga-gyeongju": {"of": "0cd018c6", "story": "Daereungwon Bonga adalah restoran Korea di Hwangnam-dong, kawasan kota tua di dekat Hwangnidan-gil. HappyCow mencantumkan pilihan ramah vegan di sini, seperti rebusan tahu, semur kedelai fermentasi, dan mi dingin. Menunya juga memiliki hidangan ikan, makanan laut, dan daging babi, dan semur serta kuah mi Korea sering dibuat dengan kaldu ikan teri, makanan laut, atau daging sapi, jadi beri tahu staf bahwa Anda tidak makan daging, ikan, atau telur dan tanyakan hidangan mana yang dapat dibuat seperti itu."},
  "wonmajung-gyeongju": {"of": "befd7c58", "story": "Wonmajung adalah restoran Korea di Hwangnam-dong, Gyeongju, yang menyajikan paket makan hotpot jamur. HappyCow menyebut kedua hotpotnya, yaitu hotpot tahu dan jamur serta hotpot jamur neungi, dapat dibuat vegan atas permintaan dengan tambahan tahu dan jamur, dan bahwa Anda sebaiknya meminta lauk pendamping tanpa ikan. Restoran ini juga menyajikan hidangan daging babi, jadi katakan dengan jelas saat memesan bahwa Anda tidak makan daging, ikan, atau telur."},
  "cheongram-daegu": {"of": "055925fb", "story": "Cheongram adalah prasmanan masakan rumahan Korea di pusat Daegu, di dekat pasar obat herbal Yangnyeongsi. HappyCow menyebut ragam lauk pendamping sayuran, nasi, dan minya memungkinkan Anda menyusun sepiring hidangan yang vegan sepenuhnya. Prasmanan ini juga memiliki hidangan daging dan ikan, dan sayuran berbumbu serta kimchi bisa mengandung kecap ikan atau ikan teri, jadi tanyakan kepada staf hidangan mana yang hanya berbahan nabati. Jaraknya sekitar 14 menit berjalan kaki dari Stasiun Banwoldang."},
  "yonghwaru-daemyeong-daegu": {"of": "d09174f0", "story": "Yonghwaru Son-jjajang adalah restoran mi Korea-Tionghoa di dekat Stasiun Myeongdeok di Daegu. HappyCow mencantumkan jajangmyeon vegan (mi saus kacang hitam), jjamppong (sup mi pedas), dan hidangan jamur asam manis. Sebuah ulasan pengunjung tahun 2026 di Kakao menyebut versi vegannya harus disiapkan terlebih dahulu, jadi teleponlah lebih dulu untuk memesan, dan bahwa jajangmyeon vegannya untuk dua orang atau lebih. Menu biasanya menggunakan daging dan makanan laut."},
  "banhal-gimbap-daegu": {"of": "b8e52124", "story": "Banhal Gimbap adalah kedai gimbap dan mi kecil di dekat Banwoldang di pusat Daegu. HappyCow mencatat adanya gimbap vegan yang diberi label dengan jelas, dan hidangan itu ada di menu saat ini sebagai 비건김밥. Menu selebihnya mencakup gimbap tuna, keju, dan daging sapi serta kotlet daging babi, jadi pesanlah gimbap vegan dengan menyebut namanya. Jaraknya sekitar 8 menit berjalan kaki dari Stasiun Banwoldang."},
  "zero-table-suseong-daegu": {"of": "45662752", "story": "Zero Table adalah toko roti kecil di samping Pasar Suseong di Daegu. HappyCow menyebut semua yang dipanggangnya vegan dan sebagian besar bebas gluten. Instagram-nya sendiri saat ini menyebut toko ini hanya buka dengan reservasi ('현재는 예약으로 운영됩니다'), jadi pesanlah sebelum Anda pergi. Latte-nya dibuat dengan susu kedelai atau susu almon. Jaraknya 3 menit berjalan kaki dari Stasiun Suseong Market di Jalur 3."},
  "oli-bread-hwanggeum-daegu": {"of": "9f7e6af0", "story": "Oli Bread adalah toko roti vegan di distrik Suseong, Daegu, yang sebagian besar memanggang dengan tepung beras. HappyCow mencantumkan roti isi krim dan kukis serta roti yang lebih sederhana seperti ciabatta dan roti tawar loyang. Jaraknya sekitar 14 menit berjalan kaki dari Stasiun Hwanggeum di Jalur 3."},
  "vegeloun-sincheon-daegu": {"of": "af176687", "story": "Vegeloun adalah toko roti vegan kecil di pertokoan sebuah kompleks apartemen di Sincheon-dong, Daegu. HappyCow mencantumkan roti bun dan kue manis. Jaraknya sekitar 20 menit berjalan kaki dari Stasiun Dongdaegu, perhentian KTX di Daegu."},
  "mushimushi-dongseongro-daegu": {"of": "a9cd57e1", "story": "Mushimushi Dongseong-ro adalah kedai poke bowl dan sushi gulung di kawasan belanja Dongseong-ro, Daegu. HappyCow menyebut sushi vegan dan bowl vegan tersedia, dan menu saat ini memiliki poke tahu. Sebagian besar bowl menggunakan ikan atau daging, dan sausnya bisa mengandung ikan atau telur, jadi mintalah versi vegan. Tempat ini berada di satu gedung dengan restoran lain, sekitar 15 menit berjalan kaki dari Stasiun Jungangno."},
  "slb-salad-gamsam-daegu": {"of": "a3be3053", "story": "SLB Salad Gamsam adalah kedai salad dan bowl cabang Gamsam yang berada tepat di dekat Stasiun Gamsam di Jalur 2 Daegu. HappyCow menyebutkan salad labu vegan dan menyebut salad vegetarian lainnya dapat dibuat vegan atas permintaan. Sebagian besar salad disajikan dengan daging, ikan, atau keju, jadi mintalah versi vegan dan periksa sausnya."},
  "bakery-yul-sindang-daegu": {"of": "3ed69890", "story": "Bakery Yul adalah toko roti lingkungan di pertokoan sebuah kompleks apartemen di kawasan Seongseo, Daegu, yang memanggang dengan ragi alami. HappyCow menyebut beberapa rotinya vegan, seperti sourdough, baguette, dan roti buah. Sebagian besar produknya menggunakan produk susu atau telur, jadi tanyakan roti mana yang vegan pada hari itu."},
  "yaraehyang-pyeonggeo-jinju": {"of": "cf3b3cfc", "story": "Yaraehyang adalah restoran Korea-Tionghoa di Pyeonggeo-dong, Jinju. HappyCow menyebut tempat ini memiliki menu vegan, termasuk japchae cabai, jamur asam manis, sup sayuran, dan lumpia, dan cantuman petanya menampilkan jajangmyeon vegetarian. Menu utamanya menggunakan daging dan makanan laut, jadi mintalah menu vegan. Jaraknya sekitar 4 km dari terminal bus antarkota."},
  "sugis-kitchen-geoje": {"of": "37cc9cf4", "story": "Sugi's Kitchen adalah restoran Korea dan Barat yang santai di tepi Pantai Wahyeon di Pulau Geoje. HappyCow menyebut bibimbap dan bibim-guksu (mi campur pedas) dapat dibuat vegan jika Anda meminta vegan dan tanpa telur, dan bahwa pemiliknya dapat menjelaskan bahan-bahannya dalam bahasa Inggris. Semur tahu di menu saat ini adalah versi makanan laut, dan sebagian besar hidangan lainnya mengandung daging atau ikan."},
  "hello-india-al-waha-jangpyeong": {"of": "ff3924e0", "story": "Hello India Al-Waha Jangpyeong menyajikan masakan India dan Lebanon di Jangpyeong-dong, Pulau Geoje. HappyCow menyebut menunya tidak diberi label, tetapi pilihan vegannya mencakup kentang cabai, baba ganoush, hummus, dan dal lentil, dan staf akan menjelaskan bahan-bahannya. Hidangan India sering menggunakan ghee atau krim, jadi mintalah tanpa produk susu. Ini adalah salah satu dari beberapa cabang di pulau ini; entri ini mencakup cabang Jangpyeong."},
  "polani-poke-sinjeong-ulsan": {"of": "a318d375", "story": "Polani Poke Ulsan adalah kedai poke bowl di Sinjeong-dong, Ulsan, yang merupakan bagian dari sebuah jaringan. HappyCow menyebut tempat ini membuat poke bowl vegan dengan tahu atau falafel, dan kedua bowl tersebut ada di menu saat ini. Saus dan topingnya mungkin mengandung telur atau ikan, jadi mintalah versi vegan. Letaknya cukup jauh dari stasiun kereta; naiklah bus atau taksi."},
  "bakery-bobo-okdong-ulsan": {"of": "db1c4577", "story": "Bakery Bobo adalah toko roti independen di Ok-dong, Ulsan, tidak jauh berjalan kaki dari gerbang utama Ulsan Grand Park. HappyCow menyebut produk vegannya diberi label dalam bahasa Inggris dan Korea, di antaranya sourdough, bagel bluberi, dan ciabatta, dan bahwa pemiliknya berbahasa Inggris. Pastri lainnya menggunakan mentega dan telur, jadi carilah labelnya."},
  "namaskar-samsan-ulsan": {"of": "7e5962f7", "story": "Namaskar Samsan adalah restoran India dan Nepal di lantai dua di Samsan-dong, Ulsan, 7 menit berjalan kaki dari terminal bus antarkota. HappyCow mencatat banyak hidangan vegetarian dan menyarankan untuk menanyakan soal produk susu; menunya memiliki kari sayuran, kacang arab, lentil, dan jamur. Mintalah tanpa ghee, mentega, atau krim, dan periksa apakah naan-nya mengandung susu."},
  "oatplat-mulgeum-yangsan": {"of": "57f0aba8", "story": "OATPLAT adalah toko kue panggang kecil di Mulgeum-eup, Yangsan. HappyCow menyebut tempat ini memiliki pilihan vegan, termasuk kukis, madeleine, dan brownies fudgy, dan bahwa Anda sebaiknya memesan terlebih dahulu. Tidak semua produknya vegan, jadi tanyakan saat memesan. Jaraknya sekitar 3,5 km dari stasiun kereta bawah tanah terdekat."},
  "tteulanchae-suwon": {"of": "9db20045", "story": "Tteulanchae Vegetarian Buffet adalah prasmanan vegan Korea di Suwon bagian barat. Dengan harga tetap Anda mendapat sekitar 20 hidangan, termasuk nasi, mi, salad, lauk pendamping, dan hidangan daging tiruan, menurut HappyCow, yang mencantumkannya sebagai vegan. HappyCow juga mencatat bahwa bir atau anggur disajikan. Tidak ada kereta bawah tanah di dekatnya, jadi naiklah bus atau taksi, dan periksa jam bukanya sebelum Anda pergi.", "esg": "Prasmanan Korea tanpa daging."},
  "bonjuk-bomun": {"of": "7b8e527e", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea, yang terletak di Bomun-ro di samping Stasiun Bomun. HappyCow mencantumkan bubur wijen hitam, labu, kacang merah, kacang pinus, dan kacang hijau sebagai pilihan vegan di sini. Sebagian besar menunya adalah bubur abalon, daging sapi, makanan laut, atau ayam, dan catatan HappyCow hanya mencakup cabang ini. Jaraknya dua menit berjalan kaki dari Stasiun Bomun."},
  "bonjuk-bongcheon-station": {"of": "f6c7380d", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea, yang terletak di Nambusunhwan-ro dekat Stasiun Bongcheon. HappyCow mencantumkan bubur wijen hitam, labu, kacang merah, kacang pinus, dan kacang hijau sebagai pilihan vegan di sini. Sebagian besar menunya adalah bubur abalon, daging sapi, makanan laut, atau ayam, dan catatan HappyCow hanya mencakup cabang ini. Jaraknya tiga menit berjalan kaki dari Stasiun Bongcheon."},
  "bonjuk-bongil-market": {"of": "efde9a3a", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea, yang terletak di Euncheon-ro dekat Pasar Bongil. HappyCow mencantumkan bubur wijen hitam, labu, kacang merah, kacang pinus, dan kacang hijau sebagai pilihan vegan di sini. Sebagian besar menunya adalah bubur abalon, daging sapi, makanan laut, atau ayam, dan catatan HappyCow hanya mencakup cabang ini. Jaraknya sepuluh menit berjalan kaki dari Stasiun Bongcheon."},
  "bonjuk-doksan-citylex": {"of": "98fd67b0", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea, yang terletak di lantai lima gedung CITYLEX di Siheung-daero, di sebelah Homeplus. HappyCow mencantumkan bubur wijen hitam, labu, kacang merah, kacang pinus, dan kacang hijau sebagai pilihan vegan di sini. Sebagian besar menunya adalah bubur abalon, daging sapi, makanan laut, atau ayam, dan catatan HappyCow hanya mencakup cabang ini. Jaraknya 16 menit berjalan kaki dari Stasiun Doksan."},
  "bonjuk-sillim-gosichon": {"of": "4d325548", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea, yang terletak di Daehak-gil di kawasan lama tempat belajar para peserta ujian di Sillim. HappyCow mencantumkan bubur wijen hitam, labu, kacang merah, kacang pinus, dan kacang hijau sebagai pilihan vegan di sini. Sebagian besar menunya adalah bubur abalon, daging sapi, makanan laut, atau ayam, dan catatan HappyCow hanya mencakup cabang ini. Jaraknya 11 menit berjalan kaki dari Stasiun Seoul National University Venture Town."},
  "bonjuk-nangok": {"of": "f664d650", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea, yang terletak di Nangok-ro di lingkungan Nangok. HappyCow mencantumkan bubur wijen hitam, labu, kacang merah, kacang pinus, dan kacang hijau sebagai pilihan vegan di sini. Sebagian besar menunya adalah bubur abalon, daging sapi, makanan laut, atau ayam, dan catatan HappyCow hanya mencakup cabang ini. Jaraknya 37 menit berjalan kaki dari Stasiun Sillim, jadi bus adalah cara yang praktis untuk ke sana."},
  "bonjuk-sillim-nokdu": {"of": "d9ef50b6", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea, yang terletak di Hoam-ro di Nokdu Street, kawasan mahasiswa di bawah Seoul National University. HappyCow mencantumkan bubur wijen hitam, labu, kacang merah, kacang pinus, dan kacang hijau sebagai pilihan vegan di sini. Sebagian besar menunya adalah bubur abalon, daging sapi, makanan laut, atau ayam, dan catatan HappyCow hanya mencakup cabang ini. Jaraknya lima menit berjalan kaki dari Stasiun Seoul National University Venture Town."},
  "bonjuk-singil-sareoga": {"of": "bc997438", "story": "Cabang Bonjuk ini, jaringan kedai bubur nasi Korea, berada di Singil-ro di Singil-dong. HappyCow mencantumkan bubur wijen hitam, labu, kacang merah, kacang pinus, dan kacang hijau sebagai pilihan vegan di sini. Sebagian besar menunya adalah bubur abalon, daging sapi, makanan laut, atau ayam, dan catatan HappyCow hanya mencakup cabang ini. Tempat ini berjarak 15 menit berjalan kaki dari Stasiun Sinpung."},
  "bibiri-hongdae": {"of": "a88102f1", "story": "Bibiri adalah prasmanan bibimbap di lantai bawah tanah dekat Stasiun Hongik University: pengunjung mengisi mangkuk dari aneka sayuran dan saus dengan satu harga. HappyCow menyebut sebagian besar hidangannya vegan, termasuk sup mentimun atau sup rumput laut, dan bahwa staf akan membantu pengunjung vegan. Topping daging juga ada di prasmanan, jadi pilihlah isian dengan cermat. Tempat ini berjarak lima menit berjalan kaki dari Stasiun Hongik University."},
  "cham-bareun-gimbap-hapjeong": {"of": "3e08a010", "story": "Cham Bareun Gimbap adalah kedai gimbap kecil di Dongmak-ro, di antara Hapjeong dan Sangsu. Hampir semua gulungan di menunya berisi tuna, ham, daging, telur, atau keju; HappyCow menyebut beberapa hidangan gimbap, kue beras, dan sup mi dapat dibuat vegan atas permintaan, jadi mintalah versi vegan saat memesan. Tempat ini berjarak sepuluh menit berjalan kaki dari Stasiun Hapjeong."},
  "fully-gimbap-seongsu": {"of": "5a855b00", "story": "Fully Gimbap adalah kedai gimbap di sebuah menara perkantoran di Seongsu. HappyCow menggambarkan gimbap vegan yang isinya dapat dipilih sendiri, dengan sayuran, jamur, dan tahu goreng, dan menu kedai ini sendiri memuat gulungan yang dinamainya vegan protein gimbap. Sebagian besar gulungan lain berisi daging, ikan, atau telur, termasuk gulungan sayuran, yang dibuat dengan telur. Tempat ini berjarak tujuh menit berjalan kaki dari Stasiun Seongsu."},
  "samcheongdang-anam": {"of": "d6ebf7af", "story": "Samcheongdang adalah kedai gimbap dan udon di dekat Korea University. Menunya memuat gimbap vegan hummus, yang digulung dengan wortel, mentimun, acar lobak, kubis, lembaran tahu, hummus, dan selada romaine; selebihnya menu ini kebanyakan berisi daging, telur ikan, atau telur. Tempat ini berjarak empat menit berjalan kaki dari Stasiun Anam."},
  "samcheongdang-hongdae": {"of": "c51b27ae", "story": "Kedai Samcheongdang di Hongdae menjual gimbap, udon, dan tteokbokki. HappyCow menyebut satu gulungan vegan, yaitu gimbap dengan hummus dan tahu, dan gulungan itu masih ada di menu; HappyCow juga mencatat laporan Juni 2025 bahwa pilihan vegannya terbatas. Tempat ini berjarak sekitar 19 menit berjalan kaki dari Stasiun Sinchon."},
  "soonnam-siraegi-myeongdong": {"of": "f4a83ad9", "story": "Soonnam Siraegi adalah jaringan restoran Korea yang berpusat pada siraegi, daun lobak kering, yang disajikan dalam sup dan bersama nasi, ditambah bar lauk pendamping swalayan. HappyCow menyebut cabang Myeongdong ini punya hidangan utama dan lauk pendamping vegan tetapi tidak menyebutkan namanya, dan menunya juga memuat daging babi rebus, daging sapi, dan kerang, jadi tanyakan hidangan dan kaldu mana yang vegan. Tempat ini berjarak lima menit berjalan kaki dari Stasiun Myeong-dong."},
  "soonnam-siraegi-chungmuro": {"of": "88398cdd", "story": "Cabang Soonnam Siraegi di Chungmuro ini menyajikan sup dan nasi yang dibuat dengan siraegi, daun lobak kering, dengan sudut lauk pendamping swalayan. HappyCow menyebut hidangan yang ramah vegan mencakup sup, soun, dan acar sayuran, sebagian dari lauk swalayan; HappyCow tidak menyebut sup yang mana, jadi tanyakan. HappyCow juga memperingatkan bahwa jam bukanya tidak dapat diandalkan. Tempat ini berjarak delapan menit berjalan kaki dari Stasiun Euljiro 3-ga."},
  "guksuga-daehakro": {"of": "dfedb320", "story": "Guksuga adalah rumah makan mi di Daehak-ro. HappyCow menyebut sup mi kacang merahnya, yaitu mi gandum dalam sup kacang merah kental yang disajikan tanpa bumbu agar Anda menambahkan sendiri garam dan gula, sebagai pilihan vegan, dan menyebut mi dingin kuah susu kedelai dapat dipesan tanpa telur. Sebagian besar mi lainnya memakai kerang, daging, atau telur. Tempat ini berjarak enam menit berjalan kaki dari Stasiun Hyehwa."},
  "korea-house-pildong": {"of": "174bf4f1", "story": "Korea House menyajikan hidangan set Korea di kompleks hanok dekat Namsangol Hanok Village. HappyCow menyebut menu setnya dapat dibuat vegan atas permintaan dan bahwa reservasi diwajibkan, jadi mintalah versi vegan saat Anda memesan tempat. Tempat ini berjarak 6 menit berjalan kaki dari Stasiun Chungmuro di Jalur 3 dan 4."},
  "parc-hannam": {"of": "5bd4f090", "story": "Parc memasak hidangan rumahan Korea di Hannam-dong. HappyCow menyebut tempat ini menawarkan hidangan vegetarian musiman yang berganti-ganti dan dapat dibuat vegan atas permintaan, serta memperingatkan bahwa kimchinya tidak vegan. Tanyakan kepada staf hidangan mana yang dapat disiapkan vegan pada hari itu. Tempat ini berjarak 9 menit berjalan kaki dari Stasiun Hangangjin di Jalur 6."},
  "eden-sikdang-yeouido": {"of": "72f2b906", "story": "Eden Sikdang menyajikan set sayuran gunung berbumbu dengan nasi dan sup doenjang berisi tahu dan jamur, di arkade lantai bawah tanah gedung Lotte Castle Empire. HappyCow mencantumkan set ini sebagai pilihan vegannya tetapi menyebut hanya dua dari lima lauk pendampingnya, yaitu kubis dan jeli biji ek, yang vegan, jadi mintalah staf untuk tidak menyertakan yang lain. Tempat ini berjarak 6 menit berjalan kaki dari Stasiun Yeouido di Jalur 5 dan 9."},
  "dos-tacos-snu-station": {"of": "2fccb145", "story": "Cabang Dos Tacos ini menyajikan makanan Meksiko bergaya Korea di sisi Sharosu-gil dari Stasiun Seoul National University. HappyCow menyebut burrito kacang tumbuk (refried beans), kentang, sayuran, dan sayuran goreng dapat dibuat vegan jika Anda meminta staf untuk tidak menyertakan produk susu. Tempat ini berjarak 5 menit berjalan kaki dari Stasiun Seoul National University di Jalur 2."},
  "shin-old-teahouse-insadong": {"of": "cec2ec5b", "story": "Shin Old Tea House menyajikan teh tradisional Korea dan kue beras di Insadong-gil. HappyCow menyebut tempat ini punya kue beras vegan termasuk injeolmi dan menawarkan alternatif susu nabati; menunya juga memuat café latte dan es krim, jadi mintalah susu nabati bila Anda menginginkannya. Tempat ini berjarak 6 menit berjalan kaki dari Stasiun Anguk di Jalur 3."},
  "traditional-teahouse-insadong": {"of": "3a8778da", "story": "Rumah teh di Insadong-gil ini menyajikan teh, minuman punch, dan kudapan manis tradisional Korea. HappyCow mencantumkannya sebagai tempat dengan pilihan vegan dan menyebut es krim serta es serutnya mengandung susu; menunya juga memuat kopi instan dan minuman biji-bijian yang mungkin mengandung susu, jadi tanyakan sebelum memesannya. Tempat ini berjarak 8 menit berjalan kaki dari Stasiun Anguk di Jalur 3."},
  "gangjeong-house-cheongdam": {"of": "27672971", "story": "Gangjeong House menjual kudapan manis tradisional Korea seperti gangjeong, yakgwa, dan kue beras, beserta teh dan minuman, di sebuah kafe modern di Cheongdam. HappyCow menyebut hidangan penutup, penganan, dan minuman vegan tersedia tetapi tidak menyebut yang mana, jadi tanyakan kepada staf. Tempat ini berjarak 8 menit berjalan kaki dari Stasiun Cheongdam di Jalur 7."},
  "gyeonggi-tteokjip-mangwon": {"of": "a2b0b905", "story": "Gyeonggi Tteokjip adalah toko kue beras tradisional beberapa langkah dari Stasiun Mangwon, khusus bawa pulang. HappyCow mencantumkannya sebagai tempat dengan pilihan vegan dan menyarankan untuk bertanya kepada staf kue beras mana yang vegan. Tempat ini berjarak 3 menit berjalan kaki dari Stasiun Mangwon di Jalur 6."},
  "dduckhamji-jamsil": {"of": "880ba059", "story": "Dduckhamji membuat kue beras dengan mugwort, yang dijual per kotak dari sebuah toko di lantai bawah tanah Galleria Palace. HappyCow menggambarkan kue beras mugwortnya sebagai hidangan penutup vegan dari beras ketan, mugwort, dan garam laut. Tempat ini berjarak 15 menit berjalan kaki dari Stasiun Jamsil di Jalur 2 dan 8."},
  "boribori-wolgye": {"of": "d9129696", "story": "Restoran Korea di samping Stasiun Wolgye ini menyajikan nasi jelai dengan aneka sayuran untuk dicampurkan. HappyCow menyebut set nasi jelainya tanpa daging dan mencantumkan tempat ini sebagai tempat dengan pilihan vegan, tetapi tidak menyebut apakah lauk pendamping atau sausnya mengandung ikan, jadi tanyakan kepada staf. Tempat ini berjarak 3 menit berjalan kaki dari Stasiun Wolgye di Jalur 1."},
  "sujeong-naengmyeon-guwol": {"of": "8bd4d9d5", "story": "Sujeong Naengmyeon menyajikan satu hal saja: mi dingin, dalam mangkuk biasa atau besar. HappyCow menyebut kaldunya dibuat dari sayuran, dan setiap mangkuk disajikan dengan sebutir telur rebus; mintalah tanpa telur (gyeran ppaejuseyo) dan hidangan ini menjadi vegan. Tempat ini berada di Guwol-dong, Namdong-gu."},
  "sucheol-shrimp-masian": {"of": "034e1640", "story": "Cabang Sucheol-ine di Pantai Masian ini terutama menjual udang raja goreng, tetapi HappyCow menyebut dapurnya melayani kebutuhan vegan dan membuat hidangan seperti tteokbokki (kue beras pedas) dan gimmari (gulungan rumput laut goreng) menjadi vegan atas permintaan. Hidangan-hidangan itu tidak vegan sebagaimana tercantum di menu, jadi mintalah agar dibuat vegan saat Anda memesan, dan tanyakan cara memasaknya."},
  "shabu-allday-yongin-ic": {"of": "1cb738a3", "story": "Shabu All Day adalah prasmanan shabu-shabu dengan harga tetap: Anda memasak daging dan sayuran dalam kaldu di meja dan mengambil sendiri dari bar salad. HappyCow menyebut ada banyak pilihan untuk vegan, termasuk sayuran, tahu, jamur, mi, salad, buah, dan sup yang dapat disesuaikan. Harganya disusun untuk daging sepuasnya, jadi tanyakan kaldu mana yang tidak memakai kaldu daging atau makanan laut sebelum Anda mulai."},
  "seoul-soba-gunsan": {"of": "a2ad1c4a", "story": "Seoul Soba menyajikan soba gandum kuda dingin dan memil-jeon, panekuk tipis dari gandum kuda. HappyCow mencantumkan keduanya sebagai vegan, tetapi juga mencatat laporan tahun 2023 bahwa pilihan vegannya telah menjadi terbatas, jadi tanyakan apakah saus celupnya dibuat tanpa kaldu ikan sebelum Anda memesan."},
  "gokmuljip-gongju": {"of": "b91d7500", "story": "Gokmuljip, 'rumah biji-bijian', adalah kafe dan toko di Gongju yang mengolah biji-bijian asli Korea: latte biji-bijian, wafel gandum lokal, dan kudapan panggang. HappyCow menyebut kukisnya vegan. Produk lain mungkin mengandung susu, jadi tanyakan kue panggang mana yang vegan dan latte mana yang dapat dibuat dengan susu nabati."},
  "gamijeong-damyang": {"of": "5b64b41b", "story": "Gamijeong adalah restoran keluarga di pedesaan dekat Damyang yang menyajikan makanan Barat bergaya Korea. HappyCow menyebut kokinya bersedia mengganti daging dan telur di hidangan apa pun dengan kacang merah, dan bahwa banyak sayurannya ditanam di seberang jalan; tidak ada yang vegan kecuali Anda memintanya. HappyCow juga menyebut reservasi diwajibkan."},
  "so-luck-ansan": {"of": "fa0fc1bc", "story": "So Luck adalah kafe hidangan penutup kecil yang dihias seperti kamar tidur merah muda penuh boneka. HappyCow menyebut kukis dan cupcake-nya mencakup yang berlabel vegan; selebihnya di etalase tidak vegan, jadi carilah labelnya atau tanyakan."},
  "slow-cali-pyeongchon": {"of": "fba1316c", "story": "Slow Cali adalah jaringan poke bowl; ini cabangnya di Pyeongchon. HappyCow menyebut ada satu mangkuk vegan di menu dan bahwa Anda dapat menyusun sendiri dari sayuran, edamame, dan tahu. Sebagian besar mangkuknya berisi tuna, salmon, atau udang, jadi katakan bahwa Anda menginginkannya tanpa ikan atau telur dan periksa sausnya."},
  "weekly-picnic-anyang": {"of": "1972b19f", "story": "Weekly Picnic adalah kafe lingkungan di Pyeongchon. HappyCow menyebut bagel polos, bluberi, dan everything-nya sudah dikonfirmasi vegan dan bahwa susu oat tersedia untuk kopi. Olesan dan kue panggang lainnya mungkin mengandung susu, jadi tanyakan."},
  "bresh-avenue-gwacheon": {"of": "642a4270", "story": "Bresh Avenue telah membuat roti di Gwacheon sejak 2013, menurut cantuman Kakao milik pemiliknya. HappyCow menyebut beberapa roti dan jusnya vegan, susu nabati tersedia, dan menunya diberi label dengan baik. Sebagian besar kuenya mengandung susu atau telur, jadi ikuti labelnya."},
  "fetu-songdo": {"of": "d2977fc4", "story": "FETU (From Earth To Us) adalah kafe brunch di Songdo yang menyajikan hidangan Timur Tengah dan Eropa. HappyCow menyebut pilihan vegannya: 'Tofu in Hell', roti lapis shiitake panggang, dan hummus dengan pita. Selebihnya menu ini memuat telur dan daging, jadi periksa apa yang Anda pesan."},
  "raj-indian-unseo": {"of": "c2043a6a", "story": "Raj adalah restoran India Utara di dekat stasiun Unseo, tidak jauh dari Bandara Incheon. HappyCow mencantumkan kari sayuran, nasi, dan naan sebagai pilihan vegan. Dapur India sering memakai ghee, mentega, atau krim, jadi mintalah hidangan Anda tanpa produk susu."},
  "mint-seed-bakery-maseok": {"of": "51c27763", "story": "Mint Seed adalah toko roti kecil di Maseok, Hwado-eup. HappyCow menyebutnya ramah vegan dan menyebut berbagai roti tawarnya cocok untuk vegan. Tidak semuanya demikian, jadi tanyakan roti mana yang dibuat tanpa susu, mentega, atau telur."},
  "maximo-burrito-yeongtong": {"of": "b3dce8a6", "story": "Maximo Burrito adalah kedai burrito dan taco di Yeongtong. HappyCow menyebut burrito nasi alpukat dan taconya menjadi vegan tanpa produk susu. Mintalah tanpa keju atau krim asam."},
  "om-restaurant-gwanggyo": {"of": "31f6206e", "story": "Ini adalah cabang Gwanggyo dari Om, jaringan restoran Nepal-India. HappyCow menyebut kari sayurannya mudah dibuat vegan atas permintaan: katakan bahwa Anda menginginkannya vegan saat memesan, tanpa ghee, mentega, atau krim."},
  "dal-bodre-bakery-suwon": {"of": "c448d424", "story": "Dal Bodre adalah toko roti organik di dekat Benteng Hwaseong yang mengembangkan rotinya dengan nuruk. HappyCow menyebut roti vegannya diberi label 비건; HappyCow menyebut baguette, campagne gandum utuh, dan ciabatta kentang. Kue panggang lainnya memakai susu atau mentega, jadi periksa labelnya."},
  "oakberry-lotte-suwon": {"of": "9c30a6ff", "story": "Oakberry adalah jaringan açaí; gerai ini berada di lantai tiga mal Lotte di Seodun-dong. HappyCow menyebut mangkuk dan smoothie-nya dapat dibuat dengan topping vegan seperti buah, biji-bijian, dan kacang, dengan susu kedelai tersedia. Beberapa topping tidak vegan, jadi pilihlah sendiri."},
  "langlang-suwon": {"of": "4c8e2989", "story": "Langlang adalah kafe dan toko roti di Haenggung-ro yang menyajikan roti lapis, hidangan penutup, dan kopi. HappyCow menyebut roti lapis alpukatnya dapat dibuat vegan jika Anda memintanya; tidak ada hidangan lain yang dicantumkan sebagai vegan."},
  "lagniappe-jeongja": {"of": "e3c787d2", "story": "Lagniappe memasak perpaduan hidangan Cajun, Meksiko, dan Vietnam yang dipengaruhi New Orleans. HappyCow menyebut pilihan vegannya: banh mi, mangkuk nasi atau mi dengan tahu dan sayuran musiman dalam kecap asin, dan sepiring gulungan kertas beras rakit sendiri untuk dua orang. Menunya juga memuat daging babi, daging sapi, dan ayam, jadi mintalah versi vegannya."},
  "kasam-suwon": {"of": "e028c647", "story": "Kasam adalah restoran India di Deogyeong-daero di Paldal-gu. HappyCow menyebut beberapa hidangan dapat dibuat vegan dengan tahu, dan meminta Anda menegaskan tanpa yoghurt, mentega, ghee, krim, atau dadih. Sebagian besar menunya adalah ayam, daging domba, atau paneer."},
  "lazy-susan-wirye": {"of": "28d898a8", "story": "Lazy Susan adalah toko kue panggang kecil di Wirye New Town. HappyCow menyebut sebagian hidangan penutupnya vegan dan bebas alergen, di samping kopi dan teh. Tidak semuanya demikian, jadi tanyakan scone dan brownies mana yang vegan pada hari itu."},
  "the-taco-booth-icn-t1": {"of": "3ddad480", "story": "The Taco Booth adalah kios taco dan burrito di area keberangkatan Terminal 1, setelah pemeriksaan keamanan di dekat Gerbang 12. HappyCow menyebut burrito bowl tahunya dapat dibuat vegan: mintalah tanpa produk susu."},
  "naan-ajou-suwon": {"of": "27f476bf", "story": "Naan adalah restoran India di dekat Ajou University. HappyCow mencantumkan samosa, gorengan, dal fry atau dal tadka, aloo gobi, dan nasi sebagai pilihan vegan, dan menyebut hidangan vegetarian dapat dibuat vegan atas permintaan. Mintalah tanpa ghee, mentega, atau krim."},
  "cafe-rebirth-godeok": {"of": "ad623928", "story": "Cafe Rebirth adalah kafe roti vegetarian di Godeok-dong, Pyeongtaek. HappyCow menyebut tempat ini menawarkan beragam kue, scone, dan kukis yang ramah vegan, ditambah kue panggang bebas gluten. Beberapa produk memakai susu, jadi tanyakan mana yang vegan."},
  "la-moire-mangwon": {"of": "4c41b4f3", "story": "Cafe La Moire adalah kafe roti kecil di Mangwon yang digambarkan HappyCow sebagai vegan, dengan kue dan minuman. Menunya mencantumkan latte biasa terpisah dari latte oat, jadi mintalah susu nabati untuk kopi Anda."},
  "pizzeria-436-asan": {"of": "27708a18", "story": "Pizzeria 436 menyajikan piza bergaya Italia di Sinjeong-ro di Asan. HappyCow menyebut pilihan vegannya: salad rucola, roti piza, dan piza marinara. Piza dan pasta lainnya memakai keju atau daging."},
  "hail-cheongju": {"of": "6865cc33", "story": "Hail adalah kafe roti di pusat Cheongju yang membuat kue panggang tanpa tepung putih atau gula rafinasi. HappyCow menggambarkannya sebagai vegan; daftar minumannya menawarkan latte oat dan almon di samping minuman susu lainnya, jadi mintalah susu nabati dan periksa kue panggangnya."},
  "insaeng-burger-taean": {"of": "58f78d41", "story": "Insaeng Burger adalah kedai burger di Pado-ri, Sowon-myeon, di Kabupaten Taean. HappyCow dan menu kedai ini sendiri sama-sama mencantumkan burger vegan, yang disajikan dengan kentang goreng. Burger lainnya berisi daging sapi, bacon, dan keju."},
  "little-delight-daejeon": {"of": "9d7c9edb", "story": "Little Delight adalah kafe pastry Prancis kecil di Eoeun-dong, Yuseong-gu. HappyCow menyebut tempat ini membuat pastry dan kudapan vegan dengan tepung beras cokelat organik, gandum utuh, dan oat dalam negeri serta minyak dedak padi, dan menawarkan susu nabati. Tanyakan pastry mana yang vegan pada hari itu."},
  "bowl-recipe-sangmu": {"of": "62c7ef1c", "story": "Bowl Recipe adalah jaringan poke bowl; ini cabangnya di Sangmu. HappyCow menyebut 'Natural Poke' sebagai vegan, dan menu saat ini juga memuat 'Vegan X Poke'. Menunya hanya dalam bahasa Korea, dan mangkuk lainnya mengandung ikan atau daging."},
  "first-nepal-gwangju": {"of": "c059c0c9", "story": "HappyCow mencantumkan First Nepal sebagai restoran Nepal-India di pusat kota Gwangju dengan pilihan vegetarian dan vegan, dan menyarankan untuk menegaskan vegan saat Anda memesan. Sebagian besar menunya adalah ayam dan daging domba, dan rotinya mungkin mengandung mentega."},
  "mungmong-mannam-gwangju": {"of": "c7f440a1", "story": "Mungmong Mannam adalah kafe dan toko nol sampah di Sansu-dong. HappyCow menyebut tempat ini melayani vegan dengan puding tomat, brownies vegan, dan susu nabati untuk latte, dan menunya sendiri mencantumkan kue cokelat vegan dan gugelhopf vegan mini. Kue lainnya mengandung susu."},
  "chaekand-gwangju": {"of": "afe6fd98", "story": "Chaek and Saenghwal ('buku dan kehidupan') adalah toko buku independen dan kafe perpustakaan di Jang-dong, Dong-gu. HappyCow menyebut tempat ini membuat kue panggang vegan untuk menemani kopi. Tanyakan apa yang vegan pada hari itu."},
  "april-and-december-jeonju": {"of": "cbec96c6", "story": "April & December adalah kafe brunch vegetarian kecil di gang samping Katedral Jeondong, di tepi Jeonju Hanok Village. HappyCow menyebut tempat ini menyajikan brunch musiman dan teh dengan roti pisang vegan; brunch-nya dapat mengandung telur atau susu, jadi mintalah versi vegan."},
  "letter-of-light-jeonju": {"of": "32ce8e50", "story": "Letter of Light adalah kafe vegetarian di dekat Jeonju Gaeksa yang menyajikan roti lapis, pasta, hidangan mangkuk, salad, dan kue panggang. HappyCow menyebut tempat ini punya keju vegan serta susu kedelai, oat, dan kelapa, dan menunya mencantumkan roti garam vegan. Beberapa hidangan memakai telur atau susu, jadi tanyakan. Cantuman Kakao milik pemiliknya meminta pengunjung memeriksa jam buka di Instagram atau Naver."},
  "eat-anything-jeonju": {"of": "ae519a55", "story": "Eat Anything adalah kafe fusi di kampung seni Seohak di Jeonju, dengan hotel untuk kucing liar di terasnya. HappyCow menyebut pasta, risotto, dan roti lapis vegannya diberi label dengan jelas, dan menu saat ini menandai satu pasta vegan, satu roti lapis vegan, dan satu 'vegan latte' dari oat. Hidangan lainnya memuat ikan teri dan ayam. HappyCow menyebut reservasi diwajibkan."},
  "nomadic-brewing-jeonju": {"of": "a6f4678e", "story": "Nomadic Brewing adalah brewpub independen kecil di dekat Jeolla Gamyeong, yang dikelola seorang ahli pembuat bir dari Michigan. HappyCow menyebut kentang goreng organik dan ayam goreng vegannya dapat dibuat tanpa produk hewani dan bahwa popcornnya dimasak dengan minyak kelapa. Tempat ini adalah bar yang menyajikan alkohol."},
  "connect-with-jochiwon": {"of": "8181fe9a", "story": "Connect With adalah kafe di dalam Jochiwon Cultural Garden, bekas instalasi penjernihan air. HappyCow menyebut roti garam dan roti isi kacang manisnya vegan dan bahwa kopi dapat dibuat dengan susu oat. Kue panggang dan minuman lainnya mengandung susu."},
  "the-india-suncheon": {"of": "0dae6a17", "story": "The India adalah restoran India di Jorye-dong. HappyCow menyebut pilihan vegannya, seperti biryani sayuran, kari sayuran campur, dan dal tadka, mudah disesuaikan; mintalah tanpa ghee, mentega, atau krim. HappyCow meminta pembaruan untuk cantuman ini."},
  "le-ble-suncheon": {"of": "ed582e57", "story": "Le Blé adalah kafe roti di Wangji-dong yang memakai tepung organik. HappyCow menyebut sebagian besar rotinya polos atau gurih dan menyebut yang vegan: baguette, roti biji-bijian utuh, ciabatta polos dan zaitun, serta campagne. Kue panggang manis mungkin mengandung telur atau mentega."},
  "for-you-restaurant-yeosu": {"of": "8324b9cd", "story": "For You adalah restoran Italia di Odongdo-ro di Yeosu. HappyCow menyebut ada pilihan vegetarian dan vegan di antara antipasti, pasta, piza, dan saladnya, tetapi Anda harus memintanya. HappyCow menyebut reservasi diwajibkan."},
  "alien-mill-jeonju-docheong": {"of": "44d87fc5", "story": "Alien Mill adalah toko roti di dekat kantor Provinsi Jeonbuk di Jeonju. HappyCow menyebut roti vegannya diberi stiker hijau; carilah stiker itu, karena selebihnya di etalase tidak vegan."},
  "levant-jeonju": {"of": "483d78bd", "story": "Levant menyajikan jajanan kaki lima Timur Tengah di Deokjin-gu, Jeonju. HappyCow mencantumkan hummus dan aneka cocolan, hidangan falafel, salad, sambosa sayuran, dan roti di antara pilihan vegannya. HappyCow mencatat bahwa tempat ini juga menyajikan daging."},
  "masala-jeonju": {"of": "31b00374", "story": "Masala adalah restoran India di Junghwasan-dong, Jeonju. HappyCow menyebut tempat ini punya beragam hidangan vegetarian dan bahwa Anda sebaiknya meminta versi vegan; menunya memuat dal tadka, aloo gobi, chana masala, dan vindaloo sayuran. Mintalah tanpa ghee atau krim. Menunya juga memuat hidangan daging babi, daging domba muda, ayam, dan udang."},
  "nuovo-napoli-gungdong": {"of": "fd8a9004", "story": "Nuovo Napoli adalah restoran piza di Gung-dong, Yuseong-gu. HappyCow menyebut tiga pilihan vegan: piza marinara, pasta pomodoro, dan salad mista. Piza lainnya memakai keju, sosis, atau prosciutto."},
  "present-muan": {"of": "0fe5e7a3", "story": "Présent adalah kafe brunch di Mangun-myeon, Muan. HappyCow menyebut tempat ini menyajikan piza dan brunch dengan pilihan vegan, termasuk salad, roti lapis, dan steik hamburger vegan. Hidangan lainnya mengandung daging, telur, atau susu, jadi mintalah versi vegannya."},
  "dunnae-makguksu-suyeong": {"of": "fd70966c", "story": "Dunnae Makguksu adalah kedai mi gandum kuda kecil di gang-gang dekat Stasiun Suyeong. Menunya pendek: mi gandum kuda dingin berkuah atau dengan saus pedas, panekuk gandum kuda, dan gulungan krep gandum kuda. HappyCow menyebut panekuk gandum kudanya vegan dan bahwa sup mi dinginnya dapat dipesan tanpa telurnya: mintalah tanpa telur saat memesan. Dapurnya bukan dapur vegan, dan tidak ada hidangan di menu yang diberi label vegan."},
  "sulgodang-nampo": {"of": "97d4ab69", "story": "Sulgodang adalah restoran masakan rumahan Korea di lantai dua sebuah gedung dekat Pasar Gukje di Nampo-dong. Hidangan andalannya adalah daging babi yang dibakar dengan api, dan menunya juga memuat rebusan kimchi dengan daging babi serta sup rumput laut daging sapi, tetapi tempat ini punya bagian vegan tersendiri: steik tahu, mi tipis dengan minyak perilla, nasi goreng sayuran pedas, ramyeon sayuran, sup kerak nasi, dan japchae jamur, masing-masing disajikan dengan enam lauk pendamping vegan. Pesanlah dari bagian itu; selebihnya menu ini tidak vegan."},
  "kim-youngae-halmeoni-sundubu-sokcho": {"of": "01218e78", "story": "Kim Youngae Halmeoni Sundubu adalah restoran tahu lembut di Haksapyeong, kampung tahu Sokcho di jalan menuju Seoraksan, yang menyajikan tahu dari kedelai Korea. Tempat ini buka pagi-pagi dan tutup pukul 2 siang, serta tutup pada hari Selasa. HappyCow menyebut tempat ini menawarkan aneka lauk pendamping vegan dan bahwa Anda sebaiknya meminta tanpa kecap ikan. Dapurnya bukan dapur vegan: HappyCow mencatat bahwa tempat ini menyajikan daging."},
  "samgyori-dongchimi-makguksu-chuncheon": {"of": "90a20c56", "story": "Cabang Chuncheon dari Samgyori Dongchimi Makguksu ini menyajikan mi buckwheat dalam dongchimi, kuah dingin kimchi air lobak yang Anda bumbui sendiri dengan saus merah, minyak wijen, cuka, dan mustar. HappyCow menyebut ada dua pilihan bagi vegan: mi tanpa telur, dan panekuk buckwheat tanpa kimchi, yang mengandung ikan. Sampaikan keduanya kepada staf. Menunya juga memuat irisan daging babi rebus dan yukgaejang, jadi ini bukan dapur vegan."},
  "nammae-sikdang-gangneung": {"of": "27c85815", "story": "Nammae Sikdang adalah restoran kecil masakan rumahan Korea di dekat Stasiun Gangneung, dengan semur, tumisan, dan bibimbap yang disajikan bersama aneka lauk pendamping. HappyCow menyebut Anda bisa memesan bibimbap tanpa telur, daging, atau ikan, dan menyarankan untuk menunjukkan kalimat ini kepada staf: 비빔밥이 먹고싶은데요 계란과 고기, 생선 없이 만들어주세요. HappyCow menambahkan bahwa sebagian lauk pendamping mungkin tidak vegan. Tamu duduk di bantal lantai pada meja rendah."},
  "sun-hansik-jeongdongjin": {"of": "214096d6", "story": "Sun Hansik adalah restoran Korea di samping Stasiun Jeongdongjin, perhentian tepi laut yang dikenal karena matahari terbitnya, yang menyajikan hidangan tahu ala Gangneung, semur, hotpot, dan bibimbap mangkuk batu sejak pagi-pagi. HappyCow menyebut satu hidangan tahu dengan nasi dan bibimbapnya bisa dibuat vegan atas permintaan; mintalah tanpa telur, daging, atau kecap ikan. Banyak hidangan lain mengandung daging atau makanan laut."},
  "nammun-nami-island": {"of": "3d8c97ef", "story": "Nammun adalah restoran Korea di Pulau Nami yang menyajikan paket nasi daun teratai, bibimbap, panekuk, dan jeli biji ek. HappyCow menyebut bibimbap dan salad jeli biji ek termasuk pilihan vegannya; mintalah bibimbap tanpa telur atau daging. Sebagian besar menunya mengandung daging atau makanan laut. Bibimbap dipesan untuk dua orang."},
  "kalguksu-yeonguso-seongsan": {"of": "f6f7fb52", "story": "Kalguksu Yeonguso ('Lab Kalguksu', tercantum di HappyCow sebagai Noodle Lab) adalah kedai mi Korea di Seongsan, sekitar satu kilometer dari Seongsan Ilchulbong. HappyCow menyebut sup mi kacang merah, bubur kacang merah dengan bola-bola beras, dan kalguksu biji perilla di antara hidangan vegannya. Menunya juga memuat mi dan bubur makanan laut serta ikan pollack, jadi tanyakan kaldu apa yang dipakai tiap hidangan. Kedai ini buka pukul 8 pagi dan tutup pada hari Minggu."},
  "umutgae-ilbeonji-seongsan": {"of": "9d9cfca9", "story": "Umutgae Ilbeonji adalah restoran keluarga di dekat Seongsan Ilchulbong yang buka pukul 6 pagi, tepat waktu untuk pendakian melihat matahari terbit. Sebagian besar menunya yang pendek berupa makanan laut, yaitu ramyeon makanan laut serta bubur abalon dan kerang, ditambah semangkuk nasi bulgogi sapi. HappyCow menyebut beberapa hidangan vegan atau bisa dibuat vegan, dan menyebut nama sup taoge; tanyakan bagaimana kaldunya dibuat."},
  "ilpum-sundubu-hagwi": {"of": "20b04e03", "story": "Ilpum Sundubu Hagwi adalah restoran tahu lembut di Hagwi, di jalan pesisir sebelah barat Kota Jeju. Tempat ini salah satu restoran tahu lembut Ilpum Sundubu di Jeju, yang menyajikan nasi mangkuk batu dan aneka lauk pendamping swalayan bersama setiap semur. HappyCow menyebut jaringan ini menawarkan rebusan tahu lembut jamur vegan dengan kaldu sayuran; menunya mencantumkan sundubu jamur (버섯순두부) tetapi tidak menjelaskan kaldunya, jadi mintalah kaldu sayuran. Sebagian besar semur mengandung makanan laut, daging babi, atau daging sapi, dan sebagian lauk pendamping tidak vegan."},
  "ilpum-sundubu-yeondong": {"of": "26904aef", "story": "Ilpum Sundubu Yeondong adalah restoran tahu lembut di Yeon-dong, Kota Jeju, tidak jauh dari bandara dengan taksi. Tempat ini salah satu restoran tahu lembut Ilpum Sundubu di Jeju, yang menyajikan nasi mangkuk batu dan aneka lauk pendamping swalayan bersama setiap semur. HappyCow menyebut jaringan ini menawarkan rebusan tahu lembut jamur vegan dengan kaldu sayuran; menunya mencantumkan sundubu jamur (버섯순두부) tetapi tidak menjelaskan kaldunya, jadi mintalah kaldu sayuran. Sebagian besar semur mengandung makanan laut, daging babi, atau daging sapi, dan sebagian lauk pendamping tidak vegan."},
  "ilpum-sundubu-tapdong": {"of": "ff3d32ef", "story": "Ilpum Sundubu Tapdong adalah restoran tahu lembut di tepi laut Tapdong di kawasan lama Kota Jeju. Tempat ini salah satu restoran tahu lembut Ilpum Sundubu di Jeju. HappyCow menyebut rebusan tahu lembut jamur dan gulungan krep buckwheat dengan kimchi sebagai pilihan vegannya; tanyakan soal kaldunya dan apakah kimchinya mengandung kecap ikan, seperti yang sering terjadi pada kimchi Korea. Sebagian besar semur mengandung makanan laut, daging babi, atau daging sapi, dan sebagian lauk pendamping tidak vegan."},
  "benjamin-poke-namsan": {"of": "21f5c8a8", "story": "Benjamin Poke & Salad adalah kedai poke kecil di jalan samping antara Myeong-dong dan Namsan. Menunya memuat satu mangkuk berlabel vegan, berisi jamur, asparagus, dan tahu; mangkuk lainnya memakai udang, daging sapi mentah, tuna, salmon, bebek, atau ayam. Letaknya lima menit berjalan kaki dari Stasiun Myeong-dong."},
  "otto-gimbap-itaewon": {"of": "a718307c", "story": "Otto Gimbap adalah kedai gimbap di Gyeongnidan yang sebagian besar penjualannya berupa pesan antar. HappyCow menyebut kedai ini memakai mayones vegan dan tuna nabati, dan menunya memuat gimbap tuna vegan; gulungan lainnya berisi Spam atau telur ikan, dan ayam goreng juga dijual. Letaknya sekitar 18 menit berjalan kaki dari Stasiun Noksapyeong."},
  "park-myeongdo-makguksu-wonhyoro": {"of": "925dd904", "story": "Restoran ini menyajikan makguksu, mi buckwheat ala Bongpyeong di Provinsi Gangwon. HappyCow menyebut kaldunya vegan dan bahwa makguksu kuah dingin maupun makguksu campur pedas sama-sama vegan jika Anda memintanya tanpa telur. Sebagian besar sisa menunya berupa daging babi, jadi pesanlah minya dengan menyebut namanya. Letaknya 11 menit berjalan kaki dari Stasiun Hyochang Park."},
  "voice-of-the-seasons-ewha": {"of": "3a27e72b", "story": "The Voice of the Seasons adalah kafe di lantai dua dekat Ewha Womans University, dengan meja-meja panjang untuk bekerja atau belajar. Menunya menandai beberapa hidangan sebagai vegan: mangkuk yoghurt kedelai dengan granola, bagel yoghurt kedelai, bingsu susu oat, dan brownies fudge. Latte dengan susu sapi biasa juga disajikan, jadi pilihlah yang bertanda. Letaknya lima menit berjalan kaki dari Stasiun Ewha Womans University."},
  "soba-yeonguso-sinchon": {"of": "cbe9b2e4", "story": "Soba Yeonguso adalah kedai mi buckwheat ala Jepang di dekat Myeongmul-gil, Sinchon. HappyCow menyebut kedai ini menawarkan soba vegan dengan minyak perilla dan basil; soba minyak perilla itu ada di menunya di samping hidangan ikan, jadi mintalah versi vegannya saat memesan. Letaknya sembilan menit berjalan kaki dari Stasiun Sinchon."},
  "surinnal-jokbal-jangchung": {"of": "a623ea86", "story": "Tempat ini salah satu restoran jokbal (kaki babi semur) di jalan jokbal Jangchung-dong, dan sebagian besar menunya berupa daging babi dan sapi. HappyCow menyebut ada dua hidangan yang cocok bagi vegan: jaengban guksu, sepiring besar mi dingin dengan sayuran yang disebutnya vegan sebagaimana disajikan, dan bibimbap yang dipesan tanpa telur. Letaknya empat menit berjalan kaki dari Stasiun Dongguk University."},
  "namhansanseong-kkwabaegi-geoyeo": {"of": "1eaeb3d1", "story": "Kedai kecil di Geoyeo-dong ini menggoreng kkwabaegi, donat pilin Korea, dan donat bulat. HappyCow menggambarkan beberapa kkwabaegi ramah vegan yang dibuat dengan beras ketan, gula, kacang merah, dan labu; HappyCow tidak menyebut yang mana, jadi tanyakan. Letaknya sekitar 22 menit berjalan kaki dari Stasiun Geoyeo."},
  "seoul-eunma-kkwabaegi-gyeongbokgung": {"of": "d073cfdf", "story": "Kios bawa pulang ini menggoreng donat Korea di samping Stasiun Gyeongbokgung, di sisi Seochon. HappyCow menyebut yang vegan diberi label dengan jelas: donat pilin beras ketan, donat kacang merah, dan donat bola beras. Hot dognya tidak vegan. Letaknya tiga menit berjalan kaki dari Stasiun Gyeongbokgung."},
  "cafe-binteum-mangwon": {"of": "5e2e6cf9", "story": "Cafe Binteum adalah kafe sekaligus perpustakaan manga di dekat Pasar Mangwon, dengan rak-rak komik untuk dibaca selagi Anda duduk. HappyCow menyebut kafe ini menyajikan bingsu vegan, es serut Korea, dan menyediakan susu nabati untuk kopi; bingsu itu ditandai vegan di menunya, sedangkan wafelnya tidak vegan. HappyCow mengingatkan bahwa pintu masuknya mudah terlewat, di gang buntu kecil di dalam kawasan pasar. Letaknya sepuluh menit berjalan kaki dari Stasiun Mangwon."},
  "bronto-sinjeong": {"of": "e3b571ae", "story": "Bronto adalah toko roti kecil di dekat Omokgyo yang memanggang kukis, banyak di antaranya vegan dan bebas gluten, dari tepung gandum utuh atau tepung beras cokelat. HappyCow menyebutnya sebagian besar vegan dan mencatat laporan tahun 2023 tentang cokelat panas putih yang tidak vegan, jadi periksalah minumannya; menunya menandai beberapa kukis sebagai vegan. Sebuah ulasan tahun 2026 menyebut toko ini hanya buka pada hari Jumat dan Sabtu, jadi periksalah sebelum datang. Letaknya delapan menit berjalan kaki dari Stasiun Omokgyo."},
  "base-is-nice-dohwa": {"of": "ebdf239f", "story": "Base is Nice menyajikan satu paket hidangan sayuran Korea musiman, hanya dengan reservasi. HappyCow menyebutnya restoran ovo-vegetarian yang menunya sebagian besar vegan: beberapa hidangan disajikan dengan telur, dan kokinya tidak memakainya jika Anda mengatakan bahwa Anda vegan, jadi sampaikan hal itu saat memesan tempat. Letaknya sekitar 12 menit berjalan kaki dari Stasiun Gongdeok."},
  "hwangsaengga-kalguksu-samcheong": {"of": "fa8d2da3", "story": "Hwangsaengga adalah rumah makan mi di jalan kecil antara Gyeongbokgung dan Samcheong-dong, yang menyajikan kalguksu dalam kaldu tulang sapi dan pangsit besar, keduanya tidak vegan. Hidangan vegannya musiman: HappyCow menyebut sup mi dingin kedelai (kongguksu) yang disajikan dari Mei hingga Agustus itu vegan, dan menunya menandainya sebagai hidangan musim panas. Di luar musim panas mungkin tidak ada yang vegan di sini. Letaknya sekitar 13 menit berjalan kaki dari Stasiun Anguk."},
  "everest-curry-world-dongdaemun": {"of": "94391ce6", "story": "Everest Curry World adalah restoran India dan Nepal di lantai dua, tiga menit berjalan kaki dari Stasiun Dongdaemun. Sebagian besar menunya berupa kari ayam dan daging domba, tetapi HappyCow menyebut stafnya paham arti vegan dan akan menunjukkan hidangan vegannya: dua jenis dal, samosa, dan satu jenis roti. Tanyakan kepada mereka yang mana, karena dal dan roti sering dibuat dengan mentega atau ghee. Tidak ada sumber yang menyebut apa pun tentang halal."},
  "hummus-kitchen-parnas-samseong": {"of": "a328a9ab", "story": "Hummus Kitchen adalah restoran Timur Tengah di lantai bawah tanah Parnas Mall, antara Stasiun Samseong dan COEX. HappyCow mencantumkan hummusnya (beberapa jenis) dan falafelnya sebagai vegan, dan mengingatkan bahwa roti pita serta saus keju yang disajikan bersama falafel sama-sama mengandung susu, jadi mintalah agar keduanya tidak disertakan. Selebihnya, menunya mencakup ayam, daging sapi, daging domba muda, dan makanan laut. Tidak ada sumber yang menyebut apa pun tentang halal."},
  "aum-huam": {"of": "97b99bce", "story": "Aum adalah kafe brunch dua lantai di Huam-dong, di kaki Namsan. HappyCow menyebut pilihan vegannya diberi label, dan menyebut roti sourdough, buah musiman dengan yoghurt kedelai, sup tomat, gazpacho jagung, dan satu hidangan natto-alpukat, yang semuanya ada di menu saat ini. Hidangan lain memakai ayam, ikan teri, atau keju, dan susu nabati tersedia untuk kopi. Letaknya sekitar 22 menit berjalan kaki dari Stasiun Sookmyung Women's University."},
  "myeongga-uyukmyeon-seolleung": {"of": "9b78d7b2", "story": "Myeongga Uyukmyeon menyajikan sup mi sapi Taiwan, tetapi HappyCow menyebut tempat ini memiliki menu vegan terpisah: mi mala, terung goreng asam manis, dan panekuk daun bawang ala Tiongkok. Menu di peta mencantumkan 마라면, 풍미가지, dan 수좌병; mintalah versi vegannya, karena sup mi sapi dibuat di dapur yang sama. Letaknya sekitar 11 menit berjalan kaki dari Stasiun Seolleung."},
  "seongwon-uyukmyeon-sillim": {"of": "cf9681c6", "story": "Seongwon Uyukmyeon adalah restoran Tiongkok di Sillim-dong yang menyajikan sup mi sapi dan daftar panjang tumisan, sebagian besar dengan daging babi atau sapi. HappyCow menyebut hidangan vegannya: salad dingin tahu kering, salad dingin jamur enoki, dan salad dingin kentang iris, terung tumis, serta tahu kering tumis cabai. Letaknya sekitar 26 menit berjalan kaki dari Stasiun Sillim; naik bus di sepanjang Nangok-ro lebih cepat."},
  "sunny-bowl-yeomni": {"of": "edbec3ac", "story": "Sunny Bowl adalah restoran kecil tiga menit dari Stasiun Ewha Womans University. HappyCow menggambarkan sup, salad, pasta, kari, dan rotinya sebagai vegan kecuali tambahan keju yang opsional, dan menu saat ini tidak memuat hidangan daging: di antaranya pasta ragù tempe, kari santan, salad hummus kinoa, dan jjamppong sayuran. Lewatkan taburan kejunya, dan tanyakan soal pasta yaki-mayo, yang mayonesnya mungkin mengandung telur."},
  "abiko-curry-times-square": {"of": "a1289585", "story": "Abiko adalah jaringan kari ala Jepang; cabang ini berada di lantai bawah tanah mal Times Square dekat Stasiun Yeongdeungpo. HappyCow menyebut pilihan vegannya ditandai dengan jelas di menu, dan menyebut kari sayuran serta tahu goreng dengan kari sayuran, yang keduanya ada di menu saat ini. Menu di peta tidak menampilkan tanda vegan itu, jadi carilah tandanya atau tanyakan sebelum memesan."},
  "aloha-poke-hakdong": {"of": "91b7a92c", "story": "Aloha Poke adalah bar poke Hawaii empat menit berjalan kaki dari Stasiun Hakdong. HappyCow menyebut pilihan vegannya ditandai dengan jelas dan menyebut tiga, yang semuanya ada di menu saat ini: poke tahu Maui, salad Vegan Paradise, dan salad tempe BBQ vegan. Sebagian besar mangkuk lainnya berisi ikan atau daging."},
  "aloha-poke-ifc-yeouido": {"of": "6402e6d2", "story": "Cabang Aloha Poke ini berada di lantai pertama IFC Mall di Yeouido. HappyCow menyebut mangkuk poke vegannya ditandai dengan jelas, dan menu saat ini melabeli dua di antaranya sebagai vegan (Vegan Paradise dan tempe BBQ vegan) di samping satu mangkuk tahu. Letaknya sekitar delapan menit berjalan kaki dari Stasiun Yeouido."},
  "casa-latina-hongdae": {"of": "327205fc", "story": "Casa Latina adalah restoran Amerika Latin di kawasan Hongdae. Menunya melabeli satu bandera vegan, sepiring hidangan yang digambarkan HappyCow sebagai nasi putih, kacang-kacangan, alpukat, pisang tanduk goreng, dan singkong goreng; bandera vegetarian di sampingnya adalah hidangan yang berbeda. HappyCow menyebut restoran ini berada di lantai tiga, naik lewat tangga logam di luar gedung, dan bahwa reservasi diwajibkan. Letaknya sekitar 20 menit berjalan kaki dari Stasiun Sangsu."},
  "crispy-fresh-seoul-square": {"of": "1a865b75", "story": "Crispy Fresh adalah jaringan salad dan mangkuk biji-bijian; cabang ini berada di lantai dasar Seoul Square, di seberang jalan dari Stasiun Seoul. HappyCow menyebut tempat ini menawarkan mangkuk vegan dengan sayuran panggang, tahu, dan hummus, dan menu saat ini memuat satu mangkuk tahu hummus. Sebagian besar mangkuk lainnya mengandung daging atau ikan."},
  "prathet-thai-yeoksam": {"of": "2b0770a4", "story": "Prathet Thai adalah restoran Thailand kecil lima menit berjalan kaki dari Stasiun Yeoksam. HappyCow mencantumkan hidangan vegan dan hidangan yang bisa disesuaikan: pad thai, tom yum, tumis kangkung, kari hijau, lumpia, nasi goreng, dan salad pepaya. Hanya lumpia yang berlabel vegan di menu; untuk yang lain, mintalah tanpa kecap ikan, udang, atau telur saat memesan."},
  "salad-box-mullae": {"of": "c98307d1", "story": "Salad Box adalah jaringan salad dan poke; cabang ini berada di sebuah menara perkantoran di Mullae-dong. HappyCow menyebut menunya diberi label dengan jelas dan menawarkan mangkuk dengan steik vegan, yang ada di menu saat ini sebagai salah satu pilihan protein. Protein lainnya adalah ayam, daging sapi, bebek, dan salmon, dan sebagian saus salad mungkin tidak vegan, jadi periksalah. Letaknya sekitar 18 menit berjalan kaki dari Stasiun Mullae."},
  "salad-house-jeokseon": {"of": "9a326671", "story": "Salad House adalah kafe salad dan roti lapis di lantai bawah tanah sebuah gedung perkantoran dekat Stasiun Gyeongbokgung. HappyCow menyebut dua salad vegan, alpukat dengan natto dan salad buah musiman dengan kacang arab; hanya salad natto yang ada di menu peta saat ini, yang terakhir diperbarui pada 2024. HappyCow menyebut hidangan vegetarian bisa dibuat vegan atas permintaan."},
  "saladus-eunpyeong": {"of": "4acfd6fd", "story": "Saladus adalah kedai salad dan roti lapis kecil sekitar sepuluh menit berjalan kaki dari Stasiun Yeonsinnae. Menunya melabeli salad falafel panggang oven sebagai vegan, salah satu hidangan yang disebut HappyCow. Salad lain di menu memakai salmon, udang, atau ayam."},
  "slow-cali-yeonnam": {"of": "61dce075", "story": "Slow Cali adalah jaringan mangkuk poke; ini gerai utamanya di Yeonnam, di lantai dua, sepuluh menit berjalan kaki dari Stasiun Hongik University. HappyCow menyebut menunya melabeli mangkuk yang dibuat dengan tahu atau jamur, dan menu saat ini memuat poke tahu oriental dan poke jamur truffle. Periksalah saus dan toppingnya, karena mangkuk lain di jaringan ini memakai telur, ikan, dan daging."},
  "southside-parlor-itaewon": {"of": "bc0f9224", "story": "Southside Parlor adalah restoran Barat dan bar koktail di lantai empat sebuah gedung di Noksapyeong-daero, enam menit berjalan kaki dari Stasiun Noksapyeong. HappyCow menyebut pilihan vegannya diberi label; menu saat ini melabeli satu, yaitu taco chorizo vegan. Makanan lainnya berupa burger, sayap ayam, ikan, dan ayam, dan tempat ini buka pada malam hari."},
  "sun-the-bud-cheongdam": {"of": "aa6f18d1", "story": "Sun the Bud adalah bistro kasual di Cheongdam-dong yang berfokus pada makanan yang lebih ringan. HappyCow menyebut hidangan vegan ditandai di menu, dan menu saat ini menandai dua: salad caesar kale dan mazesoba. Hidangan lainnya mencakup udang, salmon, steik, dan keju. Letaknya lima menit berjalan kaki dari Stasiun Apgujeong Rodeo."},
  "hola-avo-eonju": {"of": "26e599fa", "story": "Hola Avo adalah restoran Meksiko yang berpusat pada alpukat, empat menit dari Stasiun Eonju. Menunya memuat mangkuk burrito dan wrap vegetarian, yang menurut HappyCow berisi kacang arab dan lentil, dan HappyCow menyebut keduanya bisa dibuat vegan jika Anda meminta tanpa produk susu. Sampaikan hal itu saat memesan, karena versi vegetariannya mungkin disajikan dengan keju atau krim asam."},
  "taengmilli-seongnae": {"of": "7fe822b9", "story": "Taengmilli adalah toko roti vegan bebas gluten. Situsnya sendiri menyebutnya toko roti vegan bebas gluten dan melabeli setiap produknya vegan: pound cake, kukis, scone, donat, dan kue utuh, dengan jajaran produk yang berganti-ganti. Toko ini juga menyajikan kopi, teh, ade, dan latte kedelai multigrain. Toko buka Kamis sampai Sabtu, 11:00 hingga 19:00, untuk bawa pulang dan pengambilan pesanan daring. Letaknya 6 menit berjalan kaki dari Stasiun Gangdong-gu Office di Jalur 8."},
  "coconuzm-pildong": {"of": "a61011d0", "story": "Coconuzm membuat gelato dari santan, dan HappyCow mencantumkannya sebagai kedai es krim yang vegan sepenuhnya. Rasanya berganti-ganti, dan kedai ini menjualnya dalam cup atau cone (dua rasa) atau dalam kotak bawa pulang. Ada sedikit tempat duduk di dalam. Letaknya lima menit berjalan kaki dari Stasiun Chungmuro."},
  "bakeshop-pivot-bangbae": {"of": "34aeecf1", "story": "Bakeshop Pivot adalah toko roti vegan kecil yang sebagian besar memanggang dengan tepung beras merah serta memakai susu kedelai dan krim kedelai sebagai pengganti produk susu. Cantumannya di peta menampilkan roti garam beras berisi krim kedelai, batang ubi jalar, dan tart buah; latte dibuat dengan susu kedelai secara bawaan. Daftar menu itu berasal dari tahun 2023, jadi hidangan dan harganya mungkin sudah berubah. Letaknya tiga menit berjalan kaki dari Stasiun Naebang di Jalur 7."},
  "dugong-yeoksam": {"of": "9d9cc556", "story": "Dugong membuat es krim lembut susu kedelai, gelato, dan yoghurt ala Yunani tanpa gula, dan HappyCow mencantumkan setiap produknya sebagai vegan. Cabang ini juga menjual roti lapis vegan dan roti beras bebas gluten. Letaknya sekitar 13 menit berjalan kaki dari Stasiun Gangnam menyusuri Gangnam-daero. Cabang Songdo jaringan ini sudah tutup; cabang ini dan cabang Ewha masih beroperasi."},
  "dugong-ewha": {"of": "f1edea3e", "story": "Cabang Ewha dari Dugong membuat es krim lembut susu kedelai, gelato, dan yoghurt ala Yunani. Pemiliknya menyatakan setiap produknya tanpa gula dan vegan, dan HappyCow mencantumkannya dengan cara yang sama. Letaknya empat menit berjalan kaki dari Stasiun Ewha Womans University, di gedung yang sama dengan Coffee Doga Heritage."},
  "jaiso-anguk": {"of": "809bb6ea", "story": "Jaiso membuat chapssal-tteok, kue beras ketan lembut berisi, dan HappyCow menyebut semua yang dibuatnya vegan kecuali es krimnya. Isiannya antara lain kesemek kering, basil dan tomat, kacang hitam, dan stroberi; menunya juga memuat sikhye, minuman beras manis. Letaknya empat menit berjalan kaki dari Stasiun Anguk, di jalan menanjak menuju Bukchon Hanok Village."},
  "land-of-peace-eunpyeong": {"of": "001a3b54", "story": "Land of Peace adalah kafe roti yang rotinya dibuat dengan tepung beras. Menunya menandai yang vegan: pizza beras ala steik, roti lapis jamur dan basil, campagne kastanye, baguette daun bawang prei, dan ciabatta kentang. HappyCow mencantumkan kafe ini sebagai vegetarian, jadi periksalah label pada produk lainnya. Kafe ini juga menyajikan kopi dan jus segar. Letaknya lima menit berjalan kaki dari Stasiun Saejeol di Jalur 6."},
  "lucyd-unni": {"of": "ba32dff7", "story": "Lucyd adalah kafe brunch dan bistro yang dikelola orang Australia. Menunya memuat shakshouka vegan dari terung, labu, zukini, dan kacang arab dalam saus tomat dengan roti buatan sendiri, dan roti panggang alpukatnya bisa dibuat vegan tanpa telur. Hidangan lainnya mencakup bacon dan telur. HappyCow menyebut susu nabati tersedia untuk kopi. Letaknya delapan menit berjalan kaki dari Stasiun Anguk."},
  "pain-de-echo-seongsu": {"of": "e51306ee", "story": "Pain de Echo memanggang roti sourdough dari tepung organik, air, garam, dan levain, tanpa ragi komersial. Baguette dan roti gandum utuhnya tercantum sebagai dibuat tanpa gula, mentega, telur, atau susu, dan HappyCow juga menyebut campagne-nya vegan. Baguette zaitun-keju tidak vegan. Letaknya sekitar 12 menit berjalan kaki dari Stasiun Seoul Forest."},
  "thanks-oat-yeonnam": {"of": "c57940d7", "story": "Thanks, Oat adalah kafe brunch yang berpusat pada oat, mangkuk yoghurt, dan minuman susu oat. Menunya melabeli dua hidangan sebagai vegan: salad oatmeal dengan kinoa, kacang-kacangan, dan buah kering, serta roti lapis jamur truffle dengan ciabatta. Sebagian besar mangkuk yoghurt dan beberapa roti lapis mengandung produk susu, daging, atau ikan, jadi pesanlah yang berlabel. Letaknya sekitar 22 menit berjalan kaki dari Stasiun Hongik University."},
  "butty-sandwich-seongsu": {"of": "b6d0d85e", "story": "Butty Sandwich House membuat roti lapis ciabatta dan panini di Seongsu. Satu di antaranya berlabel vegan: basil dan tomat. Sisanya berisi ham, telur, ayam, atau keju. Letaknya 12 menit berjalan kaki dari Stasiun Seongsu di Jalur 2."},
  "cafe-manderley-suyu": {"of": "f0da7f81", "story": "Cafe Manderley adalah kedai kopi kecil di Suyu-dong. HappyCow menyebut roti lapis ciabatta alpukatnya vegan dan bahwa minuman bisa dibuat dengan susu kedelai atas permintaan; menu kafe itu sendiri tidak menandai hal ini, jadi pastikan saat memesan. Ciabattanya dipanggang di kedai setiap hari. Letaknya 17 menit berjalan kaki dari Stasiun Suyu di Jalur 4."},
  "hidden-gem-sogong": {"of": "66eea907", "story": "Toko cokelat kecil ini berada di sebuah arkade di lereng antara Myeong-dong dan Namsan. Toko ini menjual cokelat vegan ala rocher, dan HappyCow menyebut toko ini juga punya kukis vegan bebas gluten; cokelat lainnya tidak semuanya vegan. Letaknya 13 menit berjalan kaki dari Stasiun Hoehyeon."},
  "trou8les-sinsa": {"of": "b8a3c2cc", "story": "Trou8les adalah bar smoothie dan jus di Garosu-gil. HappyCow menyebut banyak smoothie-nya vegan; beberapa dibuat dengan susu almon, buah, dan sayuran, sedangkan mangkuknya memakai yoghurt Yunani dari susu sapi dan sebagian minuman memakai madu. Tanyakan smoothie mana yang vegan saat memesan. Letaknya 14 menit berjalan kaki dari Stasiun Sinsa."},
  "ny-lots-o-bagels-apgujeong": {"of": "48fc37ff", "story": "New York Lots O' Bagels memanggang bagel ala New York dengan tepung organik dan waktu pengembangan yang lama. Pemiliknya menyatakan bagelnya tidak mengandung mentega, susu, atau telur; bagel polos dan bagel beras ada di menu saat ini, dan HappyCow juga menyebut bagel gandum utuh, ara, oat, dan kranberi. Roti lapis dan olesannya mencakup telur, bacon, keju, dan salmon, jadi tanyakan soal isiannya. Letaknya delapan menit berjalan kaki dari Stasiun Apgujeong Rodeo."},
  "jaedong-maetdol-sundubu": {"of": "9023c943", "story": "Jaedong Maetdol Sundubu adalah restoran tahu di jalan kecil dekat Bukchon-ro, dua menit dari Stasiun Anguk. Daftar vegetarian Seoul mencantumkan rebusan tahu lembut ala Chodang di tempat ini sebagai vegan. Selebihnya, menunya mencakup rebusan tahu makanan laut, tahu dengan kimchi, panekuk, dan daging babi panggang."},
  "onmaeul-samcheong": {"of": "624cd81b", "story": "Onmaeul adalah restoran tahu di lantai atas sebuah gedung di Samcheong-ro. Daftar vegetarian Seoul mencantumkan hotpot sayuran biji perilla di tempat ini sebagai vegan. Hotpot lain, tumis daging babi, ikan pollack panggang, dan panekuk makanan laut juga ada di menu, jadi tanyakan kaldu apa yang dipakai suatu hidangan. Letaknya sekitar 27 menit berjalan kaki dari Stasiun Anguk."},
  "mokwon-seochon-garak": {"of": "b007cc45", "story": "Mokwon Seochon Garak adalah rumah makan mi kecil sekaligus tempat minum di Seochon, sebelah barat Gyeongbokgung. Daftar vegetarian Seoul mencantumkan empat hidangannya sebagai vegan: nasi gondre, pangsit sayuran gunung, mi lobak muda pedas, dan panekuk kentang. Selebihnya, menunya mencakup makanan laut, ikan kering, dan daging rebus. Letaknya sembilan menit berjalan kaki dari Stasiun Gyeongbokgung."},
  "midang-sundubu-jongno": {"of": "31a27aab", "story": "Midang Sundubu adalah restoran tahu di Cheonggyecheon-ro dekat Jonggak. Daftar vegetarian Seoul mencantumkan rebusan tahu lembut polosnya, 토속순두부, sebagai vegan. Rebusan dan hotpot lainnya memakai kaldu makanan laut, daging babi, atau kedelai fermentasi. Letaknya tujuh menit berjalan kaki dari Stasiun Euljiro 3-ga."},
  "gangnam-gyoja-ttukseom": {"of": "6c8be912", "story": "Cabang Gangnam Gyoja ini, sebuah restoran kalguksu (mi potong pisau), berjarak dua menit dari Stasiun Ttukseom. Daftar vegetarian Seoul mencantumkan mi dingin kuah susu kedelainya sebagai vegan. Restoran menandainya sebagai hidangan musiman, jadi mungkin tidak disajikan sepanjang tahun. Selebihnya, menunya mencakup pangsit, sup ayam, sup tulang sapi, dan daging babi rebus."},
  "okrumong-sinchon": {"of": "5d779f6e", "story": "Okrumong di Sinchon adalah kafe hidangan penutup Korea yang membuat bingsu dengan kacang merah yang dimasak dalam kuali besi. Daftar vegetarian Seoul mencantumkan bubur kacang merah dan bubur labu manisnya sebagai vegan. Menunya juga memuat bingsu, kue beras, roti kacang merah, dan kopi. Letaknya 11 menit berjalan kaki dari Stasiun Sinchon di Jalur Gyeongui–Jungang."},
  "jayeon-bapsang-imun": {"of": "ad53ad45", "story": "Jayeon Bapsang adalah restoran kecil masakan rumahan Korea di belakang Hankuk University of Foreign Studies. Daftar vegetarian Seoul mencantumkan bibimbap saus biji perillanya sebagai vegan. Selebihnya, menunya mencakup steik dada ayam, tumis daging babi, dan sup ayam. Letaknya 15 menit berjalan kaki dari stasiun Jalur 1 universitas tersebut."},
  "kkotjebi-kalguksu-wolgye": {"of": "ef6ecc1a", "story": "Kkotjebi Kalguksu adalah kedai mi langganan warga sekitar di dekat Kwangwoon University. Daftar vegetarian Seoul mencantumkan mi dingin kedelai hitamnya sebagai vegan. Sup mi lainnya memakai kerang, kue ikan, atau ayam. Letaknya sembilan menit berjalan kaki dari Stasiun Kwangwoon Univ."},
  "patdongdong-eunpyeong": {"of": "5ad6e681", "story": "Patdongdong adalah restoran kecil hidangan kacang merah di dekat Eunpyeong Hanok Village. Daftar vegetarian Seoul mencantumkan bubur kacang merah dan sup mi kacang merahnya sebagai vegan. Tempat ini juga menyajikan bibimbap nasi jelai, mi kedelai, bingsu, dan teh tradisional. Letaknya sekitar 35 menit berjalan kaki dari Stasiun Gupabal, jadi naik bus atau taksi untuk bagian terakhir perjalanan lebih mudah."},
  "hongdokkaebi-ewha": {"of": "2f9c2fa7", "story": "Hongdokkaebi 2 adalah kedai minum yang menyajikan jeon (panekuk Korea) di jalan samping dekat Ewha Womans University, empat menit berjalan kaki dari Stasiun Ewha Womans University. Daftar vegetarian Seoul mencantumkan salad jeli biji eknya sebagai vegan. Sebagian besar menunya berupa panekuk dengan ikan, daging, atau makanan laut, serta rebusan dan mi untuk menemani makgeolli."},
  "miltonia-mangwon": {"of": "d2fd68c3", "story": "Miltonia adalah toko roti kecil di jalan samping antara Mangwon dan Hapjeong. Daftar vegetarian Seoul mencantumkan salah satu rotinya, roti gandum hitam kastanye (마롱세이글), sebagai vegan. Roti dan kue lainnya tidak dinilai, jadi tanyakan sebelum memilih yang lain. Letaknya sepuluh menit berjalan kaki dari Stasiun Mangwon."},
  "bonjuk-bibimbap-konkuk": {"of": "095ecac9", "story": "Cabang Bonjuk & Bibimbap Cafe ini, sebuah jaringan bubur nasi dan bibimbap Korea, berjarak satu menit dari Stasiun Konkuk University. Daftar vegetarian Seoul mencantumkan tiga buburnya sebagai vegan: bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijau. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam serta bibimbap daging."},
  "bonjuk-bibimbap-taereung": {"of": "fcaf5762", "story": "Cabang Bonjuk & Bibimbap Cafe ini, sebuah jaringan bubur nasi dan bibimbap Korea, berjarak satu menit dari Stasiun Taereung. Daftar vegetarian Seoul mencantumkan tiga buburnya sebagai vegan: bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijau. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam serta bibimbap daging."},
  "bonjuk-bibimbap-janghanpyeong": {"of": "c73b1da7", "story": "Cabang Bonjuk & Bibimbap Cafe ini, jaringan restoran bubur nasi dan bibimbap Korea, berjarak 2 menit berjalan kaki dari Stasiun Janghanpyeong. Daftar vegetarian Seoul mencantumkan tiga buburnya sebagai vegan: bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijau. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, serta bibimbap daging."},
  "bonjuk-bibimbap-sinchon": {"of": "da893be2", "story": "Cabang Bonjuk & Bibimbap Cafe ini, jaringan restoran bubur nasi dan bibimbap Korea, berjarak 4 menit berjalan kaki dari Stasiun Sinchon. Daftar vegetarian Seoul mencantumkan tiga buburnya sebagai vegan: bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijau. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, serta bibimbap daging."},
  "bonjuk-bibimbap-yeonhui": {"of": "51623ff6", "story": "Cabang Bonjuk & Bibimbap Cafe ini, jaringan restoran bubur nasi dan bibimbap Korea, berjarak 18 menit berjalan kaki dari Stasiun Hongik University. Daftar vegetarian Seoul mencantumkan tiga buburnya sebagai vegan: bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijau. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, serta bibimbap daging."},
  "bonjuk-bibimbap-sungshin": {"of": "30d8331b", "story": "Cabang Bonjuk & Bibimbap Cafe ini, jaringan restoran bubur nasi dan bibimbap Korea, berjarak 6 menit berjalan kaki dari Stasiun Sungshin Women's University. Daftar vegetarian Seoul mencantumkan tiga buburnya sebagai vegan: bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijau. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, serta bibimbap daging."},
  "bonjuk-bibimbap-donam": {"of": "6e0099a5", "story": "Cabang Bonjuk & Bibimbap Cafe ini, jaringan restoran bubur nasi dan bibimbap Korea, berjarak satu menit dari Stasiun Sungshin Women's University. Daftar vegetarian Seoul mencantumkan tiga buburnya sebagai vegan: bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijau. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, serta bibimbap daging."},
  "bonjuk-bibimbap-myeongdong-2": {"of": "b2f66038", "story": "Cabang Bonjuk & Bibimbap Cafe ini, jaringan restoran bubur nasi dan bibimbap Korea, berjarak 5 menit berjalan kaki dari Stasiun Euljiro 1-ga. Daftar vegetarian Seoul mencantumkan tiga buburnya sebagai vegan: bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijau. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, serta bibimbap daging."},
  "memil-jeongwon-homaesil": {"of": "dd34f9d5", "story": "Memil Jeongwon adalah restoran masakan gandum kuda di Homaesil-dong, dekat jalur pendakian Chilbosan di tepi barat Suwon. Daftar menu vegan Kota Suwon mencantumkan sup biji perilla dengan bola-bola kentang (들깨옹심이) sebagai hidangan vegan. Selebihnya, menunya mencakup daging babi rebus dan gurita webfoot pedas, jadi dapurnya bukan dapur vegan. Tidak ada kereta bawah tanah di dekatnya; datanglah dengan bus atau taksi."},
  "gangwon-chik-naengmyeon-maetan": {"of": "d3840755", "story": "Gangwon Chik Naengmyeon menyajikan mi dingin arrowroot di Maetan-dong, tidak jauh berjalan kaki dari Stasiun Maetan-Gwonseon. Daftar menu vegan Kota Suwon mencantumkan mi dingin campur pedasnya (비빔냉면) sebagai hidangan vegan. Dapurnya bukan dapur vegan: sisa menunya mencakup pangsit daging dan rebusan ikan pollack."},
  "meokgo-bori-gwanggyo": {"of": "1bf735dd", "story": "Meokgo Bori adalah restoran Korea kecil di kawasan Wellbeing Town di Gwanggyo, yang berpusat pada nasi jelai. Daftar menu vegan Kota Suwon mencantumkan bibimbap jelainya (보리비빔밥) di antara hidangan vegannya. Menu paketnya memasangkan bibimbap itu dengan gurita webfoot pedas atau sandung lamur, dan daging babi juga ada di menu, jadi pesanlah bibimbapnya saja. Jaraknya jauh untuk berjalan kaki dari kereta bawah tanah; bus atau taksi lebih mudah."},
  "sodamgol-maetan": {"of": "af48043c", "story": "Sodamgol Maetan adalah restoran mi Korea di kawasan permukiman Maetan-dong, yang menyajikan mi potong tangan, bola-bola kentang dalam sup perilla atau sup kacang merah, dan daging babi rebus. Daftar menu vegan Kota Suwon mencantumkan sup mi kacang merahnya (팥칼국수) sebagai hidangan vegan. Sup lain di sini menggunakan kerang, dan daging babi serta pangsit daging ada di menu, jadi pesanlah mi kacang merah dengan menyebut namanya."},
  "sondubuga-ajou": {"of": "c880163a", "story": "Sondubuga adalah restoran tahu di depan Universitas Ajou yang menyajikan rebusan tahu lembut, sup mi kedelai, dan tahu segar. Daftar menu vegan Kota Suwon mencantumkan rebusan tahu lembut biji perillanya (들깨순두부) sebagai hidangan vegan. Beberapa rebusan lain di sini mengandung makanan laut atau daging, jadi pesanlah yang perilla dengan menyebut namanya."},
  "gung-janggijitteok-gwanggyo": {"of": "92d782e7", "story": "Gung Jan-gijitteok Gwanggyo menjual kue beras kukus seukuran sekali suap yang dikembangkan dengan arak beras, kudapan manis tradisional Korea yang dijual per kotak. Daftar menu vegan Kota Suwon mencantumkan Gung jan-gijitteok polosnya sebagai vegan; rasa lain seperti mugwort, jagung, dan jelai juga dijual tetapi tidak disebutkan dalam daftar itu. Tempat ini berupa konter bawa pulang, beberapa menit berjalan kaki dari Stasiun Gwanggyo Jungang."},
  "gung-janggijitteok-suwon-station": {"of": "82362c42", "story": "Cabang Gung Jan-gijitteok ini, dekat Stasiun Suwon, menjual kue beras kukus seukuran sekali suap yang dikembangkan dengan arak beras, dikemas dalam kotak berbagai ukuran. Daftar menu vegan Kota Suwon mencantumkan Gung jan-gijitteok polosnya sebagai vegan; versi mugwort, jagung, dan wijen hitam juga dijual tetapi tidak disebutkan dalam daftar itu."},
  "yellow-forest-gwanggyo": {"of": "c66ca11f", "story": "Yellow Forest adalah kafe hidangan penutup kecil di lantai bawah tanah sebuah mal dekat Taman Danau Gwanggyo yang membuat kue dengan kacang arab sebagai pengganti produk susu dan telur: crumble bar, pound cake, dan sebuah kue dengan krim berbahan dasar kacang arab buatannya sendiri. Daftar menu vegan Kota Suwon mencantumkan seluruh menunya sebagai vegan, dan pemiliknya menggambarkannya sebagai toko hidangan penutup nabati. Latte-nya dibuat dengan susu kedelai tanpa pemanis."},
  "vegan-begins-gwanggyo": {"of": "934511d2", "story": "Vegan Begins adalah kafe roti di gedung Gwanggyo Central Plaza, sepuluh menit berjalan kaki dari Stasiun Gwanggyo Jungang. Daftar menu vegan Kota Suwon mencantumkan pound cake labu manis dan pound cake ubi jalar kenarinya sebagai vegan, dan menunya menandai lebih banyak item lagi sebagai vegan, dari kukis hingga roti garam. Tidak semuanya berlabel: caffè latte, scone polos, dan pound cake cokelatnya tidak, dan susu kedelai atau susu oat ditawarkan untuk minuman."},
  "bakery-ilsang-songjuk": {"of": "12653989", "story": "Bakery Ilsang adalah toko roti kecil di lingkungan Songjuk-dong, Suwon utara, yang terutama menjual roti tawar, termasuk yang dari gandum utuh. Daftar menu vegan Kota Suwon mencantumkan roti tawar gandum utuh kenari-beri di antara roti vegannya; roti lain tidak disebutkan, jadi tanyakan mana yang vegan. Letaknya jauh dari kereta bawah tanah; datanglah dengan bus."},
  "bonjuk-seolleung": {"of": "b2e92e97", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea. Daftar restoran vegetarian Kota Seoul menandai bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijaunya sebagai vegan. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, jadi pesanlah bubur yang ditandai itu dengan menyebut namanya. Tempat ini berjarak 4 menit berjalan kaki dari Stasiun Seolleung."},
  "bonjuk-poi": {"of": "92ea2c3d", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea. Daftar restoran vegetarian Kota Seoul menandai bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijaunya sebagai vegan. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, jadi pesanlah bubur yang ditandai itu dengan menyebut namanya. Tempat ini berjarak 17 menit berjalan kaki dari Stasiun Yangjae Citizen's Forest."},
  "bonjuk-gangnam-station": {"of": "e52ad9b5", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea. Daftar restoran vegetarian Kota Seoul menandai bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijaunya sebagai vegan. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, jadi pesanlah bubur yang ditandai itu dengan menyebut namanya. Tempat ini berjarak 5 menit berjalan kaki dari Stasiun Gangnam."},
  "bonjuk-jamsil-lake-palace": {"of": "3d18a18e", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea. Daftar restoran vegetarian Kota Seoul menandai bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijaunya sebagai vegan. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, jadi pesanlah bubur yang ditandai itu dengan menyebut namanya. Tempat ini berjarak 11 menit berjalan kaki dari Stasiun Samjeon."},
  "bonjuk-gubeundari-station": {"of": "11b7ea59", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea. Daftar restoran vegetarian Kota Seoul menandai bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijaunya sebagai vegan. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, jadi pesanlah bubur yang ditandai itu dengan menyebut namanya. Tempat ini berjarak 4 menit berjalan kaki dari Stasiun Gubeundari."},
  "bonjuk-dunchon-vhs": {"of": "22c4e84a", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea. Daftar restoran vegetarian Kota Seoul menandai bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijaunya sebagai vegan. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, jadi pesanlah bubur yang ditandai itu dengan menyebut namanya. Tempat ini berjarak 8 menit berjalan kaki dari Stasiun VHS Medical Center."},
  "bonjuk-yeouido-station": {"of": "4a0519b3", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea. Daftar restoran vegetarian Kota Seoul menandai bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijaunya sebagai vegan. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, jadi pesanlah bubur yang ditandai itu dengan menyebut namanya. Tempat ini berjarak 4 menit berjalan kaki dari Stasiun Yeouido."},
  "bonjuk-siheung-sageori": {"of": "f4ea73b1", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea. Daftar restoran vegetarian Kota Seoul menandai bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijaunya sebagai vegan. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, jadi pesanlah bubur yang ditandai itu dengan menyebut namanya. Tempat ini berjarak 14 menit berjalan kaki dari Stasiun Geumcheon-gu Office."},
  "bonjuk-gasan-terra-tower": {"of": "2e14a30c", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea. Daftar restoran vegetarian Kota Seoul menandai bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijaunya sebagai vegan. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, jadi pesanlah bubur yang ditandai itu dengan menyebut namanya. Tempat ini berjarak 19 menit berjalan kaki dari Stasiun Gasan Digital Complex."},
  "bonjuk-doksan-station": {"of": "217a1141", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea. Daftar restoran vegetarian Kota Seoul menandai bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijaunya sebagai vegan. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, jadi pesanlah bubur yang ditandai itu dengan menyebut namanya. Tempat ini berjarak 5 menit berjalan kaki dari Stasiun Doksan."},
  "bonjuk-noryangjin": {"of": "6917772d", "story": "Ini adalah cabang Bonjuk, jaringan restoran bubur nasi Korea. Daftar restoran vegetarian Kota Seoul menandai bubur kacang merah dengan bola-bola beras, bubur labu manis, dan bubur kacang hijaunya sebagai vegan. Sebagian besar menunya berupa bubur abalon, daging sapi, makanan laut, atau ayam, jadi pesanlah bubur yang ditandai itu dengan menyebut namanya. Tempat ini berjarak 9 menit berjalan kaki dari Stasiun Noryangjin."},
  "robot-gimbap-express-terminal": {"of": "841f52b0", "story": "Robot Gimbap adalah kedai gimbap (nasi gulung rumput laut Korea) di Express Bus Terminal di Banpo, di lantai dasar di 194 Sinbanpo-ro. Daftar restoran vegetarian Kota Seoul menandai forest gimbap-nya sebagai vegan. Sebagian besar gulungan lainnya mengandung tuna, ham, ikan teri, daging, atau keju, jadi mintalah forest gimbap dengan menyebut namanya. Tempat ini berjarak 8 menit berjalan kaki dari Stasiun Express Bus Terminal."},
  "gaeseong-jip-nonhyeon": {"of": "5824e0e6", "story": "Gaeseong-jip adalah restoran barbeku Korea di sebuah jalan kecil dekat Stasiun Sinnonhyeon, yang memanggang daging babi dan daging sapi. Daftar restoran vegetarian Kota Seoul menandai satu hidangan sebagai vegan: nurungji, bubur lembut dari kerak nasi yang ada di menu makan siang. Semua hidangan lain di menu berupa daging, ikan, atau rebusan, jadi pesanlah nurungji dengan menyebut namanya. Tempat ini berjarak 4 menit berjalan kaki dari Stasiun Sinnonhyeon."},
  "the-dream-yeoksam": {"of": "be75d15f", "story": "The Dream adalah restoran Korea di kawasan perkantoran Yeoksam yang mengkhususkan diri pada rebusan kimchi dan kimchi yang dimasak perlahan. Daftar restoran vegetarian Kota Seoul menandai satu hidangan sebagai vegan: bibimbap dengan gangdoenjang, saus pasta kedelai yang kental. Banyak hidangan di menunya berupa daging babi atau daging sapi, jadi pesanlah bibimbap itu dengan menyebut namanya. Tempat ini berjarak 10 menit berjalan kaki dari Stasiun Yeoksam."},
  "daedune-sundubu-gasan": {"of": "c569e58f", "story": "Daedune Sundubu membuat tahu lembut dan hidangan tahu di lantai bawah tanah sebuah gedung perkantoran di Gasan. Daftar restoran vegetarian Kota Seoul menandai dua hidangan sebagai vegan: tahu lembut putih polos dan tahu balok yang baru dibuat. Hidangan lainnya mencakup rebusan tahu lembut dengan sandung lamur sapi, daging babi, dan pangsit daging, jadi mintalah yang putih. Tempat ini berjarak 9 menit berjalan kaki dari Stasiun Gasan Digital Complex."},
  "daon-memil-makguksu-sinjeong": {"of": "64629d80", "story": "Daon Memil Makguksu menyajikan mi gandum kuda dan dakhanmari, hotpot ayam utuh, di dekat Stasiun Mokdong. Daftar restoran vegetarian Kota Seoul menandai bibim makguksu-nya, mi gandum kuda yang diaduk dengan saus pedas, sebagai vegan. Mi berkuah dan hotpotnya tidak ditandai, jadi pesanlah mi bibim dengan menyebut namanya. Tempat ini berjarak 3 menit berjalan kaki dari Stasiun Mokdong."},
  "nae-yeoja-seolleung": {"of": "d147cd9c", "story": "Nae Yeoja-reul Butakhae, Seolleung, adalah kedai salad dan nasi mangkuk di lantai bawah tanah sebuah menara perkantoran di Teheran-ro dekat Stasiun Seolleung. Daftar restoran vegetarian Kota Seoul menandai salad jamurnya sebagai vegan. Salad dan nasi mangkuk lainnya disajikan dengan ayam, salmon, daging babi, atau daging sapi. Tempat ini berjarak 5 menit berjalan kaki dari Stasiun Seolleung."},
  "cherry-garden-insadong": {"of": "89069968", "story": "Cherry Garden Insadong adalah restoran Korea kecil di lantai tiga sebuah gedung di Insadong-gil. Menunya melabeli samgyetang, dakgalbi, dan bulgoginya sebagai halal. Direktori halal Zabihah mencantumkannya sebagai halal sepenuhnya dan tidak menjual alkohol, berdasarkan jaminan staf, serta menyebut adanya fasilitas salat. Zabihah menyatakan makanannya bersertifikat halal, tetapi tidak ada sertifikat yang kami lihat dan tidak ada lembaga sertifikasi yang disebutkan.", "esg": "Hidangan Korea halal, termasuk samgyetang, di tengah Insadong"},
  "jyoti-chungmuro": {"of": "cfe594f9", "story": "Jyoti Indian Restaurant Chungmuro adalah restoran India di Seoae-ro dekat Stasiun Chungmuro, dengan kari daging domba dan kari udang, biryani, serta jajanan kaki lima seperti pani puri. Direktori halal Zabihah mencantumkannya sebagai halal sepenuhnya dan tidak menjual alkohol, serta menyebut pemiliknya Muslim. Zabihah juga mencatat adanya sertifikat dalam arsipnya, tetapi tidak ada sertifikat yang kami lihat dan tidak ada lembaga sertifikasi yang disebutkan."},
  "jyoti-sinchon": {"of": "f9896209", "story": "Jyoti Indian Restaurant Sinchon adalah restoran India di lantai tiga tidak jauh dari Stasiun Sinchon, yang menyajikan kari seperti chicken butter masala dan palak paneer, samosa, dan paket makan siang. Direktori halal Zabihah mencantumkannya sebagai halal sepenuhnya dan tidak menjual alkohol, serta menyebut pemiliknya Muslim. Zabihah juga mencatat adanya sertifikat dalam arsipnya, tetapi tidak ada sertifikat yang kami lihat dan tidak ada lembaga sertifikasi yang disebutkan."},
  "jayeondo-sogeumppang-seongsu": {"of": "404503bc", "story": "Jayeondo Sogeumppang Seongsu adalah toko roti garam khusus bawa pulang di Yeonmujang-gil yang hanya menjual satu hal: roti garam, dalam set berisi empat. Anda memesan di mesin pemesanan mandiri dan mengambil pesanan di konter. Zabihah, sebuah direktori restoran halal, mencantumkannya sebagai halal sepenuhnya dan tidak menjual alkohol, berdasarkan jaminan stafnya. Tidak ada sertifikat yang kami lihat."},
  "jayeondo-sogeumppang-yeonnam": {"of": "999c4797", "story": "Jayeondo Sogeumppang Yeonnam adalah toko roti garam yang tidak jauh berjalan kaki dari Stasiun Hongik University, menjual roti garam dalam set berisi empat melalui mesin pemesanan mandiri. Zabihah, sebuah direktori restoran halal, mencantumkannya sebagai halal sepenuhnya dan tidak menjual alkohol, berdasarkan jaminan stafnya. Tidak ada sertifikat yang kami lihat."},
  "jayeondo-sogeumppang-dosan": {"of": "b4057f4e", "story": "Jayeondo Sogeumppang Dosan adalah toko roti garam khusus bawa pulang di jalan-jalan kecil Apgujeong Rodeo, yang menjual roti garam hangat dalam set berisi empat. Zabihah, sebuah direktori restoran halal, mencantumkannya sebagai halal sepenuhnya dan tidak menjual alkohol, berdasarkan jaminan stafnya. Tidak ada sertifikat yang kami lihat."},
  "adnan-kebab-hoehyeon": {"of": "2f77ceb2", "story": "Adnan Kebab adalah konter bawa pulang kecil di ujung Toegye-ro yang mengarah ke Pasar Namdaemun, beberapa menit berjalan kaki dari Stasiun Hoehyeon, yang menjual kebab daging domba dan kebab ayam, kebab nasi, dan falafel. Direktori halal Zabihah mencantumkannya sebagai halal sepenuhnya dan tidak menjual alkohol, berdasarkan jaminan staf, dan mencatat adanya sertifikat dalam arsipnya, tetapi tidak ada sertifikat yang kami lihat dan tidak ada lembaga sertifikasi yang disebutkan."},
  "kkotbap-epida-insadong": {"of": "fa7e676b", "story": "Kkotbap Epida Insadong memasak hidangan Korea dari bahan organik dan bahan hasil pertanian alami, yang dibumbui dengan ganjang dan doenjang tradisional. Situsnya sendiri menyatakan bahwa di kedua restorannya nasi, sup, banchan, dan setiap hidangan pendamping dibuat vegan, sedangkan daging dan ikan ditawarkan sebagai hidangan utama terpisah. Tamu vegan dapat memesan paket vegan berisi empat atau delapan hidangan yang diakhiri dengan bibimbap namul, atau chaegaejang, sup pedas bergaya yukgaejang yang dibuat tanpa daging. Beberapa hidangan di menu menggunakan telur, daging sapi, daging babi, atau makanan laut, jadi sebutkan paket vegan saat Anda memesan. Tempat ini berjarak empat menit berjalan kaki dari Stasiun Anguk; cabang saudaranya di Bukchon juga ada di peta ini.", "esg": "Beras Korea organik hasil pertanian alami serta kecap asin dan doenjang yang difermentasi secara tradisional."},
  "jandisok-sangdo": {"of": "cd442e01", "story": "Pemilik Imagine You're in the Grass, sebuah kafe di lantai dua, menyebut setiap item di menunya vegan. Menu yang tercantum pendek: brownie, roti panggang pisang, kopi garam, dan americano. Rombongan dibatasi empat orang, anjing boleh masuk dengan sertifikat vaksinasi rabies, dan tempat ini tidak menerima uang tunai. Tempat ini berjarak empat menit berjalan kaki dari Stasiun Sangdo di Jalur 7."},
  "cafe-geobugi-bangbae": {"of": "fda75bc3", "story": "Cafe Geobugi (\"kura-kura\") menggambarkan dirinya sebagai toko hidangan penutup vegan dan menyatakan setiap bahan yang digunakannya nabati. Menunya mencakup kue, tart, pai, dan bingsu musiman: antara lain kue wortel, kue mugwort dan wijen hitam, pai kenari, dan bingsu kacang merah. Beberapa kue bersifat musiman. Tempat ini berjarak sekitar sembilan menit berjalan kaki dari Stasiun Sadang."},
  "vegan-daum-gajwa": {"of": "42be4912", "story": "Vegan Daum Bakery membuat hidangan penutup tanpa tepung terigu, produk susu, atau telur, dan menyebutnya vegan. Menunya mencantumkan kue cokelat pisang dan kukis seperti kukis s'more dengan marshmallow vegan; kukis bluberinya menggunakan keju susu kedelai buatan sendiri. Itemnya berganti mengikuti musim. Tempat ini berjarak empat menit berjalan kaki dari Stasiun Gajwa."},
  "forfour-bread-seogyo": {"of": "ba134410", "story": "For Four Bread menyebut dirinya toko roti vegan yang membuat roti \"untuk manusia, hewan, bumi, dan hari esok\". Tempat ini membuat roti tawar, ciabatta, dan campagne dari tepung beras Korea, ditambah pound cake, kukis, dan madeleine bebas gluten. Sejak September 2026 toko ini hanya buka tiga hari seminggu dan mengumumkan hari bukanya di Instagram pada awal setiap bulan, jadi periksa dahulu sebelum Anda pergi. Tempat ini berjarak sekitar sebelas menit berjalan kaki dari Stasiun Hapjeong.", "esg": "Roti yang dibuat dari tepung beras hasil tanam Korea."},
  "modu-garden-gimpo": {"of": "9d63cddc", "story": "Modu-ui Jeongwon (\"taman semua orang\") menyebut dirinya kafe hidangan penutup yang murni nabati, dan pemiliknya menyatakan setiap item menu dibuat dari bahan nabati. Kuenya antara lain kue bertabur buah dengan krim oat serta kue cokelat, grapefruit, mugwort, dan matcha; kue utuh dapat dipesan dua hari sebelumnya. Tempat ini berjarak sekitar lima belas menit berjalan kaki dari Stasiun Masan di Gimpo Goldline."},
  "chorokbbang-pyeongtaek-godeok": {"of": "0cac695f", "story": "Chorokbbang Pyeongtaek Godeok menyatakan dirinya sebagai toko roti vegan yang tidak menggunakan telur, mentega, susu, atau bahan hewani lainnya. Tempat ini membuat roti tawar tepung beras dengan rasa seperti mugwort dengan kacang merah, wijen hitam, buah ara, dan kastanye kayu manis. Cabang ini dibuka pada akhir 2025 di kota baru Godeok; stasiun kereta terdekat, Pyeongtaek Jije, berjarak hampir 5 km, jadi datanglah dengan bus atau taksi."},
  "dampuk-bakery-wirye": {"of": "ebb96af1", "story": "Dampuk Bakery menggambarkan dirinya sebagai toko roti vegan dengan ragi alami. Tempat ini membuat roti tawar beras, termasuk roti organik tanpa gula dan tanpa garam, yang juga dijualnya secara daring. Letaknya di sebuah pusat pertokoan di kota baru Wirye, sekitar 37 menit berjalan kaki dari Stasiun Namwirye, jadi bus adalah cara yang lebih mudah untuk ke sana."},
  "wonder-chips-gaebong": {"of": "3b94fed7", "story": "Wonder Chips menyebut dirinya spesialis hidangan penutup vegan dan bebas gluten. Tempat ini menjual kukis tebal, financier, dan kue panggang lainnya, banyak di antaranya secara daring. Tempat ini berjarak sekitar 17 menit berjalan kaki dari Stasiun Oryu-dong di Jalur 1."},
  "iroun-jegwa-jayang": {"of": "4d353250", "story": "Iroun Jegwa menyatakan bahwa tempat ini membuat kukis dan hidangan penutup vegan, menggunakan mentega vegan fermentasi buatannya sendiri, marshmallow vegan, dan minyak kelapa organik. Andalannya adalah serangkaian kukis kenyal bergaya levain berisi marshmallow vegan, dalam rasa jagung, labu, mugwort, dan cokelat; scone dan kotak hadiah juga dijual. Tempat ini berjarak tujuh menit berjalan kaki dari Stasiun Jayang, dekat Taman Sungai Han Ttukseom.", "esg": "Kotak hadiah dikemas dalam kantong dan kertas yang dapat terurai secara hayati, menurut menu toko tersebut."},
  "second-breeze-bucheon": {"of": "e20c5ead", "story": "Second Breeze menggambarkan dirinya sebagai kafe vegan di Bucheon yang memanggang tanpa susu, mentega, atau telur. Tempat ini menjual scone dan hidangan penutup vegan lainnya, termasuk sandwich buah, beserta kopi. Anjing boleh masuk. Tempat ini berjarak sekitar tiga belas menit berjalan kaki dari Stasiun Sang-dong di Jalur 7."},
  "bdro-guui": {"of": "d17ce58c", "story": "BDRO menggambarkan dirinya sebagai kafe vegan. Selain kopi dan teh, tempat ini menyajikan pasta seharga 8.000–9.000 won, antara lain pasta pakis (gosari), basil, mala, cabai, dan truffle. Tempat ini berjarak enam menit berjalan kaki dari Stasiun Guui di Jalur 2; pesanan terakhir pukul 21:00."},
  "pini-cake-house-bongcheon": {"of": "ffa0775d", "story": "Pini Cake House menggambarkan dirinya sebagai kafe kue vegan. Tempat ini membuat kue kecil bertulisan sesuai pesanan, termasuk kue seukuran kotak bekal, dan menyajikan kopi, teh, dan soda krim. Tempat ini berjarak sekitar sepuluh menit berjalan kaki dari Stasiun Seoul National University di Jalur 2, dekat Sharosu-gil."},
  "dolmen-bakery-ganghwa": {"of": "fb8f39aa", "story": "Dolmen Bakery menggambarkan dirinya sebagai kafe roti vegan, terletak di pesisir timur Pulau Ganghwa menghadap selat Yeomha. Tempat ini membuat roti vegan dan menyajikan kopi, teh herbal, dan ade. Letaknya jauh di luar kota, sekitar satu jam berjalan kaki dari Ganghwa Bus Terminal, jadi datanglah dengan mobil atau taksi; tempat ini tutup pada hari Jumat."},
  "youngi-jegwa-uijeongbu": {"of": "af8edbe0", "story": "Youngi Jegwa menggambarkan dirinya sebagai toko roti vegan. Tempat ini membuat kukis crumble tepung beras dan roti garam beras vegan, serta menjual sebagian besar produknya lewat kiriman paket dan di acara pop-up, jadi periksa halaman Kakao atau Instagramnya sebelum berkunjung; jam bukanya tidak dipublikasikan. Tempat ini berjarak sekitar 40 menit berjalan kaki dari Stasiun Tapseok, jadi naiklah bus atau taksi."},
  "geongang-bbangjip-yongin": {"of": "6cdbb923", "story": "Geongang-han Bbangjip adalah toko roti yang menyebut dirinya tempat untuk roti vegan sehat yang dibuat dari beras Korea. Minumannya dibuat dengan susu kedelai atau susu almon. Tempat ini berjarak empat menit berjalan kaki dari Stasiun Samga di Yongin Everline, dekat Balai Kota Yongin.", "esg": "Roti yang dibuat dari beras hasil tanam Korea."},
  "cafe-uroka-gyodae": {"of": "d3bc2b80", "story": "Cafe Uroka menyebut dirinya toko roti vegan bebas gluten yang memanggang dengan tepung beras, dan melabeli kukis serta financier-nya vegan. Minuman kopinya menggunakan susu sapi kecuali Anda meminta susu oat, jadi pesanlah susu nabati untuk minuman Anda. Tempat ini berjarak lima menit berjalan kaki dari Stasiun Gyodae (Seoul National University of Education)."},
  "neulimi-gwajajeom-macheon": {"of": "f5b789dc", "story": "Neulimi Gwajajeom menyebut dirinya kafe hidangan penutup vegan dan bebas gluten. Brownie-nya dideskripsikan sebagai vegan dan kukis levain-nya dibuat dengan mentega vegan buatan sendiri; tempat ini juga membuat kudapan berbahan dasar kacang arab dan madeleine beras. Daftar minumannya memuat latte biasa dan latte oat, jadi mintalah yang oat. Tempat ini berjarak enam menit berjalan kaki dari Stasiun Macheon di Jalur 5."},
  "pyeonghyeong-mangwon": {"of": "bc15e1c7", "story": "Pyeonghyeong adalah kedai kopi hand-drip kecil yang pemiliknya menyatakan semua minuman dan hidangan penutupnya vegan dan bebas gluten. Hidangan penutupnya antara lain pound cake mugwort, kukis, dan yoghurt kedelai dengan granola biji-bijian Korea. Tempat ini juga menjual quiche, yang tidak tercakup dalam pernyataan pemiliknya, jadi tanyakan soal itu. Hewan peliharaan boleh masuk. Tempat ini berjarak sekitar tiga belas menit berjalan kaki dari Stasiun Mangwon."},
  "immu-bake-shop-hapjeong": {"of": "8e2e2d18", "story": "Immu Bake Shop menyatakan mengkhususkan diri pada hidangan penutup vegan dan bebas gluten, termasuk kue utuh dan mud cake cokelat. Daftar minumannya memuat teh susu yang tidak menyebutkan susu apa yang digunakan, jadi tanyakan. Tokonya berada di lantai dua, sekitar delapan menit berjalan kaki dari Stasiun Hapjeong, dan minggu ini buka Kamis sampai Minggu."},
  "goodness-club-yongsan": {"of": "29e7aa82", "story": "Goodness Club menyebut dirinya toko roti bebas gluten berbasis vegan: hidangan penutupnya vegan, misalnya bottle cake dari bolu oat dan frosting cokelat hitam kelapa. Tempat ini juga menjual sandwich focaccia, yang tidak dideskripsikan sebagai vegan; seorang pengulas baru-baru ini menyebut burrata, jadi tanyakan. Letaknya di lantai bawah tanah dekat Pasar Sinheung, sekitar 25 menit berjalan kaki dari Stasiun Noksapyeong."},
  "haedeun-bueok-gwangmyeong": {"of": "ba0f8cd7", "story": "Haedeun Bueok menggambarkan dirinya sebagai restoran untuk vegan maupun nonvegan, dekat IKEA dan Costco di Gwangmyeong. Tiga hidangan ditandai vegan: salad dengan galbi nabati yang dimarinasi kecap asin, pasta krim kacang mete dan bayam, serta pilaf dengan daging kedelai dan yuba. Selebihnya, menunya mencakup bacon, sosis, steik, udang, dan telur, jadi pesanlah dari hidangan yang ditandai. Tempat ini berjarak sekitar 17 menit berjalan kaki dari Stasiun Gwangmyeong KTX."},
  "kikicoco-mokdong": {"of": "197a56ff", "story": "Kikicoco menyebut dirinya restoran pescatarian dan vegan, yang memasak dengan sayuran dari Pasar Mok-sarang di dekatnya. Hidangan vegannya antara lain galbi daging kedelai yang dipanggang di atas arang dengan jamur, spageti dengan bola daging nabati, dan pasta pasar bulanan (pada bulan September berupa pasta shiitake krim kedelai). Hidangan gurita dan udang juga disajikan. Tempat ini berjarak sekitar enam belas menit berjalan kaki dari Stasiun Yeomchang di Jalur 9; ada jam istirahat pukul 15:00–17:00.", "esg": "Memasak dengan sayuran yang dibeli di Pasar Mok-sarang di sebelahnya."},
  "boot-bread-eungam": {"of": "1b147a37", "story": "Boot Bread menyatakan bahwa tempat ini memanggang roti vegan yang sehat, menggunakan tepung beras Korea. Ciabatta beras kentang dan roti garam berasnya dilabeli vegan, dibuat tanpa bahan hewani, telur, atau produk susu; roti kayu manis dan roti cokelatnya tidak dilabeli. Toko ini tanpa staf dan, menurut Kakao, buka 24 jam kecuali hari Minggu. Tempat ini berjarak sekitar sepuluh menit berjalan kaki dari Stasiun Eungam di Jalur 6."},
  "supumdang-gwangmyeong": {"of": "af982f79", "story": "Supumdang adalah rumah teh yang telah menyajikan teh tradisional Korea seperti jujube, omija, dan jahe selama lebih dari satu dekade, serta membuat roti dan kudapan manis dari tepung beras. Pemiliknya melabeli sebagian di antaranya vegan: roti tawar beras rasa labu manis, angkak, mugwort, dan campuran 'Gureumsan', serta pai ketan beras hitam yang dibuat dengan susu kedelai. Roti dan kudapan manis lainnya mengandung susu, mentega, atau keju, jadi pilihlah yang berlabel. Tempat ini berjarak sekitar 24 menit berjalan kaki dari Stasiun Geumcheon-gu Office."},
  "little-gangster-hyochang": {"of": "c4fbdcfe", "story": "Little Gangster menyebut dirinya dapur vegan kreatif dan memasak tanpa lima sayuran berbau tajam dalam masakan Buddha (bawang putih, bawang bombai, dan kerabatnya) serta tanpa gluten. Menunya berganti setiap bulan; hidangan terbarunya antara lain rebusan kimchi yang disajikan dengan tahu goreng buatan sendiri dan nasi beras cokelat, aglio e olio yang diaduk dengan namul Korea, dan gazpacho buah. Tempat ini berjarak sekitar tujuh menit berjalan kaki dari pintu keluar 6 Stasiun Hyochang Park dan tutup pada hari Senin dan Selasa.", "esg": "Menu musiman yang sepenuhnya nabati dan berpusat pada sayuran Korea"},
  "cure-kitchen-seul-jeonju": {"of": "680c572a", "story": "Cure Kitchen Seul menyajikan satu paket menu, yang oleh pemiliknya dideskripsikan di Kakao Map sebagai '100% nabati', dikembangkan oleh seorang ahli gizi hanya dari bahan nabati. Tempat ini menerima satu rombongan per hari dan hanya melayani dengan reservasi, melalui kanal Kakao-nya atau pesan teks, serta mengganti paketnya mengikuti musim (menu musim gugur 2026 berlaku dari 1 September sampai 30 November). Harga paketnya 120.000 won per orang menurut cantuman tersebut. Pesanlah tempat sebelum Anda berangkat; tidak ada layanan tanpa reservasi.", "esg": "Paket musiman yang disusun dari bahan nabati yang ditanam di Jeonbuk, sebagaimana dideskripsikan oleh pengelolanya."},
  "lans-kitchen-aewol": {"of": "96f482a5", "story": "LAN's Kitchen menyebut dirinya bistro vegan. Menunya sebagian besar masakan Vietnam — pho, mi tom yum, dan banh mi dengan kotlet kedelai — di samping hidangan Korea-Tionghoa seperti jjamppong dan jajangmyeon, serta hidangan yang dinamai menurut daging (bulgogi, galbi, tumisan ala daging babi) yang dicantumkan pengelolanya sebagai versi vegan. Tempat ini dibuka kembali di alamatnya yang sekarang di Haga-ro pada Juli 2026 setelah pindah dari Hagwi yang berdekatan; peta dan ulasan lama mungkin masih menampilkan alamat sebelumnya."},
  "kubikubi-mokpo": {"of": "69076283", "story": "Vegan Bakery Kubi Kubi menyebut dirinya sebagai toko roti di Mokpo yang membuat hidangan penutup vegan 100% nabati. Toko ini juga mengadakan kelas membuat kue vegan (kelas satu hari seharga 60.000 won pada cantumannya)."},
  "eupnae-bakery-jinyeong": {"of": "a6c7ef9d", "story": "Eupnae Bakery menyebut dirinya sebagai toko roti khusus vegan. Roti yang dicantumkannya adalah roti tangzhong dari tepung beras yang ditandai vegan. Pemiliknya meminta pelanggan memesan terlebih dahulu dan menutup toko lebih awal bila roti habis terjual."},
  "mion-bakery-suncheon": {"of": "eda6f8af", "story": "Mion Bakery membuat roti dengan tepung beras dan, menurut penuturan pemiliknya, sama sekali tidak memakai susu, telur, dan mentega, hanya bahan nabati. Ragam produknya mencakup roti garam beras yang dibuat dengan mentega vegan buatan sendiri, roti tawar beras, dan madeleine. Toko ini meraih penghargaan harapan pada kontes kuliner Suncheon Misik Daecheop ke-11 pada 2026, menurut laporan pemiliknya. Toko tutup bila roti hari itu habis terjual."},
  "biroso-hyeonmi-changwon": {"of": "c0c75fd8", "story": "Biroso Hyeonmi membuat roti dan camilan vegan bebas gluten dari beras cokelat organik, menurut penuturan pemiliknya. Toko ini hanya menjual lewat pesanan di muka untuk diambil sendiri atau dikirim lewat paket: cantumannya menyebut pelanggan yang datang tanpa menghubungi toko lebih dulu tidak dapat membeli. Telepon atau kirim pesan sebelum datang.", "esg": "Roti dibuat dari beras cokelat organik."},
  "neugeutan-ssalppang-gurye": {"of": "1977c936", "story": "Neugeutan Ssalppang ('roti beras yang santai') membuat roti vegan yang kenyal dari tepung beras organik, menurut penuturan pemiliknya. Menunya mencakup roti tawar beras dan beras cokelat, roti isi kacang merah yang dibuat dengan kacang merah Gurye, serta kukis beras dengan keping cokelat vegan.", "esg": "Tepung beras organik dan kacang merah lokal Gurye, sebagaimana dicantumkan pemiliknya."},
  "ssalssal-hadang-beomeo": {"of": "f3e449c4", "story": "Ssalssal Hadang menamai dirinya toko roti vegan. Pemiliknya menyatakan toko ini menggiling beras organik setiap hari untuk membuat rotinya, termasuk roti tawar beras bebas gluten dalam beberapa rasa."},
  "simsim-bread-chilgok": {"of": "119dfab4", "story": "Simsim Bread menyebut dirinya sebagai toko roti dan kafe vegan, yang beroperasi sejak 2020. Jam buka dan ragam produknya tidak dipublikasikan di Kakao Map; periksa Instagram-nya sebelum berkunjung."},
  "hooa-bbanggeut-ulsan": {"of": "e72d8025", "story": "Hooa Bbanggeut menyebut dirinya di Instagram sebagai toko roti vegan di Ulsan yang membuat roti beras. Rotinya mencakup roti tawar dan roti bulat rasa kastanye, gandum utuh, dan pasta kacang polong, dan minuman susunya dibuat dengan susu kedelai."},
  "the-soonsu-bread-daegu": {"of": "58f74ccf", "story": "The Soonsu Bread menyebut dirinya sebagai toko roti vegan di Daegu. Latte dan teh susunya dicantumkan sebagai versi vegan."},
  "heeso-jeonpo": {"of": "6a6df3b9", "story": "Heeso menyebut dirinya sebagai toko roti vegan di Jeonpo yang juga mengadakan kelas membuat roti, termasuk kursus bagi calon pemilik toko roti. Ragam produk dan jam bukanya tidak dipublikasikan di Kakao Map; periksa Instagram-nya sebelum berkunjung."},
  "classy-vegan-gwangju": {"of": "0e224676", "story": "Classy Vegan menyebut dirinya sebagai toko roti vegan di Gwangju. Hari bukanya tidak dipublikasikan di Kakao Map; periksa Instagram-nya sebelum berkunjung."},
  "soon-bake-daegu": {"of": "fff59de6", "story": "Soon Bake menyebut dirinya sebagai toko roti vegan di Daegu. Roti yang dicantumkannya adalah roti beras kacang merah; jam buka tokonya tidak dipublikasikan di Kakao Map, jadi periksa dahulu sebelum berkunjung."},
  "milhanjum-oncheoncheon": {"of": "50bf7912", "story": "Milhanjum menyebut dirinya sebagai toko roti vegan di Busan. Toko ini terletak di jalan kafe di sepanjang sungai Oncheoncheon dan membuat roti tawar beras, cinnamon roll, dan ciabatta mugwort. Jam bukanya tidak dipublikasikan di Kakao Map."},
  "omiljomil-uiseong": {"of": "740aa076", "story": "Omiljomil menyebut dirinya sebagai toko roti vegan. Toko ini berada di lantai dua gedung pasar pangan lokal Uiseong dan menyajikan teh yang dibuat dari buah dan akar-akaran Korea."},
  "day-vegan-daegu": {"of": "ba789960", "story": "Day Vegan menyebut dirinya sebagai toko roti vegan di Daegu, bebas gluten dan vegan. Menunya di Kakao Map mencantumkan roti krim vegan."},
  "ondam-jegwa-changwon": {"of": "03ef93c0", "story": "Ondam Jegwa menyebut dirinya sebagai toko roti vegan yang membuat roti beras dan kukis vegan. Menunya mencakup roti tawar beras putih dan roti tawar beras berisi kastanye Gongju yang dikupas dan direbus perlahan sendiri oleh pemiliknya."},
  "aaa-bakeshop-gwangju": {"of": "383cdd91", "story": "A.A.A Bakeshop menyebut dirinya sebagai toko kue bebas gluten dan vegan, yang memanggang dengan tepung beras dan menujukan produknya sebagai camilan anak-anak. Ragam produknya mencakup roti garam beras, madeleine, dan Basque cheesecake vegan."},
  "jeju-veggies-hangyeong": {"of": "983f6d2c", "story": "Jeju Veggie's adalah restoran vegetarian yang terinspirasi pola makan Mediterania, menurut penuturannya sendiri, di dekat kebun teh O'sulloc di Jeju bagian barat. Setiap hidangan di menunya diberi label menurut jenisnya: sebagian besar vegan, termasuk bibimbap salad dengan bulgogi nabati, pasta pakis dan perilla, serta hidangan asam manis jeruk keprok, sedangkan beberapa mengandung produk susu atau makanan laut. Tanyakan kepada staf untuk memastikan saat memesan.", "esg": "Memakai pakis Jeju, jeruk keprok, dan perilla yang ditanam sendiri oleh para pemiliknya, sebagaimana diuraikan menunya."},
  "neuadnit-kitchen-jinju": {"of": "68464175", "story": "Neuadnit Kitchen menyajikan satu set makan siang: sepiring hidangan musiman berisi nasi beras cokelat organik, sup, salad, dan beberapa hidangan sayuran musiman. Pemiliknya menyatakan hidangan itu disiapkan vegan atau ovo-vegetarian, jadi tanyakan apakah hidangan hari itu mengandung telur; puding kacang merahnya vegan. Tempat ini hanya buka untuk makan siang, Kamis sampai Minggu, dan hanya menerima reservasi.", "esg": "Menu yang disusun di seputar sayuran musiman."},
  "cafe-walden-cheongdo": {"of": "ad358d21", "story": "Cafe Walden adalah kafe di jalan pegunungan Heolti-ro di Cheongdo. Pemiliknya menggambarkan hidangan penutupnya sebagai vegan dan mudah dicerna; menunya menyebut scone kacang merah vegan dan teh susu vegan buatan sendiri. Tidak semua minuman ditandai vegan, jadi tanyakan."},
  "namusangja-bakery-galma": {"of": "7c2c30cb", "story": "Namusangja Bakery Café membuat roti beragi alami dari gandum Korea dan menyangrai kopinya sendiri. Dua rotinya ditandai vegan pada menu pemiliknya, yaitu campagne buah ara dan ciabatta polos; ragam lainnya mencakup keju dan ham, jadi tanyakan roti mana yang vegan hari itu.", "esg": "Gandum yang ditanam di Korea."},
  "cafe-orsol-songgwang": {"of": "9dcd406e", "story": "Cafe Orsol adalah kafe bertaman di Songgwang-myeon, kecamatan tempat kuil Songgwangsa berada. Pemiliknya menggambarkan hidangan penutupnya sebagai vegan, dan menunya menyebut roti panggang vegan (basil-tomat, apel-kayu manis, selai kacang), hummus tomat vegan, dan latte krim vegan. Latte lainnya tidak menyebutkan susu apa yang dipakai."},
  "la-vie-belle-hadan": {"of": "e4d16564", "story": "La Vie Belle menjual minuman sirop buah buatan sendiri dan tiga jenis hidangan penutup, menurut penuturan pemiliknya: vegan, tinggi protein, dan biasa. Menunya menyebut kukis vegan dan crumble vegan; cheesecake dan tiramisunya tidak vegan."},
  "silktela-munsan": {"of": "f0571420", "story": "Silktela adalah kafe toko roti di Munsan yang memanggang dengan beras dan biji-bijian utuh, menurut penuturan pemiliknya. Tempat ini menjual serangkaian roti sourdough yang disebutnya vegan, antara lain roti enam biji-bijian, campagne gandum hitam, buah ara, dan oatmeal, di samping castella dan kue lain yang tidak vegan."},
  "inmama-ganadang-jangyu": {"of": "8435dde7", "story": "Inmama & Ganadang menjual roti beras dan hidangan penutup vegan, roti lapis, kopi, dan minuman vegan, menurut penuturan pemiliknya. Tidak semuanya vegan, jadi tanyakan produk mana yang vegan."},
  "off-the-cuff-damyang": {"of": "939528e0", "story": "Off the Cuff adalah kafe besar bertaman, yang menurut penuturan pemiliknya merupakan kafe toko roti vegan di Damyang. Produk panggangnya dijual sebagai vegan; menu kopinya tidak menyebutkan susu apa yang dipakai untuk latte."},
  "muffindle-seogwipo": {"of": "70b7f4f4", "story": "Muffindle membuat muffin beras vegan bebas gluten dengan hasil bumi Jeju, menurut penuturan pemiliknya, dan menyajikan kopi single origin. Rasanya antara lain labu kabocha, mugwort dengan tepung kedelai, dan wortel dengan yuja.", "esg": "Muffin dibuat dengan hasil bumi yang ditanam di Jeju, sebagaimana digambarkan pemiliknya."},
  "saluv-allday-yeondong": {"of": "d680cc33", "story": "Saluv All Day adalah kedai poke dan salad di Yeon-dong, Kota Jeju. Sebagian besar mangkuknya mengandung ikan atau daging; menunya menyebut bibim poke all-in-one vegan dan wrap daging kedelai vegan."},
  "rapa-day-ulsan": {"of": "ee39bb57", "story": "Rapa's Day menyebut dirinya sebagai kafe toko roti vegan di Ulsan yang membuat kue vegan, kue beras, roti beras, dan roti bebas gluten. Menu minumannya menawarkan latte kedelai dan latte oat di samping minuman berbahan susu sapi, jadi periksa susunya saat memesan."},
  "brunel-house-ulsan": {"of": "f4da70f8", "story": "Brunel House membuat pound cake vegan rasa cokelat, Earl Grey, dan matcha serta scone, yang dijual utuh atau per potong, dan mengirimkannya sebagai bingkisan."},
  "dohyeondang-haeundae": {"of": "11944caf", "story": "Dohyeondang adalah toko roti organik di jalan tepi pantai Haeundae. Situs tokonya sendiri menyebut serangkaian roti vegan, yaitu roti gandum utuh, gandum hitam, kacang hitam, dan roti beras cokelat bebas gluten, di samping roti lain, camilan, dan bingsu susu yang tidak vegan. Tanyakan di toko, roti mana yang vegan.", "esg": "Biji-bijian organik, sebagaimana toko roti ini menggambarkan rotinya."},
  "momongve-allak": {"of": "6a5616b4", "story": "Momongve Vegan Bakery menyebut dirinya sebagai toko roti vegan. Toko ini menyajikan kopi dan latte bersama produk panggangnya; menu minumannya tidak menyebutkan susu apa yang dipakai untuk latte."},
  "onhwadang-yeonsan": {"of": "0254ff73", "story": "Onhwadang menyebut dirinya sebagai toko roti vegan. Toko ini membuat roti tawar beras, bagel, dan roti bulat; beberapa di antaranya disebut vegan pada menunya, termasuk roti garam beras, roti tawar keju, dan muffin cokelat. Tanyakan tentang produk yang tidak ditandai vegan."},
  "insadodam-insadong": {"of": "9b4d69bf", "story": "Insadodam menyajikan hidangan Korea dan makgeolli di Insadong: bibimbap, galbi babi yang dimasak perlahan, gurita pedas, bulgogi, dan set untuk berbagi. Pemiliknya menandai tiga hidangan di menu sebagai vegan: panekuk renyah minari (seledri air) dan bawang bombai, tahu dan sayuran yang dimasak dalam kukusan, serta rebusan tahu dan jamur dalam kaldu sayuran. Sebagian besar menu memakai daging atau makanan laut, jadi sebutkan nama hidangan vegan itu saat Anda memesan. Tempat ini berjarak sekitar empat menit berjalan kaki dari Stasiun Anguk."},
  "gyejeol-gotgan-haenggung": {"of": "fc86d0bb", "story": "Gyejeol Gotgan membuat gimbap dan salad di dekat gerbang Hwaseomun di Benteng Hwaseong. Pemiliknya menandai beberapa produk dengan VG, yang berarti vegan: gimbap dengan hummus buatan sendiri dan tahu panggang, gimbap tempe, salad hummus dan tempe, serta gangjeong kembang kol dan tahu, yakni gorengan renyah berlapis saus. Gulungan lainnya memakai galbi Suwon, tuna, telur, atau kue ikan, jadi carilah tanda VG. Tidak ada stasiun kereta bawah tanah di dekatnya: Stasiun Maegyo berjarak sekitar 40 menit berjalan kaki, dan sebagian besar pengunjung datang naik bus."},
  "otto-gimbap-gangseo-gucheong": {"of": "c1c48ca2", "story": "Cabang Gangseo dari Otto Gimbap ini membuat gimbap gulung dan ayam goreng Korea. Gimbap tuna vegannya memakai tuna dan mayones nabati dengan selada romaine, daun perilla, acar lobak, mentimun, dan wortel, tanpa telur. Gulungan lainnya mengandung telur, kue ikan, atau Spam. Tempat ini berjarak sekitar 15 menit berjalan kaki dari Stasiun Gayang di Jalur 9."},
  "gyeongdae-kebab-jinju": {"of": "25f59557", "story": "Gyeongdae Kebab membuat kebab ala Turki, nasi mangkuk ala New York, dan snack pack ala Australia, dan menyatakan di situsnya sendiri bahwa semuanya memakai daging sapi dan ayam bersertifikat halal. Pemiliknya, mantan mahasiswa internasional di Gyeongsang National University, menulis bahwa ia membukanya agar mahasiswa Muslim dan orang yang baru mengenal kebab dapat makan di meja yang sama, dan bahwa seorang juru masak kelahiran Uzbekistan memanggang dagingnya. Hingga September 2026 tempat ini beroperasi dengan nama Russian Cakey (러시안케이키), dan situs toko itu sendiri menyebut papan nama toko kue yang lama masih terpasang sampai papan yang baru tiba. Tidak ada sertifikat yang kami lihat, dan menunya tidak mencantumkan alkohol.", "esg": "Kedai dekat universitas yang dikelola pemiliknya sendiri dan menyatakan dagingnya bersertifikat halal."},
  "raj-indian-jeondae-gwangju": {"of": "3d8c6fca", "story": "Raj Indian Restaurant menyebut dirinya pada cantuman petanya sendiri sebagai restoran India yang mencakup makanan halal, vegan, dan ala kuil. Menu yang dicantumkannya mencakup butter chicken, palak paneer, biryani sayuran, ayam tandoori, dan set thali. Restoran ini terletak di dekat gerbang belakang Chonnam National University dan tutup untuk istirahat antara makan siang dan makan malam. Kami belum melihat sertifikat halalnya."},
  "the-halal-oppa-sangsu": {"of": "2c5aca20", "story": "The Halal Oppa, kedai kecil di dekat Stasiun Sangsu, menggambarkan makanannya sendiri sebagai masakan Timur Tengah halal yang autentik, di samping roti lapis dari berbagai penjuru dunia. Menu yang dicantumkannya adalah wrap kebab, baguette, boks, dan hidangan nasi dengan daging ayam, domba, atau campuran, falafel ala Mesir, dan smash burger daging sapi. Kami belum melihat sertifikat halalnya.", "esg": "Pemiliknya menggambarkan makanannya sebagai halal pada cantumannya sendiri."},
  "king-kebab-itaewon": {"of": "66d4dee1", "story": "King Kebab Itaewon, cabang Itaewon dari jaringan King Kebab, menyebut dirinya pada cantumannya sendiri sebagai restoran halal tempat seorang koki Turki membuat kebabnya. Menu yang dicantumkannya berkisar dari wrap kebab ayam dan domba hingga hidangan piring Iskender, Adana daging sapi, dan lamb chop, dan restoran ini dicantumkan buka sepanjang hari dan malam. Kami belum melihat sertifikat halalnya.", "esg": "Pemiliknya menggambarkan restoran ini sebagai halal pada cantumannya sendiri."},
  "atlas-uijeongbu": {"of": "c3ba1f97", "story": "Atlas Uzbek Kitchen, restoran di lantai dua dekat Stasiun Uijeongbu, menyajikan masakan rumahan Uzbekistan buatan seorang koki dari Uzbekistan dan menyebut makanannya halal di kanal Kakao miliknya sendiri. Semuanya dibuat di tempat, dari roti non dan patyr yang berlapis-lapis hingga samsa daging sapi, plov, lagman, dan shashlik daging domba, sapi, atau ayam yang dipanggang dengan arang. Kami belum melihat sertifikat halalnya.", "esg": "Semuanya, termasuk roti, dibuat di tempat."},
  "mahalla-yongin": {"of": "7f9c53b9", "story": "Mahalla Halal Uzbek Restaurant, restoran Uzbekistan di dekat Pasar Yongin Jungang, menyebut dirinya di Instagram miliknya sendiri sebagai restoran Uzbekistan halal. Menu yang dicantumkannya meliputi osh (pilaf), pangsit manti dan chuchvara, beberapa jenis mi lagman, sup daging sapi, ayam tabaka, serta samsa yang dipanggang dalam oven dan tandir. Restoran ini tampaknya dibuka pada September 2026. Kami belum melihat sertifikat halalnya.", "esg": "Pengelolanya menampilkan diri sebagai restoran Uzbekistan halal."},
  "mealans-daeheung": {"of": "97547be2", "story": "Pemilik Mealans menggambarkan tokonya sebagai tempat yang membuat sendiri hidangan penutup vegan dan non-vegan. Yang vegan disebut namanya pada menu: cheesecake gelas bebas gluten, gateau gandum utuh rasa cokelat, almon, matcha, dan labu, cupcake beras, dan muffin gandum utuh. Macaron dan kukisnya tidak diberi label vegan. Tempat ini berjarak sekitar 19 menit berjalan kaki dari Stasiun Daeheung di Jalur 6."},
  "ttangji-veggie-doksan": {"of": "87418255", "story": "Pemilik Earthy Veggie menggambarkan tempat ini sebagai toko roti dan kafe vegan yang hanya memakai bahan nabati. Menunya berpusat pada kukis levain yang dibuat dengan tepung beras atau tepung gandum utuh, dalam rasa keping cokelat hitam, s'more, kacang, dan kranberi, dengan latte oat, limun segar, dan jus musiman. Tempat ini berjarak sekitar 14 menit berjalan kaki dari Stasiun Geumcheon-gu Office di Jalur 1."},
  "nanal-sikppang-haengsin": {"of": "5dae1149", "story": "Nanal Sikppang adalah toko roti kecil yang menjual roti tawar dan menuliskan bahan setiap roti pada menunya. Dua di antaranya diberi label vegan dan dibuat tanpa susu, mentega, atau telur: roti country gandum utuh organik dengan kenari, kismis, dan kranberi, serta roti tawar kenari. Roti lainnya mengandung susu, mentega, atau telur. Tempat ini berjarak empat menit berjalan kaki dari Stasiun Haengsin."},
  "owol-jegwajeom-gimpo": {"of": "46b02247", "story": "Pemilik May Bakery menyatakan toko ini membuat hidangan penutupnya tanpa tepung terigu, telur, atau susu. Menunya menyebut granola vegan dan tuile beras vegan, serta bagel beras yang dibuat dengan mentega vegan, salah satunya diberi topping bawang putih dan mayones vegan. Tempat ini berjarak sekitar 4,4 km berjalan kaki dari Stasiun Yangchon di Gimpo Goldline, jadi lebih mudah naik bus atau taksi."},
  "ppang-hyanghyun-junghwa": {"of": "f8442cf1", "story": "Menu kafe Ppang-ui Hyanghyun menyebut tiga bingsu vegan, yang dibuat dengan 'salju' oat dan kacang merah, wijen hitam, atau teh hijau, beserta kopi susu kelapa vegan dan latte oat. Rotinya tidak dirinci pada menu, dan roti lapis roti garamnya tidak diberi label vegan. Cabang kedua beroperasi di Dasan, Namyangju. Tempat ini berjarak lima menit berjalan kaki dari Stasiun Junghwa di Jalur 7."},
  "ppang-hyanghyun-dasan": {"of": "3bc979d2", "story": "Ppang-ui Hyanghyun Dasan, cabang Ppang-ui Hyanghyun di lantai basemen, mencantumkan roti tawar beras vegan dan madeleine tepung beras vegan pada menunya; ragam produk lainnya tidak dirinci. Tempat ini berjarak sekitar 10 menit berjalan kaki dari Stasiun Donong di Jalur Gyeongui–Jungang."},
  "plat-o-yangjae": {"of": "853f2d0b", "story": "Menu Plat O adalah masakan rumahan Italia tanpa daging atau ikan: polenta, pasta, linguine ragù kacang, risotto jelai hijau dengan pesto namul, ribollita, dan sup wortel yang dibuat dengan susu kedelai. Satu hidangan diberi label vegan, yaitu O:! Burger, yang dibuat dengan daging nabati 'Devotion' dan cheddar vegan. Beberapa hidangan lain memakai mentega, ricotta, atau keju. Tempat ini berjarak sekitar 15 menit berjalan kaki dari Stasiun Yangjae Citizen's Forest di Jalur Shinbundang."},
  "petit-tong-seochon": {"of": "8eade1ee", "story": "Para pemilik Petit Tong menggambarkannya sebagai toko roti Swiss yang dirintis seorang istri asal Korea untuk suaminya yang berkebangsaan Swiss, yang memanggang roti Eropa setiap pagi di Seochon. Menunya menyebut satu hidangan vegan, roti lapis hummus, di samping roti lapis ham, ayam, dan salmon asap, tart Swiss, dan roti gandum hitam. Tempat ini berjarak tujuh menit berjalan kaki dari Stasiun Gyeongbokgung di Jalur 3."},
  "uuum-eatery-dogok": {"of": "00c760d7", "story": "Uuum Eatery & Bakery membuat roti dari biang sourdough miliknya sendiri dan menandai roti yang vegan dengan VG pada menunya: baguette Prancis, campagne kacang merah, mugwort, dan beras ketan, serta ciabatta tomat-herba. Ciabatta lainnya mengandung keju, dan toko ini juga membuat bagel beras bebas gluten dan madeleine. Tempat ini berjarak tujuh menit berjalan kaki dari Stasiun Maebong di Jalur 3."},
  "cafe-songbird-junggye": {"of": "4e6d33fc", "story": "Cafe Songbird berada di lantai basemen Perpustakaan Buram. Menunya menyebut satu produk vegan, roti pizza, di samping kopi, muffin, sup, dan roti lapis yang tidak diberi label vegan. Perpustakaan itu berada di kaki Buramsan, sekitar 2,2 km berjalan kaki dari Stasiun Junggye di Jalur 7, jadi lebih mudah naik bus."},
  "monil2-house-yeonnam": {"of": "0e3fd7cf", "story": "Pemilik Monil-i-ne House menggambarkan tempat ini sebagai toko roti tepung beras yang seluruhnya bebas gluten sekaligus kafe studio, yang juga membuat cokelat bean-to-bar. Menunya menyebut roti garam vegan dijual di samping roti garam beras biasa; roti lainnya bebas gluten tetapi tidak diberi label vegan. Pengumuman pemiliknya untuk musim gugur 2026 mencantumkan hari Rabu sebagai hari tutup. Tempat ini berjarak sekitar 16 menit berjalan kaki dari Stasiun Hongik University."},
  "backstube-395-seogyo": {"of": "c40f0318", "story": "Pemilik 395 Bakery membuat roti sehari-hari ala Jerman dari tepung organik Korea dan Jerman. Enam di antaranya ditandai vegan pada menu: pretzel ala Munich, roti gandum hitam 100%, roti bulat gandum hitam berbiji, roti kenari-aprikot, roti khas toko, dan roti tawar gandum hitam berbiji. Pretzel mentega dan roti bulat mentega-garam tidak ditandai vegan. Tempat ini berjarak enam menit berjalan kaki dari Stasiun Hapjeong."},
  "nuave-gojan-ansan": {"of": "14c4d6ed", "story": "Nuave adalah toko roti kecil yang membuat canelé. Pemiliknya mencantumkan canelé vanila dan basil yang dibuat dengan tepung beras serta canelé zaitun dan keju yang dibuat dengan keju vegan, semuanya digambarkan dibuat tanpa produk susu atau telur. Tempat ini berjarak delapan menit berjalan kaki dari Stasiun Jungang di Jalur 4."},
  "le-pain-de-papa-magok": {"of": "645f14c9", "story": "Pemilik Le Pain de Papa menggambarkan tempat ini sebagai toko roti tempat seorang ayah memanggang dengan 100% tepung beras Korea. Satu-satunya roti yang dicantumkannya, roti country beras truffle, digambarkan sebagai vegan. Toko ini berada di lantai empat Botanic Park Tower 2, sepuluh menit berjalan kaki dari Stasiun Balsan di Jalur 5. Jam bukanya tidak dipublikasikan pada cantuman petanya."},
  "ssalkkakka-jeonju": {"of": "120711d0", "story": "Ssalkkakka membuat roti beras, kue beras, dan camilan panggang tanpa gula dan tanpa tepung terigu. Pemiliknya mencantumkan satu produk vegan, bagel beras tanpa gula yang dibuat dari tepung beras Korea dan gula kelapa, yang disebut toko ini sebagai produk andalannya. Roti dan kue lainnya memakai mentega atau krim susu, jadi tanyakan sebelum memilih yang lain. Catatan jam buka pemiliknya menyebut toko ini buka Rabu sampai Sabtu.", "esg": "Tepung beras Korea sebagai pengganti terigu, sebagaimana digambarkan pemiliknya."},
  "gongmidang-dalmaji": {"of": "c05b87b6", "story": "Gongmidang adalah kafe di jalan Dalmaji di atas Haeundae. Di antara produk panggangnya, pemiliknya memberi label vegan pada dua roti, yaitu ciabatta zaitun gandum utuh dan campagne kranberi gandum utuh, yang digambarkan dibuat tanpa gula, mentega, telur, atau susu dan difermentasi lebih dari 12 jam. Menu lainnya mencakup mentega dan susu, sehingga dua roti berlabel itulah pilihan vegannya."},
  "milkkot-damyang": {"of": "1a605262", "story": "Milkkot adalah toko roti kecil di pedesaan Damyang yang memanggang dengan beras. Pemiliknya mencantumkan roti tawar beras vegan; roti beras mugwortnya tidak diberi label vegan. Toko ini hanya buka pada hari kerja, menurut cantuman Kakao-nya; letaknya jauh dari jalur kereta, jadi rencanakan untuk naik mobil atau bus lokal."},
  "seukkopi-yeonsan": {"of": "aaf7ed3e", "story": "Seukkopi adalah toko roti kecil di Yeonsan-dong yang membuat scone, roti beras, dan kue utuh. Pemiliknya mencantumkan kukis vegan; sebagian besar produk lainnya memakai mentega atau keju. Toko ini tutup pada akhir pekan dan hari libur nasional, menurut cantumannya."},
  "cafe-balcony-ricebread-gimhae": {"of": "c2afc2bd", "story": "Cafe Balcony & Rice Bread membuat roti tawar beras dari beras Korea dan gandum lokal asli. Pemiliknya memberi label vegan pada sekitar selusin produk, di antaranya roti tawar beras polos, bluberi, kenari-kastanye, dan wijen hitam, scone buah ara, dan biscotti kranberi. Roti lainnya mengandung ham, keju, atau keju krim, jadi periksa labelnya.", "esg": "Beras Korea dan gandum lokal asli, sebagaimana pemiliknya menggambarkan rotinya."},
  "uio-field-station-daejeong": {"of": "49ca190e", "story": "UIO Field Station adalah kafe di desa Mureung di Jeju bagian barat. Pemiliknya memberi label vegan pada satu hidangan: 'kotak bekal peneliti Belanda' berisi dua macam hummus dengan baguette dan potongan sayuran; hummusnya juga dijual untuk dibawa pulang. Latte disajikan dengan susu oat kecuali Anda meminta susu sapi. Pesanan terakhir pukul 17:30, menurut catatan pemiliknya.", "esg": "Teh herbal lokal dan jeruk Jeju organik, sebagaimana digambarkan pemiliknya."},
  "sweet-home-oven-naedong": {"of": "8d42af20", "story": "Sweet Home Oven membuat roti yang difermentasi perlahan dengan gandum organik Korea, gandum hitam, dan nuruk beras. Pemiliknya menggambarkan beberapa roti sebagai vegan, yaitu roti tawar gandum utuh nuruk, sourdough gandum hitam dan sourdough kranberi-kenari, cinnamon roll yang dibuat dengan minyak kelapa, scone gandum utuh, dan kukis kacang gandum hitam. Roti lapisnya mengandung ham, keju, dan telur. Pemiliknya mengumumkan hari buka setiap bulan pada cantumannya.", "esg": "Gandum dan gandum hitam organik Korea, sebagaimana pemiliknya menggambarkan rotinya."},
  "nutjimi-bakery-mungyeong": {"of": "e6289db9", "story": "Nutjimi Bakery adalah kafe toko roti besar di Hogye-myeon, Mungyeong. Dari daftar rotinya yang panjang, pemiliknya memberi label vegan pada dua roti: campagne buah ara dan ciabatta zaitun. Sebagian besar roti dan kue lainnya memakai produk susu."},
};
